window.PET_ESSAY_ADV[1] = {"args": {"agree": [{"t": "Sleep & the Teenage Body Clock 睡眠與青少年生理時鐘", "ts": ["Teenagers' body clocks naturally shift later, so an early start forces them to learn while still short of sleep.", "青少年的生理時鐘自然往後延，所以太早上課等於逼他們在睡眠不足的狀態下學習。"], "ex": ["During puberty the brain releases melatonin about two hours later, which makes falling asleep at ten genuinely difficult.", "青春期時大腦分泌褪黑激素的時間大約晚兩小時，因此晚上十點入睡真的很困難。"], "eg": ["The American Academy of Pediatrics recommends that secondary schools start no earlier than 8:30 for exactly this reason.", "美國兒科學會正是基於這個原因，建議中學上課時間不要早於八點半。"], "wu": ["Therefore, a later start simply matches the school day to how adolescent bodies actually work.", "因此，延後上課只是讓學校作息配合青少年身體真正的運作方式。"]}, {"t": "Better Concentration & Grades 專注力與成績", "ts": ["Students who have slept enough concentrate for longer and remember far more of what they are taught.", "睡飽的學生能專注更久，也能記住更多上課內容。"], "ex": ["Sleep is when the brain stores new information, so tired pupils struggle to absorb lessons however hard they try.", "大腦在睡眠時儲存新資訊，所以疲倦的學生再怎麼努力也很難吸收課程內容。"], "eg": ["After Seattle delayed its high-school start time in 2016, students slept over half an hour longer and their grades improved.", "西雅圖在 2016 年延後高中上課時間後，學生多睡了半小時以上，成績也進步了。"], "wu": ["As a result, a later start can raise achievement without adding a single extra lesson.", "因此，延後上課不必多加任何一堂課，就能提升學習成效。"]}, {"t": "Physical & Mental Health 身心健康", "ts": ["Chronic lack of sleep harms teenagers' physical and mental health in ways that extend well beyond the classroom.", "長期睡眠不足對青少年身心健康的傷害，遠遠超出課堂之外。"], "ex": ["Sleep-deprived adolescents are more likely to feel anxious, depressed and irritable, and their immune systems become weaker.", "睡眠不足的青少年比較容易焦慮、憂鬱、煩躁，免疫力也會變差。"], "eg": ["Doctors also link short sleep among teenagers to weight gain and a higher risk of road accidents on the way to school.", "醫師也指出，青少年睡眠過短與體重增加，以及上學途中較高的交通事故風險有關。"], "wu": ["In short, giving students more sleep is a simple, low-cost investment in their long-term physical and mental health.", "簡單來說，讓學生多睡一點是對他們長期身心健康既簡單又低成本的投資。"]}, {"t": "Time for a Proper Breakfast 好好吃早餐的時間", "ts": ["A later start would give students time to eat a proper breakfast instead of rushing out of the door hungry.", "延後上課能讓學生好好吃頓早餐，而不是餓著肚子匆忙出門。"], "ex": ["The brain needs energy to concentrate, and pupils who skip breakfast often feel tired and distracted by mid-morning.", "大腦需要能量才能專注，不吃早餐的學生往往到了上午中段就疲倦又分心。"], "eg": ["Many teenagers currently grab a sugary drink from a convenience store and eat it on the bus or in class.", "目前許多青少年只是在便利商店買杯含糖飲料，在公車上或教室裡隨便解決。"], "wu": ["Thus, an extra half hour in the morning would improve both their diet and their readiness to learn.", "因此，早上多出半小時能同時改善他們的飲食和學習狀態。"]}], "disagree": [{"t": "Later Finish, Less Free Time 放學更晚、自由時間更少", "ts": ["A later start would push the end of the school day back and shrink the time available for other activities.", "延後上課會讓放學時間跟著延後，壓縮其他活動的時間。"], "ex": ["Sports practice, music lessons and part-time jobs would all have to begin later, often after dark.", "運動練習、音樂課和打工都得延後開始，常常要到天黑以後。"], "eg": ["A school day ending at five would leave students with little daylight for outdoor exercise, especially during the winter months.", "如果五點才放學，學生能在戶外運動的白天時間所剩無幾，冬天尤其如此。"], "wu": ["In other words, the time gained in the morning would simply be lost in the evening.", "換句話說，早上多出的時間只是在傍晚被拿走而已。"]}, {"t": "Problems for Working Parents 造成上班父母的困擾", "ts": ["Most parents start work at fixed hours, so a later school day would make family routines far harder to manage.", "大多數父母有固定的上班時間，延後上課會讓家庭作息更難安排。"], "ex": ["Parents who drop children off on the way to work could no longer do so if lessons began at nine.", "如果九點才上課，順路送孩子上學再去上班的父母就沒辦法這麼做了。"], "eg": ["Younger siblings might be left alone at home in the morning, or families might have to pay for extra childcare.", "年幼的弟妹可能早上得獨自在家，或者家庭必須額外花錢請人照顧。"], "wu": ["Consequently, a change meant to help students could place a heavy burden on their families.", "因此，原本想幫助學生的改變，反而可能成為家庭的沉重負擔。"]}, {"t": "Students Will Just Stay Up Later 學生只會更晚睡", "ts": ["If school starts later, many teenagers will simply go to bed later and gain no extra sleep at all.", "如果延後上課，許多青少年只會更晚睡，根本不會多睡到。"], "ex": ["The real causes of late nights are phones, online games and cram school, none of which a timetable change can fix.", "晚睡的真正原因是手機、線上遊戲和補習班，這些都不是改課表能解決的。"], "eg": ["A student who scrolls through videos until one o'clock will be just as tired at nine as at half past seven.", "滑影片滑到半夜一點的學生，九點上課和七點半上課一樣累。"], "wu": ["Therefore, healthy sleep habits at home matter far more than the time at which the first bell rings each morning.", "因此，在家養成良好的睡眠習慣，遠比每天早上第一節鐘響的時間重要。"]}, {"t": "Discipline for Adult Life 為成人生活培養紀律", "ts": ["Getting up early for school teaches young people the discipline and time management they will need in adult life.", "早起上學能培養年輕人成年後需要的紀律與時間管理能力。"], "ex": ["Most workplaces expect employees to arrive on time in the morning, regardless of whether they feel fully awake.", "大多數職場都要求員工早上準時到班，不管他們是否完全清醒。"], "eg": ["Hospital staff, factory workers and teachers themselves often begin their shifts well before eight o'clock.", "醫院人員、工廠員工，甚至老師自己，常常在八點以前就開始上班。"], "wu": ["As a result, an early start can be seen as useful preparation for the realities of working life.", "因此，早上學可以被視為面對職場現實的有用準備。"]}]}, "agree": [["first lesson 7:30 · present but not awake", "**Anyone who has** taught a first lesson at half past seven **will know that** many teenagers arrive physically present but mentally still in bed."], ["start before eight · cram school · calls grow louder", "**With** most secondary schools starting before eight and many pupils attending cram school until late evening, **it is hardly surprising that** calls for a later start have grown louder."], ["stance: agree · biology + learning", "**I firmly agree that** the school day should begin later, **not only because** it would allow adolescents to sleep in line with their biology **but also because** well-rested pupils learn far more effectively."], ["adolescent body clock", "**The most compelling argument concerns** the adolescent body clock."], ["melatonin shifts later · not ready at ten", "During puberty, the release of melatonin shifts roughly two hours later, **which means that** a sixteen-year-old is simply not ready to fall asleep at ten, **however** disciplined he or she **may be**."], ["AAP · no earlier than 8:30 · California law", "**It is for this reason that** the American Academy of Pediatrics recommends that secondary schools begin no earlier than 8:30, **a guideline that** California has since written into law."], ["rising at six = weekly jet lag", "**Forcing** teenagers **to** rise at six, **in other words, amounts to** imposing a mild jet lag on them every weekday."], ["academic benefits", "**Just as important are** the academic benefits of a later start."], ["Seattle 2016 · +30 min sleep · grades up · fewer absences", "**When** Seattle pushed its high-school start time back by almost an hour in 2016, **researchers found that** students slept over half an hour longer and earned better grades, **with** absences and lateness falling too; **far from** being wasted, the extra time translated directly into sharper concentration."], ["concession: end later · squeeze sport & family", "**Critics argue that** a later start **would merely** push the end of the day back, squeezing sport and family time."], ["rebuttal: delay modest · alert hour > two sleepy", "**Yet** a delay of forty-five minutes is modest, and an hour spent alert in class **is surely worth more than** two spent struggling to stay awake."], ["restate: health + learning", "**In conclusion,** the scientific **evidence leaves little doubt that** a later start would benefit both the health and the learning of adolescents."], ["open when minds are awake", "**If** schools exist to help young people learn, **they should** open when young minds are actually awake."]], "disagree": [["sleep in · appealing · overlooked costs", "**Few** school reforms sound as appealing **as** letting teenagers sleep in, **yet few** have consequences that are so easily overlooked."], ["campaigners · sleep research · timetable blamed", "Campaigners **point to** research on adolescent sleep **to argue that** lessons should begin an hour later, **as though** the timetable alone were responsible for exhausted pupils."], ["stance: disagree · family routines + real causes", "**I disagree with this proposal, since** a later start would disrupt family routines **and, more importantly,** do little to tackle the real causes of sleep deprivation."], ["practical costs", "**The practical costs alone are** considerable."], ["working parents · unsupervised mornings · late dismissal", "**In most** households both parents work fixed hours, **so** a school day beginning at nine **would leave** younger pupils unsupervised in the morning and push dismissal well into the late afternoon."], ["sport · music · part-time jobs → evening", "Sports training, music lessons and part-time jobs **would all be squeezed into** the evening, **leaving** teenagers **with** less daylight and no more rest than before."], ["gift of time = reshuffle", "**What appears to be** a gift of time, **then, is in fact** merely a reshuffling of it."], ["screens at night", "**A deeper problem is that** later bells do nothing to curb late-night screen use."], ["phones · gaming · cram school · bedtime shifts · consistency", "**Unless** smartphones, gaming and late cram-school classes **are brought under control,** many teenagers will simply go to bed an hour later, **cancelling out** any benefit; **indeed,** sleep specialists themselves stress that regular bedtimes and screen-free evenings **matter at least as much as** the hour at which lessons begin."], ["concession: some districts · better attendance", "**Admittedly,** some districts **that have** delayed their start times **have reported** modest gains in attendance."], ["rebuttal: local conditions · cheaper fixes", "**However, such results depend heavily on** local conditions, and similar improvements **could be achieved far more cheaply by** limiting homework and educating families about healthy sleep."], ["restate: keep start times · fix habits", "**For these reasons, I remain convinced that** schools should keep their current start times **while** addressing the habits that keep pupils awake."], ["bedroom, not school bell", "**The solution to** tired teenagers **lies not in** the school bell **but in** the bedroom."]], "vocab": [["sleep deprivation", "睡眠不足"], ["adolescent", "青少年的；青少年"], ["body clock", "生理時鐘"], ["concentration", "專注力"], ["unsupervised", "無人看管的"], ["dismissal", "放學"], ["reshuffling", "重新調整、洗牌"], ["cancel out", "抵銷"]]};

window.PET_ESSAY_ADV[2] = {"args": {"agree": [{"t": "Addiction by Design 被設計成讓人上癮", "ts": ["Many apps are deliberately designed to keep users scrolling, and young children have very little ability to resist them.", "許多 App 是刻意設計來讓使用者一直滑下去的，而年幼的孩子幾乎沒有抵抗能力。"], "ex": ["Features such as autoplay, infinite feeds and rewards for daily use exploit the brain's natural desire for novelty.", "自動播放、無限動態和每日使用獎勵等功能，利用了大腦天生追求新鮮感的特性。"], "eg": ["Even adults admit they reach for their phones dozens of times a day without consciously deciding to do so.", "連大人都承認自己一天會不自覺地拿起手機好幾十次。"], "wu": ["Therefore, giving a young child a smartphone is like handing them a product built to be hard to put down.", "因此，給年幼的孩子一支智慧型手機，就等於給他們一個刻意設計成難以放下的產品。"]}, {"t": "Online Dangers 網路危險", "ts": ["A private smartphone exposes children to online dangers that they are too young to recognise or handle.", "一支私人智慧型手機會讓孩子接觸到他們年紀太小、無法辨識或應付的網路危險。"], "ex": ["Without an adult nearby, children may see violent content, share personal information or chat with strangers.", "沒有大人在身邊時，孩子可能看到暴力內容、洩露個人資料或和陌生人聊天。"], "eg": ["Police in many countries warn that predators often pose as children in games and messaging apps to gain trust.", "許多國家的警方都警告，不法分子常在遊戲和通訊軟體裡假扮成孩子來取得信任。"], "wu": ["In short, a phone in a child's bedroom opens a door that parents cannot fully watch.", "簡單來說，孩子房間裡的一支手機，打開了一扇父母無法完全看守的門。"]}, {"t": "Development & Sleep 發展與睡眠", "ts": ["Heavy screen use can interfere with children's sleep, physical activity and face-to-face social development during their most important years.", "大量使用螢幕會在孩子最關鍵的成長階段，影響他們的睡眠、身體活動和面對面的社交發展。"], "ex": ["The light from screens delays sleep, and hours spent on a phone replace outdoor play and real conversation.", "螢幕的光會延後入睡時間，而花在手機上的時間也取代了戶外遊戲和真實的交談。"], "eg": ["Eye doctors in Taiwan have long warned that rising rates of short-sightedness among young children are linked to close-up screen time.", "台灣的眼科醫師一直警告，幼童近視率上升與長時間近距離看螢幕有關。"], "wu": ["Consequently, delaying smartphone ownership until secondary school helps protect the healthy growth of both body and mind.", "因此，把擁有智慧型手機的時間延到國中以後，有助於保護孩子身心的健康成長。"]}, {"t": "A Basic Phone Is Enough 基本手機就夠了", "ts": ["Children who need to contact their parents can use a basic phone that only makes calls and sends texts.", "需要聯絡父母的孩子，可以使用只能打電話和傳簡訊的基本款手機。"], "ex": ["Such phones meet every genuine safety need without providing access to social media, games or video platforms.", "這種手機能滿足所有真正的安全需求，卻不會提供社群媒體、遊戲或影音平台的使用管道。"], "eg": ["A simple handset costs far less than a smartphone and is much less attractive to thieves at school.", "基本款手機比智慧型手機便宜得多，在學校也比較不會被偷。"], "wu": ["Thus, families can keep their children reachable without exposing them to the risks of a smartphone.", "因此，家庭可以隨時聯絡得到孩子，又不必讓他們承受智慧型手機的風險。"]}], "disagree": [{"t": "Safety & Contact 安全與聯絡", "ts": ["A smartphone allows children to contact their parents immediately whenever they feel lost, unwell or in danger.", "智慧型手機讓孩子在迷路、身體不適或遇到危險時，能立刻聯絡父母。"], "ex": ["Many children now travel to school and after-school classes alone, so a reliable way to call home is important.", "許多孩子現在獨自上下學和去課後班，所以能可靠地打電話回家很重要。"], "eg": ["Location-sharing features let parents see that a child has arrived safely without having to phone them repeatedly.", "位置分享功能讓父母不必一直打電話，也能確認孩子已經平安抵達。"], "wu": ["Therefore, for many families, a smartphone acts as a reassuring safety net rather than a source of danger.", "因此，對許多家庭來說，智慧型手機是一張令人安心的安全網，而不是危險的來源。"]}, {"t": "A Powerful Learning Tool 強大的學習工具", "ts": ["Smartphones give children instant access to dictionaries, educational videos and learning apps wherever they are.", "智慧型手機讓孩子無論身在何處，都能立即使用字典、教育影片和學習 App。"], "ex": ["Curious children can look up answers to their own questions and practise skills in short, enjoyable sessions.", "好奇的孩子可以自己查詢問題的答案，並利用短暫又有趣的時間練習技能。"], "eg": ["Language apps such as Duolingo allow a child to practise English for ten minutes on the bus every day.", "像 Duolingo 這樣的語言 App，讓孩子每天在公車上就能練習十分鐘英文。"], "wu": ["As a result, a phone used wisely can extend learning far beyond the walls of the classroom.", "因此，善用手機能讓學習延伸到教室之外。"]}, {"t": "Digital Skills for the Future 未來的數位能力", "ts": ["Children need to develop digital skills early because almost every future job will require them.", "孩子需要及早培養數位能力，因為未來幾乎每一份工作都會用到。"], "ex": ["Learning to search effectively, judge whether information is reliable and communicate politely online takes years of practice.", "學會有效搜尋、判斷資訊是否可靠，以及在網路上有禮貌地溝通，都需要多年的練習。"], "eg": ["A child who learns to spot a fake advertisement at ten is better protected than one who meets the internet alone at fifteen.", "十歲就學會辨識假廣告的孩子，比十五歲才獨自面對網路的孩子更有保障。"], "wu": ["In other words, early guided use prepares children for the digital world instead of leaving them unprepared.", "換句話說，在引導下及早使用能讓孩子為數位世界做好準備，而不是毫無準備。"]}, {"t": "Rules, Not the Device 重點是規範而非裝置", "ts": ["The real issue is how children use smartphones, which parents can control with clear rules and settings.", "真正的問題在於孩子如何使用智慧型手機，而父母可以用明確的規則和設定來控制。"], "ex": ["Parental controls can block unsuitable content, limit daily screen time and switch the phone off at bedtime.", "家長監護功能可以封鎖不適當的內容、限制每日使用時間，並在睡前自動關閉手機。"], "eg": ["Many families agree that phones stay in the living room overnight and are never used during meals.", "許多家庭會約定手機晚上放在客廳，吃飯時也絕不使用。"], "wu": ["Consequently, sensible supervision at home makes a total ban both unnecessary and, in the long run, counterproductive.", "因此，只要家中有合理的監督，全面禁止不但沒有必要，長遠來看還會適得其反。"]}]}, "agree": [["restaurant · child staring at screen", "**It has become a familiar sight:** a young child at a restaurant table, eyes fixed on a glowing screen **while** the adults around them talk."], ["cheaper phones · first device younger · parents question", "**As** smartphones **have become** cheaper, the age at which children receive their first device has fallen steadily, **prompting** a growing number of parents **to question whether** this is wise."], ["stance: agree · addictive design + risks", "**I strongly agree that** children under twelve should not have smartphones of their own, **as** these devices **are engineered to** be habit-forming and expose young users to risks they cannot yet manage."], ["design of the apps", "**The first concern is** the deliberate design of the apps themselves."], ["infinite scroll · autoplay · streaks", "Features **such as** infinite scrolling, autoplay and daily streaks **are built to** maximise screen time, and **even** adults **struggle to** resist them."], ["Bill Gates · no phone until 14", "**It is telling that** Bill Gates has said his own children did not receive a phone until they were fourteen, **a fact that speaks volumes about** what the industry knows."], ["adults can't resist → child stands little chance", "**If even** adults find these products hard to put down, a nine-year-old **stands little chance**."], ["dangers in the bedroom", "**Equally worrying are** the dangers a smartphone brings into a child's bedroom."], ["private device · parents can't see · violent content · strangers", "**Once** a child owns a private, internet-connected device, parents **can no longer** see who is contacting them or what they are watching; **not only may** children stumble upon violent or sexual content within a few taps, **but** they **may also** be approached by strangers posing as peers."], ["concession: need to contact parents", "**It might be argued that** children need a phone to stay in touch with their parents."], ["rebuttal: basic handset · calls & texts", "**Yet** a basic handset **that** makes calls and sends texts **fulfils this purpose perfectly well without** opening the door to social media and endless video."], ["restate: risks outweigh benefits", "**On balance, then, I am convinced that the risks of** giving young children smartphones **far outweigh** the benefits."], ["childhood too short for screens", "Childhood **is too** short **to be** spent staring at a screen."]], "disagree": [["tickets · homework · menus online", "**In a world where** train tickets, homework platforms and even restaurant menus have moved online, a childhood without smartphones **is becoming** difficult to imagine."], ["parents & policymakers · keep away", "**Nevertheless,** some parents and policymakers **have called for** children under twelve **to be kept away from** smartphones entirely, on the grounds that the devices are simply too risky."], ["stance: disagree · safety + learning · with rules", "**I disagree with such a ban, because** a smartphone can keep children safe and support their learning, **provided that** parents set clear limits on its use."], ["safety", "**The most immediate benefit is** safety."], ["travel alone · call parent instantly", "**Many** children now travel to school or to after-school classes on their own, and a phone **allows** them **to** call a parent **the moment** something goes wrong."], ["location sharing · reassurance", "Location-sharing features, **moreover, mean that** parents can check a child's whereabouts **without** constant calls, which offers reassurance to the whole family."], ["not danger → safety net", "**Rather than** a source of danger, **then,** a phone **can serve as** a safety net for parents and children alike."], ["powerful learning tool", "A smartphone **is also** a powerful tool **for** learning, provided it is used with purpose."], ["Duolingo · dictionaries · maps · digital literacy", "**From** language apps such as Duolingo **to** online dictionaries and educational videos, a phone **puts** an enormous range of resources **in** a child's pocket; **what is more,** searching, evaluating and communicating responsibly online is a skill children will need throughout their lives, **and one best acquired** gradually under adult guidance."], ["concession: unrestricted access = addictive apps", "**Of course,** unrestricted access **would expose** young children **to** addictive apps and inappropriate content, just as critics fear."], ["rebuttal: rules not prohibition · parental controls", "**This, however, is an argument for** rules, **not** prohibition: parental controls such as screen-time limits and content filters let families decide exactly what a child can use, and when."], ["restate: allowed · supervised", "**In conclusion, I believe** children under twelve **should be allowed to** own smartphones, **as long as** their use is carefully supervised."], ["control technology, not ignore it", "**The goal should be to** teach children to control technology, **not to** pretend it does not exist."]], "vocab": [["habit-forming", "容易成癮的"], ["infinite scrolling", "無限滾動"], ["speak volumes about", "充分說明"], ["stumble upon", "無意間碰到"], ["inappropriate content", "不當內容"], ["whereabouts", "行蹤、下落"], ["parental controls", "家長監護功能"], ["prohibition", "禁止、禁令"]]};

window.PET_ESSAY_ADV[3] = {"args": {"agree": [{"t": "Equality & Less Bullying 平等、減少霸凌", "ts": ["Uniforms reduce visible differences in wealth, so students are less likely to be judged or teased for their clothes.", "制服減少了外表上的貧富差距，學生比較不會因為穿著而被評斷或嘲笑。"], "ex": ["When everyone dresses the same way, expensive brands cannot be used to show off or to exclude others.", "當大家穿著一樣時，昂貴的名牌就無法用來炫耀或排擠別人。"], "eg": ["Without uniforms, a pair of designer trainers can quickly become a symbol of status in a junior high classroom.", "如果沒有制服，一雙名牌球鞋很快就會成為國中教室裡的身分象徵。"], "wu": ["Therefore, uniforms help every student feel that they truly belong, whatever their family background or income.", "因此，不論家庭背景或收入如何，制服都能讓每位學生真正感到有歸屬感。"]}, {"t": "Saves Time and Money 省時省錢", "ts": ["Uniforms remove the daily problem of choosing what to wear and are cheaper than a wardrobe of fashionable clothes.", "制服解決了每天選衣服的麻煩，也比一整櫃時髦衣服便宜。"], "ex": ["Students can get ready quickly in the morning, and parents are not pressured to buy the latest trends.", "學生早上可以很快準備好，父母也不必被迫購買最新流行的服飾。"], "eg": ["A few durable sets of uniform can last a whole school year, whereas fashion trends change every season.", "幾套耐穿的制服可以穿一整個學年，而流行趨勢卻每季都在變。"], "wu": ["As a result, uniforms make school life simpler and more affordable for many ordinary families.", "因此，制服讓許多一般家庭的校園生活更單純、負擔也更輕。"]}, {"t": "School Identity & Safety 學校認同與安全", "ts": ["Uniforms create a sense of school identity and make it easier for teachers to keep students safe.", "制服能建立學校認同感，也讓老師更容易保護學生的安全。"], "ex": ["Wearing the same uniform reminds students that they represent their school, which encourages good behaviour in public.", "穿著相同的制服提醒學生自己代表學校，能鼓勵他們在公共場所表現良好。"], "eg": ["On a school trip to a crowded museum, teachers can spot their own students instantly among hundreds of visitors.", "在擁擠的博物館校外教學時，老師可以在數百名遊客中一眼認出自己的學生。"], "wu": ["In short, uniforms strengthen students' pride in their school while also making them easier to protect outside it.", "簡單來說，制服能增強學生對學校的榮譽感，同時也讓他們在校外更容易受到保護。"]}, {"t": "Focus on Learning, Not Fashion 專注學習而非時尚", "ts": ["Uniforms create a serious atmosphere in which students concentrate on their studies rather than their appearance.", "制服營造出認真的氛圍，讓學生專注於課業而不是外表。"], "ex": ["A shared dress code signals that school is a place of work, much as a suit does in an office.", "統一的服裝規定傳達出學校是用功的地方，就像辦公室裡的西裝一樣。"], "eg": ["Teachers often notice that classes become noisier and more distracted on days when students may wear casual clothes.", "老師常發現，在可以穿便服的日子，班上會變得比較吵、也比較不專心。"], "wu": ["Thus, uniforms help students switch into a learning mindset the moment they arrive at school each morning.", "因此，制服幫助學生每天早上一到學校就進入學習狀態。"]}], "disagree": [{"t": "Freedom of Expression 表達自由", "ts": ["Uniforms prevent teenagers from expressing their personality at an age when they are discovering who they are.", "制服讓青少年在探索自我的年紀，無法展現自己的個性。"], "ex": ["Choosing what to wear is one of the few everyday decisions through which young people can show their identity.", "選擇穿什麼，是年輕人能展現自我認同的少數日常決定之一。"], "eg": ["In much of continental Europe students wear their own clothes, and schools there function perfectly well.", "在歐洲大陸許多地方，學生都穿自己的衣服，學校也運作得很好。"], "wu": ["Therefore, compulsory uniforms place conformity above the very individuality that schools claim they want to encourage in students.", "因此，強制穿制服把整齊劃一置於學校聲稱想鼓勵的個人特色之上。"]}, {"t": "Comfort and Climate 舒適與氣候", "ts": ["Many school uniforms are uncomfortable to wear and poorly suited to Taiwan's hot and humid climate.", "許多學校制服穿起來不舒服，也不適合台灣炎熱潮濕的氣候。"], "ex": ["Thick polyester fabric traps heat, so students may feel sticky and tired during long summer afternoons.", "厚重的聚酯纖維布料不透氣，學生在漫長的夏日午後容易又黏又累。"], "eg": ["Students who are allowed to wear light cotton T-shirts can usually concentrate better in a classroom without air conditioning.", "能穿輕薄棉質 T 恤的學生，在沒有冷氣的教室裡通常比較能專心。"], "wu": ["As a result, allowing comfortable clothing would support learning rather than distract from it, especially in summer.", "因此，允許穿著舒適的服裝反而有助於學習，而不是讓人分心，夏天尤其如此。"]}, {"t": "Hidden Costs 隱藏成本", "ts": ["Uniforms are often more expensive than they first appear, which places a burden on low-income families.", "制服常常比表面上看起來更貴，造成低收入家庭的負擔。"], "ex": ["Families must buy several sets for summer, winter and PE, usually from a single approved supplier.", "家庭必須購買夏季、冬季和體育服等好幾套制服，而且通常只能向指定廠商購買。"], "eg": ["A growing child may need a completely new set every year, and these clothes cannot be worn outside school.", "正在長高的孩子可能每年都需要整套新制服，而且這些衣服在校外也穿不到。"], "wu": ["In other words, the popular claim that uniforms save families money is often untrue for those who need savings most.", "換句話說，「制服能幫家庭省錢」這個常見說法，對最需要省錢的家庭來說往往不成立。"]}, {"t": "Equality Is Only Skin-Deep 平等只是表面", "ts": ["Uniforms hide differences in wealth only on the surface, because students still compare other possessions.", "制服只是表面上隱藏了貧富差距，因為學生仍會比較其他物品。"], "ex": ["Expensive phones, trainers, bags and watches still reveal which families have money and which do not.", "昂貴的手機、球鞋、書包和手錶，仍然會透露出誰家有錢、誰家沒錢。"], "eg": ["Bullying in schools with strict uniform rules often simply shifts to the brand of a student's phone or shoes.", "在制服規定嚴格的學校，霸凌往往只是轉移到學生手機或鞋子的品牌上。"], "wu": ["Consequently, real equality depends on a respectful school culture rather than on making everyone wear identical clothing.", "因此，真正的平等取決於互相尊重的校園文化，而不是讓每個人穿一樣的衣服。"]}]}, "agree": [["weekday morning · identical shirts", "**Walk past** almost any secondary school in Taiwan on a weekday morning **and you will see** hundreds of pupils in identical shirts and trousers."], ["schools relax dress codes · debate", "**In recent years, however,** a number of schools have relaxed their dress codes, **reigniting the debate over whether** uniforms still belong in modern education."], ["stance: agree · equality + focus", "**I am firmly of the opinion that** all students should wear uniforms, **since** they reduce visible inequality and allow pupils to concentrate on learning **rather than** appearance."], ["equality", "**The strongest argument in their favour is** equality."], ["clothes = wealth · designer trainers · haves vs have-nots", "**Where** students **are free to** wear what they like, clothing **quickly becomes** a marker of wealth, **with** designer trainers and branded hoodies separating those who can afford them from those who cannot."], ["UK · Japan · less teasing & fashion pressure", "**This is precisely why** countries such as the United Kingdom and Japan **have long regarded** uniforms **as a way of** reducing teasing and fashion-related peer pressure."], ["remove comparison · belonging", "**By removing** one obvious source of comparison, uniforms **help** every pupil **feel that** they belong."], ["environment for study", "Uniforms **also create an environment that is better suited to** study."], ["no morning decisions · standards like office suit · trips & safety", "**Instead of** deciding what to wear each morning, students arrive ready to work, and a shared dress code signals that school has its own standards, **much as** a suit does in an office; **on** school trips, **moreover,** teachers can spot their pupils instantly in a crowd, **which is no small advantage for** safety."], ["concession: suppress individuality", "**Critics claim that** uniforms suppress individuality."], ["rebuttal: ideas · hobbies · weekend clothes", "**Yet** self-expression **hardly depends on** clothing alone, and students **remain free to** express themselves through their ideas, hobbies and work, **as well as** in what they wear at weekends."], ["restate: equality · focus · safety", "**In conclusion, because** uniforms promote equality, focus and safety, **I believe they should remain** a standard part of school life."], ["think, not wear", "**What matters at** school **is** what students think, **not** what they wear."]], "disagree": [["humid July · polyester · nothing to do with learning", "**Anyone who has sat through** a humid July afternoon in a thick polyester uniform **will know how little** it has to do with learning."], ["Taiwan tradition · continental Europe none", "**While** uniforms **have long been** a feature of schools in Taiwan, much of continental Europe **has never required** them, and its students appear to learn just as well."], ["stance: disagree · expression + equality illusion", "**I therefore disagree that** all students should wear uniforms, **because** they restrict self-expression and the equality they promise **is largely an illusion**."], ["personal freedom", "**My first objection concerns** personal freedom, a value schools are supposed to nurture."], ["adolescence · identity · self-presentation", "Adolescence **is a period in which** young people are working out who they are, and choosing how to present themselves **is a natural part of that process,** not a distraction from it."], ["dress identically · conformity · creativity", "**Requiring** teenagers **to** dress identically for eight hours a day **sends the message that** conformity matters more than individuality, **a lesson at odds with** the creativity schools claim to value."], ["clothing = responsible choice", "Clothing, **in short, is one of the few areas in which** teenagers can exercise responsible choice."], ["inequality not removed", "**Nor do** uniforms **genuinely** eliminate inequality, despite the claims made on their behalf."], ["phones · trainers · bags · several sets · single supplier · cost", "Wealthier pupils **still** stand out **through** their phones, trainers and bags, **so** the differences simply move elsewhere; **meanwhile, the cost of** buying separate summer, winter and sports uniforms, **which** must often come from a single approved supplier, **can place** a considerable **burden on** low-income families."], ["concession: saves time", "**It is true that** uniforms save time on busy mornings and give schools a tidy, orderly appearance."], ["rebuttal: simple dress code · same order + comfort", "**However,** a simple dress code banning offensive slogans or unsafe footwear **would achieve** the same order **while** allowing students both comfort and choice."], ["restate: abandon compulsory uniforms", "**For these reasons, I believe** schools should abandon compulsory uniforms **in favour of** sensible, flexible guidelines."], ["respect = trust", "**Respecting** students **begins with** trusting them to dress themselves, and most are more than capable of doing so."]], "vocab": [["dress code", "服裝規定"], ["marker of wealth", "財富的標誌"], ["peer pressure", "同儕壓力"], ["conformity", "從眾、整齊劃一"], ["individuality", "個人特色"], ["at odds with", "與……相矛盾"], ["approved supplier", "指定供應商"], ["in favour of", "以……取代；支持"]]};

window.PET_ESSAY_ADV[4] = {"args": {"agree": [{"t": "Stress and Sleep 壓力與睡眠", "ts": ["Excessive homework leaves students exhausted, anxious and short of sleep after an already long school day.", "過多的作業讓學生在本來就很長的上課日之後，更加疲憊、焦慮又睡不夠。"], "ex": ["When homework stretches past midnight, the brain has too little time to rest and recover for the next day.", "當作業寫到超過午夜，大腦就沒有足夠的時間休息，為隔天恢復精神。"], "eg": ["A Stanford study found that pupils doing over three hours of homework a night reported more stress and health problems.", "史丹佛大學的研究發現，每晚寫作業超過三小時的學生回報有較多壓力與健康問題。"], "wu": ["Therefore, reducing homework would protect students' wellbeing as well as their long-term ability to learn.", "因此，減少作業既能保護學生的身心健康，也能保護他們長期的學習能力。"]}, {"t": "Quality Beats Quantity 質重於量", "ts": ["Beyond a certain amount, extra homework adds very little to what students actually learn and remember.", "超過一定的量之後，額外的作業對學生真正學到和記住的東西幾乎沒有幫助。"], "ex": ["Tired students work slowly, make more mistakes and often complete tasks mechanically without real understanding.", "疲倦的學生做得慢、錯得多，常常只是機械式地完成作業而沒有真正理解。"], "eg": ["Research by Harris Cooper suggests that the benefits of homework for older students level off at around two hours a night.", "Harris Cooper 的研究指出，高年級學生寫作業的效益大約在每晚兩小時後就趨於平緩。"], "wu": ["In short, a few well-designed tasks are worth more than a pile of repetitive worksheets.", "簡單來說，幾份設計良好的作業，比一大疊重複的練習卷更有價值。"]}, {"t": "Time for Other Skills 培養其他能力的時間", "ts": ["Less homework would give students time to develop skills and interests that schoolwork cannot teach.", "減少作業能讓學生有時間培養課業教不到的能力和興趣。"], "ex": ["Activities such as sport, music, reading for pleasure and volunteering build creativity, teamwork and self-confidence.", "運動、音樂、閱讀課外書和當志工等活動，都能培養創造力、團隊合作和自信心。"], "eg": ["A student who joins a basketball team or an orchestra learns cooperation and commitment in a way no worksheet can teach.", "加入籃球隊或管弦樂團的學生，能學到練習卷教不來的合作精神和責任感。"], "wu": ["As a result, students would have the chance to grow into more balanced, healthy and well-rounded young people.", "因此，學生將有機會成長為更均衡、健康且全面發展的年輕人。"]}, {"t": "Copying Is Not Learning 抄寫不是學習", "ts": ["When students are overloaded, they often copy answers simply to finish on time rather than to learn.", "學生作業過多時，常常只是為了準時交而抄答案，而不是為了學習。"], "ex": ["Copying from classmates or answer apps produces neat pages but no genuine understanding of the material.", "抄同學的或用解答 App 抄來的作業雖然整齊，卻對內容沒有真正的理解。"], "eg": ["Teachers frequently find that the same students who hand in perfect homework perform poorly in tests.", "老師常發現，交出完美作業的學生，考試成績卻不理想。"], "wu": ["Thus, smaller amounts of meaningful homework would encourage honest effort and real learning instead of mindless copying.", "因此，適量而有意義的作業才能鼓勵學生誠實努力、真正學習，而不是盲目抄寫。"]}], "disagree": [{"t": "Practice Makes Permanent 練習才會牢固", "ts": ["Homework gives students the practice they need to turn new knowledge into lasting, usable skills.", "作業給學生必要的練習，把新知識轉化為牢固且實用的能力。"], "ex": ["A lesson introduces an idea, but students only master it after using it independently several times.", "一堂課只是介紹概念，學生必須自己運用好幾次之後才能真正掌握。"], "eg": ["In mathematics and languages, a forty-minute lesson is rarely enough to make a new formula or grammar pattern automatic.", "在數學和語言科目上，四十分鐘的課很少足以讓新公式或文法句型變得熟練自然。"], "wu": ["Therefore, homework plays an essential role in turning short-term exposure in class into genuine long-term understanding.", "因此，作業在把課堂上的短暫接觸轉化為真正的長期理解上，扮演不可或缺的角色。"]}, {"t": "Responsibility & Time Management 責任感與時間管理", "ts": ["Regular homework teaches students to take responsibility for their own learning and manage their time.", "規律的作業能教導學生為自己的學習負責，並管理自己的時間。"], "ex": ["Students must plan ahead, set priorities and meet deadlines without a teacher standing over them.", "學生必須事先規劃、排定優先順序，在沒有老師盯著的情況下準時完成。"], "eg": ["University students and employees are expected to complete long projects independently, often with several deadlines at once.", "大學生和上班族都被期待能獨立完成長期專案，而且常常同時面對好幾個截止期限。"], "wu": ["As a result, homework prepares young people for the demands of higher education and work.", "因此，作業能讓年輕人為高等教育和職場的要求做好準備。"]}, {"t": "Free Time Is Not Always Used Wisely 自由時間未必被善用", "ts": ["Without homework, many students would not spend their extra time on sport or reading, but on screens.", "如果沒有作業，許多學生不會把多出來的時間拿去運動或閱讀，而是拿去看螢幕。"], "ex": ["Teenagers are naturally drawn to games, videos and social media, which are designed to hold their attention.", "青少年天生容易被遊戲、影片和社群媒體吸引，而這些本來就是設計來抓住注意力的。"], "eg": ["Surveys of teenagers' screen time regularly show that many already spend several hours a day on entertainment apps.", "針對青少年螢幕使用時間的調查經常顯示，許多人每天已經花好幾個小時在娛樂 App 上。"], "wu": ["In other words, cutting homework would not automatically lead to healthier or more productive evenings.", "換句話說，減少作業並不會自動讓晚上的時間變得更健康或更有意義。"]}, {"t": "Preparation for Exams 為考試做準備", "ts": ["Homework helps students review regularly, which is essential in an education system built around important exams.", "作業幫助學生定期複習，這在以重要考試為主的教育體制中十分必要。"], "ex": ["Reviewing a little every day is far more effective than trying to learn everything the week before a test.", "每天複習一點，遠比考前一週才拼命塞進所有內容有效得多。"], "eg": ["Students preparing for the Comprehensive Assessment Program cannot cover three years of material in class time alone.", "準備會考的學生，光靠上課時間無法讀完三年的內容。"], "wu": ["Consequently, a steady amount of homework reduces last-minute panic before exams and usually leads to better results.", "因此，穩定的作業量能減少考前臨時抱佛腳的慌亂，通常也能帶來更好的成績。"]}]}, "agree": [["11 p.m. · still at desks", "**It is** eleven o'clock at night, **and** across the country, countless teenagers **are still** bent over their desks, long after their parents have gone to bed."], ["8 hours school · cram school · worksheets before sleep", "**Having already** spent eight hours at school and often several more at cram school, they face a pile of worksheets **before** they can finally sleep."], ["stance: agree · wellbeing + little gain", "**I agree that** schools should assign less homework, **because** excessive amounts damage students' wellbeing **and add surprisingly little to** their learning."], ["toll on health", "**The most serious consequence is** the toll on health, both physical and mental."], ["past midnight · lost sleep · anxious · poor focus", "**When** homework **routinely** stretches past midnight, students lose the sleep their developing brains need, **leaving** them anxious, irritable and less able to concentrate the next day."], ["Stanford study · 3+ hours · stress, headaches", "**A** Stanford University **study of** high-achieving schools **found that** pupils doing more than three hours of homework a night reported higher stress, headaches and sleep problems."], ["exhausted = poor learners", "Exhausted students, **in other words,** are poor learners, no matter how many hours they log at their desks."], ["beyond a point · little reward", "**Beyond a certain point, moreover,** extra homework **brings little** academic reward, however diligently it is completed."], ["Harris Cooper · ~2 hours plateau · Finland light homework", "**Research by** the psychologist Harris Cooper **suggests that** the benefits of homework level off at around two hours a night for older students, **while** Finland, **where** homework loads are comparatively light, **has long** performed well internationally; **what matters, it seems, is** the quality of a task, **not** the time it consumes."], ["concession: students idle", "**Some parents fear that** reducing homework would leave students idle, drifting aimlessly between screens."], ["rebuttal: reading · sport · music · rest", "**On the contrary,** the time freed **could be devoted to** reading, sport, music or simply rest, **all of which** develop qualities that worksheets cannot."], ["restate: less but better", "**In conclusion, I believe that** less, but better-designed, homework **would leave** students healthier, more motivated and, paradoxically, better educated."], ["more ≠ better · cost of sleep", "**More is not always better, particularly when** it comes at the cost of sleep, health and the joy of learning itself."]], "disagree": [["every generation complains · no lasting harm", "**Every generation of** students **has complained about** homework, **yet few** adults **would claim that** it did them any lasting harm; many, in fact, credit it with their success."], ["educators · cut drastically · Finland", "**Recently, however,** some educators **have called for** homework **to be** drastically reduced, **often pointing to** Finland **as** a model."], ["stance: disagree · consolidation + self-discipline", "**I disagree with this view, since** regular homework **is essential for** consolidating skills and fosters the self-discipline that students will need later in life."], ["learning requires practice", "**The first reason is that** learning requires practice, and the classroom alone rarely provides enough of it."], ["clear explanation ≠ mastery · apply · mistakes", "**However** clearly a teacher explains a concept, students **do not truly** master it **until** they have applied it independently, making mistakes and correcting them along the way."], ["maths · languages · 40 minutes not enough", "**This is particularly true of** mathematics and languages, **where** a forty-minute lesson **is rarely enough to** make a new formula or grammar pattern automatic."], ["exposure → lasting understanding", "Homework **thus turns** brief exposure **into** lasting understanding, in much the same way that training turns talent into skill."], ["responsibility", "**Equally valuable is** the sense of responsibility **that** homework cultivates."], ["deadlines · plan · prioritise · university expectations", "**Faced with** several assignments and fixed deadlines, students **must learn to** plan their time, set priorities and work without supervision, **precisely the skills that** universities and employers expect; **without** this practice, many young people would arrive at university **having never had to** organise their own study."], ["concession: stress · sleep", "**Admittedly,** excessive homework **can cause** stress and cut into sleep, particularly for students who also attend cram school."], ["rebuttal: shorter tasks · Finland's small classes", "**Yet the solution lies in** setting shorter, more purposeful tasks, **not in** abandoning homework altogether, and the Finnish model **depends on** conditions, such as small classes, that few school systems share."], ["restate: indispensable · well designed", "**In conclusion, I believe** homework **remains** an indispensable part of education, **provided that** it is well designed and reasonable in quantity."], ["skills through practice", "Skills **are built not in** a single lesson **but through** steady, independent practice, night after night."]], "vocab": [["excessive", "過量的"], ["toll", "損害、代價"], ["irritable", "煩躁易怒的"], ["level off", "趨於平穩"], ["consolidate", "鞏固"], ["self-discipline", "自律"], ["indispensable", "不可或缺的"], ["purposeful", "有明確目的的"]]};

window.PET_ESSAY_ADV[5] = {"args": {"agree": [{"t": "Comparison & Self-Esteem 比較與自尊", "ts": ["Social media encourages teenagers to compare themselves with others, which can seriously damage their self-esteem.", "社群媒體讓青少年不斷和別人比較，可能嚴重傷害他們的自尊心。"], "ex": ["Feeds are full of edited photos and highlights, so ordinary lives can seem dull and bodies seem imperfect.", "動態上滿是修過的照片和精彩片段，讓平凡的生活顯得乏味、身材顯得不完美。"], "eg": ["Meta's own research, leaked in 2021, found that Instagram made body-image concerns worse for about a third of teenage girls who had them.", "2021 年外洩的 Meta 內部研究發現，Instagram 讓約三分之一本來就有身材焦慮的少女情況更糟。"], "wu": ["Therefore, constant exposure to idealised images can leave young people feeling inadequate, anxious and unhappy with themselves.", "因此，長期接觸理想化的形象可能讓年輕人覺得自己不夠好、焦慮，並對自己不滿意。"]}, {"t": "Time and Sleep 時間與睡眠", "ts": ["Endless scrolling takes hours away from homework, exercise and sleep, often late into the night.", "無止盡地滑手機奪走了寫作業、運動和睡覺的時間，常常一滑就到深夜。"], "ex": ["Apps use notifications and infinite feeds to keep users online long after they intended to stop.", "App 利用通知和無限動態，讓使用者在原本打算停下來之後還繼續上線。"], "eg": ["In 2023 the US Surgeon General warned that heavy social media use is linked to poor sleep and depression among adolescents.", "2023 年美國聯邦衛生署長警告，大量使用社群媒體與青少年睡眠不良和憂鬱有關。"], "wu": ["As a result, social media quietly erodes the habits teenagers need to stay healthy and focused.", "因此，社群媒體在不知不覺中侵蝕了青少年維持健康與專注所需的生活習慣。"]}, {"t": "Cyberbullying 網路霸凌", "ts": ["Social media allows bullying to follow teenagers home and continue at any hour of the day or night.", "社群媒體讓霸凌跟著青少年回家，並且無論白天黑夜都可能持續。"], "ex": ["Cruel comments can be shared instantly with a large audience and are very difficult to delete completely.", "惡意留言能瞬間傳給大量觀眾，而且很難完全刪除。"], "eg": ["An embarrassing photo posted in a class group chat can be screenshotted and spread across a whole school within minutes.", "一張發在班級群組的糗照，可能在幾分鐘內被截圖並傳遍全校。"], "wu": ["In short, social media gives bullies a wider reach and victims fewer places to escape.", "簡單來說，社群媒體讓霸凌者影響範圍更廣，受害者卻更無處可逃。"]}, {"t": "Misinformation 錯誤資訊", "ts": ["Teenagers on social media are frequently exposed to misinformation that they may not have the skills to recognise.", "使用社群媒體的青少年經常接觸錯誤資訊，而他們未必有能力辨識。"], "ex": ["Algorithms promote content that attracts clicks, so dramatic falsehoods often spread faster than careful, accurate reporting.", "演算法會推送吸引點擊的內容，因此聳動的假消息常比謹慎準確的報導傳得更快。"], "eg": ["Dangerous diet trends and fake health cures regularly go viral on short-video platforms popular with young users.", "危險的減肥風潮和假的健康偏方經常在年輕人愛用的短影音平台上爆紅。"], "wu": ["Thus, social media can shape young people's beliefs and choices in misleading and even harmful ways.", "因此，社群媒體可能以誤導甚至有害的方式影響年輕人的觀念與選擇。"]}], "disagree": [{"t": "Connection and Support 連結與支持", "ts": ["Social media helps teenagers stay connected with friends and find support when they feel isolated.", "社群媒體幫助青少年和朋友保持聯繫，並在感到孤單時找到支持。"], "ex": ["Young people with a disability, an unusual hobby or a minority identity can find others who understand them.", "身障、有冷門嗜好或身為少數族群的年輕人，可以找到理解他們的人。"], "eg": ["During the school closures of 2020, social platforms were among the main ways students kept in touch with their friends.", "2020 年學校停課期間，社群平台是學生和朋友保持聯絡的主要方式之一。"], "wu": ["Therefore, for many lonely or isolated teenagers, social media is a lifeline rather than a threat.", "因此，對許多孤單或被孤立的青少年而言，社群媒體是一條救命索，而不是威脅。"]}, {"t": "Learning and Creativity 學習與創造力", "ts": ["Social media gives teenagers free access to tutorials and a platform to share their own creative work.", "社群媒體讓青少年免費取得教學資源，也提供平台分享自己的創作。"], "ex": ["Students can learn to code, draw, cook or play an instrument by following experts who post free lessons online.", "學生可以追蹤在網路上發布免費課程的專家，學習寫程式、畫畫、烹飪或演奏樂器。"], "eg": ["Many young musicians and artists have built an audience by posting their work on YouTube or Instagram.", "許多年輕音樂人和藝術家都是透過在 YouTube 或 Instagram 發表作品而累積觀眾的。"], "wu": ["As a result, social media can turn passive consumers into active and confident learners and creators.", "因此，社群媒體能把被動的使用者變成主動而自信的學習者與創作者。"]}, {"t": "Voice and Awareness 發聲與意識", "ts": ["Social media allows young people to raise awareness of issues they care about and make their voices heard.", "社群媒體讓年輕人能為自己關心的議題發聲，引起社會關注。"], "ex": ["Teenagers who cannot vote can still influence public debate by sharing information and organising campaigns online.", "還不能投票的青少年，仍可透過網路分享資訊、發起活動來影響公共討論。"], "eg": ["Greta Thunberg's school strike for the climate grew into a global movement largely through social media.", "格蕾塔·通貝里的氣候罷課行動，主要透過社群媒體發展成全球運動。"], "wu": ["In other words, social media gives the younger generation real influence over their own future.", "換句話說，社群媒體讓年輕世代對自己的未來擁有真正的影響力。"]}, {"t": "The Problem Is Use, Not the Tool 問題在使用方式而非工具", "ts": ["Most of the harms linked to social media come from how it is used rather than from the platforms themselves.", "與社群媒體相關的傷害，大多來自使用方式，而不是平台本身。"], "ex": ["Teenagers who set time limits, follow positive accounts and protect their privacy can enjoy the benefits safely.", "懂得設定使用時間、追蹤正向帳號並保護隱私的青少年，可以安全地享受其好處。"], "eg": ["Many schools now teach digital literacy lessons that show students how to spot fake news and report bullying.", "許多學校現在開設數位素養課程，教學生如何辨識假新聞和檢舉霸凌。"], "wu": ["Consequently, education and parental guidance are far better solutions than simply blaming social media for every problem teenagers face.", "因此，教育與家長的引導，遠比把青少年面臨的每個問題都怪罪於社群媒體更好。"]}]}, "agree": [["reshaped adolescence · fast", "**Rarely has** a technology reshaped adolescence **as quickly as** social media."], ["Instagram · TikTok · socialise · measure worth", "**Within** little more than a decade, platforms **such as** Instagram and TikTok **have become the place where** teenagers socialise, relax and measure their own worth."], ["stance: agree · self-esteem + time", "**Although** these apps offer some benefits, **I agree that** they do more harm than good, **chiefly because** they damage young people's self-esteem and consume time that should be spent on sleep and study."], ["constant comparison", "**The most damaging effect is** constant comparison."], ["filtered faces · perfect bodies · identity still forming", "Feeds **filled with** filtered faces, flawless bodies and luxurious holidays present an unattainable standard, and teenagers, **whose** sense of identity is still forming, **are especially vulnerable to** measuring themselves against it."], ["Meta leak 2021 · 1 in 3 girls · body image worse", "**Tellingly,** Meta's **own** internal research, **leaked in** 2021, **found that** Instagram made body-image concerns worse for roughly a third of teenage girls who already had them."], ["platform admits harm", "**When even** the platform acknowledges the harm, **it is difficult to dismiss**."], ["devours time unnoticed", "Social media **also devours** time **in ways that** few teenagers notice."], ["infinite feeds · notifications · late night · Surgeon General 2023", "**Designed around** infinite feeds and notifications, these apps keep users scrolling **long after** they intended to stop, often late into the night; **in** 2023 the US Surgeon General **issued an advisory warning that** heavy use is linked to poor sleep, anxiety and depression, **a striking step for** a public-health authority."], ["concession: stay in touch with friends", "**It is true that** social media allows teenagers to stay in touch with friends."], ["rebuttal: messaging · face to face · no audience pressure", "**However,** such friendships **could easily be maintained through** messaging apps or face-to-face meetings, **neither of which** carries the same pressure to perform for an audience."], ["restate: not without merit · harmful overall", "**In conclusion, while** social media **is not without merit,** its effects on teenagers' mental health and time **are, on balance,** harmful."], ["profits from attention", "**A** platform **that profits from** attention **will rarely** protect the wellbeing of those who give it."]], "disagree": [["unhappy teens · blame social media", "**Whenever** teenagers seem unhappy, social media **is the first to be blamed,** often on remarkably thin evidence."], ["addiction headlines · friendship · learning · opportunity", "Headlines about addiction and anxiety **abound, yet they rarely mention** the millions of young people **for whom** these platforms are a source of friendship, learning and opportunity."], ["stance: disagree · support + knowledge + voice", "**I disagree that** social media does more harm than good, **since, used sensibly,** it connects teenagers with support and gives them access to knowledge and a public voice."], ["connection", "**Perhaps its greatest value lies in** connection, particularly for those who struggle to find it offline."], ["isolated teens · disability · rare interest · identity", "Teenagers **who** feel isolated at school, **whether because of** a disability, an unusual interest or their identity, **can find** online communities **where** they are understood."], ["2020 school closures · keep in touch", "**During** the school closures of 2020, **moreover,** social platforms **were among the main ways in which** young people kept in touch with their friends."], ["not distraction · lifeline", "**For many,** these networks **are not** a distraction **but** a lifeline, offering reassurance at difficult moments."], ["learning · civic participation", "Social media **also opens doors to** learning and civic participation on an unprecedented scale."], ["tutorials · explainers · Greta Thunberg · global movement", "**Whether it is** a coding tutorial, a science explainer **or** a language lesson, high-quality educational content **is freely available to anyone with** a connection; **it was through** social media, **after all, that** Greta Thunberg's school strike grew into a global movement, **showing how** young people can shape debates about their own future."], ["concession: cyberbullying · beauty standards", "**Admittedly,** cyberbullying and unrealistic beauty standards **are genuine problems** that no one should dismiss."], ["rebuttal: how it's used · education · settings · guidance", "**Yet** these **stem from** how platforms are used, and **are best addressed through** digital education, privacy settings and parental guidance **rather than** blanket condemnation."], ["restate: more good than harm · use wisely", "**In conclusion, I believe** social media does teenagers **more good than harm, provided that** they learn to use it wisely."], ["teach, don't switch off", "**The answer is not to** switch it off, **but to** teach young people to use it critically, kindly and well."]], "vocab": [["self-esteem", "自尊心"], ["unattainable", "無法達到的"], ["vulnerable to", "容易受……影響的"], ["advisory", "（官方）警示、建議公告"], ["lifeline", "救命索、重要支柱"], ["civic participation", "公民參與"], ["blanket condemnation", "全盤譴責"], ["stem from", "源自於"]]};

window.PET_ESSAY_ADV[6] = {"args": {"agree": [{"t": "Designed to Hook Players 設計來讓人上癮", "ts": ["Most modern games are designed to keep people playing for as long as possible rather than to be finished.", "多數現代遊戲的設計目的是讓人盡可能玩得越久越好，而不是讓人玩完。"], "ex": ["Daily rewards, rankings and limited-time events push players to log in again and again, often longer than they planned.", "每日獎勵、排行榜和限時活動促使玩家一再登入，玩的時間常常超出原本的打算。"], "eg": ["A player who opens a mobile game for a quick ten-minute break can easily look up and find that two hours have gone.", "一個只想打開手遊休息十分鐘的玩家，很容易一抬頭就發現兩個小時已經過去了。"], "wu": ["Therefore, much of the time spent gaming is not really chosen freely but taken by clever design.", "因此，花在遊戲上的許多時間並非真正自由選擇，而是被巧妙的設計奪走的。"]}, {"t": "Lost Opportunities 錯失的機會", "ts": ["Every hour spent gaming is an hour that cannot be used for activities with longer-lasting benefits.", "每花一小時玩遊戲，就少了一小時可以投入效益更長久的活動。"], "ex": ["Skills such as playing an instrument, speaking a language or playing a sport grow steadily with practice over many years.", "像演奏樂器、說外語或從事運動等技能，會隨著多年練習穩定成長。"], "eg": ["A teenager who games for three hours a night spends over a thousand hours a year that could have produced a real skill.", "一個每晚玩三小時遊戲的青少年，一年花掉一千多個小時，這些時間原本可以練成一項真本事。"], "wu": ["As a result, heavy gaming often leaves young people with high scores but few abilities they can use in real life.", "因此，大量玩遊戲常讓年輕人分數很高，卻沒有多少能在現實生活中使用的能力。"]}, {"t": "Health Costs 健康代價", "ts": ["Long gaming sessions take a toll on physical health, especially on sleep, eyesight and posture.", "長時間打遊戲會損害身體健康，尤其是睡眠、視力和姿勢。"], "ex": ["Players sit still for hours under bright screens, and exciting games make it hard for the brain to switch off before bed.", "玩家在明亮的螢幕前一坐就是好幾個小時，而刺激的遊戲讓大腦在睡前難以放鬆下來。"], "eg": ["Many eye doctors in Taiwan warn that rising rates of short-sightedness among students are linked to long hours of screen use.", "台灣許多眼科醫師警告，學生近視比例上升與長時間使用螢幕有關。"], "wu": ["Consequently, players who spend long hours gaming may pay for it with their health as well as with their free time.", "因此，長時間玩遊戲的玩家付出的不只是空閒時間，還可能賠上健康。"]}, {"t": "Virtual Rewards Vanish 虛擬獎勵終會消失", "ts": ["Achievements earned inside a game, however impressive they look on screen, have little value in the real world.", "在遊戲裡獲得的成就，無論在螢幕上看起來多麼厲害，在現實世界中幾乎沒有價值。"], "ex": ["Levels, rare items and rankings exist only on a company's servers and disappear when the game closes or the player moves on.", "等級、稀有道具和排名只存在於遊戲公司的伺服器上，遊戲關閉或玩家不再玩時就會消失。"], "eg": ["When a popular online game shuts down, players who spent years building powerful characters are left with nothing at all.", "當一款熱門線上遊戲停止營運時，花了好幾年練出強大角色的玩家最後什麼也沒留下。"], "wu": ["In short, gaming rewards may feel important at the time, but they leave nothing lasting behind once the game is over.", "簡而言之，遊戲獎勵當下或許感覺很重要，但遊戲結束後卻留不下任何長久的東西。"]}], "disagree": [{"t": "Healthy Relaxation 健康的放鬆", "ts": ["When they are played in moderation, video games are a healthy way to relax after a long and demanding day.", "只要適度地玩，電玩是漫長忙碌的一天後健康的放鬆方式。"], "ex": ["Games are absorbing enough to take the mind off stress, and they require active thinking rather than passive watching.", "遊戲引人入勝，足以讓人暫時忘卻壓力，而且需要主動思考，而不是被動觀看。"], "eg": ["A student who plays for thirty minutes after cram school may return to revision calmer and more focused.", "一個下了補習班後玩三十分鐘遊戲的學生，回到複習時可能會更平靜、更專注。"], "wu": ["Therefore, a short gaming break can improve the quality of the study time that follows.", "因此，短暫的遊戲休息可以提升接下來讀書時間的品質。"]}, {"t": "Teamwork and Problem-Solving 團隊合作與解決問題", "ts": ["Many popular games help players develop valuable skills such as teamwork, careful planning and quick decision-making.", "許多熱門遊戲能幫助玩家培養團隊合作、縝密規劃和快速決策等寶貴技能。"], "ex": ["Players must share information, agree on a plan and adjust it within seconds when the situation changes.", "玩家必須分享資訊、商定計畫，並在情況改變時於幾秒內調整。"], "eg": ["In strategy games such as Civilization, players manage limited resources and think several moves ahead, much like a manager.", "在《文明帝國》這類策略遊戲中，玩家管理有限資源並預想好幾步，就像一位經理人。"], "wu": ["Thus, well-chosen games can train practical skills that remain useful long after the game is switched off, at school and at work.", "因此，挑選得當的遊戲能訓練實用的技能，關掉遊戲後在學校和職場仍然派得上用場。"]}, {"t": "Learning and Careers 學習與職涯", "ts": ["Video games can support language learning and, for some young people, even lead to well-paid careers.", "電玩可以幫助語言學習，對某些年輕人來說，甚至能通往收入不錯的職業。"], "ex": ["Online players often communicate in English, and the games industry needs designers, programmers, artists and professional players.", "線上玩家經常用英文溝通，而遊戲產業需要設計師、程式設計師、美術人員和職業選手。"], "eg": ["Taiwan has produced professional e-sports teams that compete in international tournaments watched by millions of fans.", "台灣已培養出參加國際賽事的職業電競隊伍，比賽吸引數百萬粉絲觀看。"], "wu": ["As a result, time spent gaming is not always wasted; it can open doors to new skills and jobs.", "因此，玩遊戲的時間不一定是浪費，它可能開啟通往新技能與工作的大門。"]}, {"t": "Balance, Not a Ban 平衡而非禁止", "ts": ["The real problem is excessive gaming, not gaming itself, which is harmless when it is kept within reasonable limits.", "真正的問題在於過度玩遊戲，而不是遊戲本身；只要控制在合理範圍內，遊戲並無害處。"], "ex": ["Almost any enjoyable activity, from social media to sport, becomes harmful when it pushes out sleep and study.", "幾乎任何令人愉快的活動，從社群媒體到運動，一旦排擠了睡眠和讀書都會變得有害。"], "eg": ["Many families agree on a simple rule, such as one hour of gaming after homework is finished, which keeps the hobby under control.", "許多家庭約定一個簡單的規則，例如作業寫完後才能玩一小時，讓這個嗜好維持在可控範圍。"], "wu": ["In other words, sensible limits solve the problem far better than calling all gaming a waste of time.", "換句話說，合理的限制比把所有遊戲都視為浪費時間更能解決問題。"]}]}, "agree": [["pastime · absorbed hours · recent decades", "**Rarely has** a single pastime absorbed so many hours of so many lives **as** video gaming has in recent decades."], ["industry > film + music · parents worried", "**With** the games industry **now** earning more than film and music combined, **it is hardly surprising that** parents and teachers question how young people spend their evenings."], ["stance: agree · engineered to consume time · displace valuable activities", "**Although** games **can** offer harmless entertainment in small doses, **I would argue that** for most players they are a poor use of time, **since** they are engineered to consume hours and displace activities of far greater value."], ["designed never to end", "**The central problem is that** modern games are designed not to be finished but to be played indefinitely."], ["login rewards · rankings · 20 min → 2 hours lost", "Daily login rewards and ranking systems **exploit** well-documented psychological mechanisms, **so that** a player **who intends to** play for twenty minutes **frequently** surfaces two hours later."], ["WHO · gaming disorder · China's time limits", "**It is telling that** the World Health Organization now recognises 'gaming disorder' as a medical condition, **and that** China has imposed legal limits on how long minors may play online."], ["→ not a free choice", "**When** a product **is built to** override self-control, the time spent on it **is rarely** a free choice."], ["opportunity cost", "**Equally significant is** the opportunity cost of all those hours."], ["instrument · sport · novel vs rewards vanish", "An evening devoted to climbing an online ranking **could instead have been spent** learning an instrument, playing a sport or reading a novel, activities whose benefits accumulate over years; the rewards of a game, **by contrast, however** hard-won, vanish the moment its servers are switched off."], ["concession: strategy · reflexes · teamwork", "**Admittedly,** some games **do** develop strategic thinking and quick reflexes, and team titles demand cooperation."], ["rebuttal: chess · sport · music · no compulsive design", "**Yet these** skills **can be acquired far more** efficiently **through** chess, team sports or music, **none of which** carries the same compulsive design or toll on sleep."], ["restate: hours better invested elsewhere", "**In conclusion, while** an occasional game is perfectly harmless, **I firmly believe that** the hours most people pour into gaming **would be better** invested elsewhere."], ["achievements that survive", "**The only** achievements **worth** chasing, **after all, are those that** survive when the screen goes dark."]], "disagree": [["every generation · blame a pastime", "**Every generation, it seems, finds** a new pastime **to blame for** the supposed idleness of its young."], ["novels · radio · TV once condemned", "**Just as** novels, radio and television **were once condemned as** corrupting distractions, video games **are now routinely dismissed as** a waste of time."], ["stance: disagree · moderation · relaxation + skills", "**I disagree with this view: provided that** they are played in moderation, games **offer** genuine relaxation **and** develop skills that conventional schooling often neglects."], ["leisure ≠ wasted time", "**The first point to make is that** leisure is not wasted **simply because** it produces nothing measurable."], ["demanding day · switch off · active not passive", "**After** a demanding day of lessons or work, people need an activity **that is** absorbing **enough to** switch off their worries, **and many** games **provide precisely that**, requiring active engagement rather than passive viewing."], ["hospitals · calming games · play manages stress", "**It is no coincidence that** some children's hospitals use calming games to ease anxiety before treatment, **and that** psychologists increasingly regard play as a legitimate way of managing stress."], ["novel ≠ wasted → why gaming?", "**Few would** call an evening with a novel wasted, **so it is hard to see why** an hour of gaming should be judged differently."], ["skills that carry over", "**Beyond** relaxation, well-designed games **cultivate** abilities that carry over into real life."], ["Civilization · planning · team games · English · careers", "Strategy titles **such as** Civilization **require** players to manage scarce resources and plan several moves ahead, **while** online team games demand rapid communication under pressure, often in English with international players; **the industry itself now** employs designers, programmers and professional competitors."], ["concession: lose control · sleep · study", "**It must be acknowledged that** some players lose control, **sacrificing** sleep, exercise and study to their screens."], ["rebuttal: any hobby · excess · limits", "**However, the same is true of** almost any enjoyable activity, from social media to sport; **the problem lies in** excess **rather than in** gaming itself, and sensible limits address it far better than blanket condemnation."], ["restate: no more wasteful than any hobby", "**In conclusion,** video games **are no more** a waste of time **than** any other hobby, **as long as** they are balanced with study, exercise and real friendships."], ["not whether but how wisely", "**What matters is not whether** young people play, **but how** wisely they do so."]], "vocab": [["opportunity cost", "機會成本"], ["exploit (a weakness)", "利用（弱點）；剝削"], ["override self-control", "凌駕／壓過自制力"], ["accumulate", "累積"], ["displace", "取代；排擠"], ["blanket condemnation", "全面的譴責"], ["in moderation", "適度地"], ["cultivate", "培養"]]};

window.PET_ESSAY_ADV[7] = {"args": {"agree": [{"t": "Learning at Your Own Pace 依自己的步調學習", "ts": ["Online learning allows each student to move through the material at the speed that suits them best.", "線上學習讓每位學生能依照最適合自己的速度學習教材內容。"], "ex": ["Students can pause, replay or skip parts of a lesson instead of being rushed or bored in a large class.", "學生可以暫停、重播或跳過課程的部分內容，而不必在大班級裡被催促或感到無聊。"], "eg": ["A student who finds algebra difficult can watch the same explanation three times until it finally makes sense.", "覺得代數很難的學生可以把同一段講解看三遍，直到終於弄懂為止。"], "wu": ["Therefore, gaps in a student's understanding can be filled before the course moves on to harder topics.", "因此，學生理解上的漏洞能在課程進入更難的單元之前就被補上。"]}, {"t": "Access to Excellent Teachers 接觸優秀的老師", "ts": ["Online learning gives students access to high-quality teaching, no matter whether they live in a big city or a small village.", "線上學習讓學生無論住在大城市還是小村莊，都能接觸到高品質的教學。"], "ex": ["Location no longer limits who can teach a student, so the best lessons are available to anyone with an internet connection.", "地點不再限制誰能教導學生，因此任何有網路的人都能取得最好的課程。"], "eg": ["Free platforms such as Khan Academy offer clear lessons in maths and science to students in remote villages and big cities alike.", "像可汗學院這樣的免費平台，為偏鄉與大城市的學生同樣提供清楚的數學和科學課程。"], "wu": ["As a result, a student's education depends less on which school happens to be nearby.", "因此，學生所受的教育較不會取決於附近剛好有哪一所學校。"]}, {"t": "No Commute, More Time 不用通勤，時間更多", "ts": ["Studying at home saves students the considerable time and energy that the daily journey to and from school consumes.", "在家學習能幫學生省下每天往返學校所耗費的大量時間與精力。"], "ex": ["Without early buses and long journeys, students can sleep longer and arrive at their lessons more alert.", "不必趕早班公車、長途通勤，學生可以多睡一點，上課時也更有精神。"], "eg": ["A student who spends an hour a day commuting could gain over two hundred extra hours a year for sleep, exercise or reading.", "一個每天通勤一小時的學生，一年就能多出兩百多個小時用來睡覺、運動或閱讀。"], "wu": ["Consequently, online learners often enjoy a healthier and more balanced daily routine than students who travel to school.", "因此，線上學習者往往比通勤上學的學生擁有更健康、更平衡的日常作息。"]}, {"t": "Fewer Distractions and Less Pressure 較少干擾與壓力", "ts": ["Learning at home can protect students from many of the distractions and pressures of school life.", "在家學習可以讓學生免於許多校園生活中的干擾與壓力。"], "ex": ["There are no noisy classmates, no peer pressure in the corridors and fewer chances for bullying.", "沒有吵鬧的同學、沒有走廊上的同儕壓力，被霸凌的機會也比較少。"], "eg": ["Shy students who rarely speak in class often feel more confident asking questions in an online chat box.", "很少在課堂上發言的害羞學生，在線上聊天室提問時常常更有自信。"], "wu": ["In short, a calmer and safer environment at home helps some students learn more effectively than they would at school.", "簡而言之，家中較平靜安全的環境能幫助部分學生比在學校學得更有效率。"]}], "disagree": [{"t": "Social Skills 社交能力", "ts": ["School teaches young people how to live and work alongside others, a lesson that no online course can provide.", "學校教導年輕人如何與他人一起生活和合作，這是任何線上課程都無法提供的一課。"], "ex": ["Group projects, team sports and everyday disagreements build cooperation, empathy and the ability to resolve conflict.", "小組報告、團隊運動和日常的意見分歧能培養合作、同理心和解決衝突的能力。"], "eg": ["During the pandemic, many surveys reported that teenagers studying from home felt more lonely and anxious than before.", "疫情期間，許多調查顯示在家學習的青少年比以前更孤單、更焦慮。"], "wu": ["Therefore, school offers young people a real community and a sense of belonging that a screen cannot replace.", "因此，學校提供年輕人真實的群體生活與歸屬感，這是螢幕無法取代的。"]}, {"t": "Discipline and Motivation 紀律與動機", "ts": ["Most teenagers do not yet have the self-discipline needed to study alone at home for hours every day.", "多數青少年還不具備每天在家獨自讀書好幾個小時所需要的自律。"], "ex": ["At home they are surrounded by beds, games consoles and phones, and there is no teacher nearby to keep them on task.", "在家裡，他們身邊圍繞著床、遊戲機和手機，也沒有老師在旁邊督促他們專心。"], "eg": ["Many teachers noticed that during online classes students often turned off their cameras and quietly stopped paying attention.", "許多老師發現上線上課時，學生常關掉鏡頭，然後默默地不再專心。"], "wu": ["As a result, online lessons often lead to less learning than the same lessons in a classroom.", "因此，線上課程的學習成效常常不如在教室上同樣的課。"]}, {"t": "Hands-On Learning 實作學習", "ts": ["Many important school subjects cannot be taught properly without real equipment, real space and real classmates.", "許多重要的學校科目，沒有真實的器材、空間和同學就無法好好教授。"], "ex": ["Experiments, sports and music depend on physical practice that cannot be done properly through a webcam.", "實驗、運動和音樂都仰賴實際操作，無法透過視訊鏡頭好好完成。"], "eg": ["A chemistry student who only watches a video of an experiment never learns how to handle the equipment safely.", "只看實驗影片的化學學生，永遠學不會如何安全地操作器材。"], "wu": ["Consequently, online learning leaves out practical parts of education that students can only gain by doing things themselves.", "因此，線上學習會遺漏教育中實作的部分，而這些只有親自動手才能學到。"]}, {"t": "Unequal Conditions 條件不平等", "ts": ["Online learning works well only for students whose homes provide the right conditions for quiet, focused study.", "線上學習只對家中能提供安靜、專注讀書條件的學生有效。"], "ex": ["Not every family can provide a quiet room, a reliable internet connection and an adult who can help.", "不是每個家庭都能提供安靜的房間、穩定的網路和能幫忙的大人。"], "eg": ["A student who shares a small flat with younger siblings may find it almost impossible to concentrate during online lessons.", "和弟妹擠在小公寓裡的學生，上線上課時可能幾乎無法專心。"], "wu": ["In other words, replacing school with online learning could widen the gap between rich and poor students.", "換句話說，以線上學習取代學校可能會擴大貧富學生之間的差距。"]}]}, "agree": [["rural student · top professor · without leaving home", "**Never before has** a student in a rural town **been able to** attend lessons delivered by leading teachers without leaving home."], ["pandemic · schools online · is the classroom still best?", "**Since** the pandemic forced schools worldwide to move online, **many people have begun to ask whether** the classroom is still the best place to learn."], ["stance: online better · own pace + better teaching", "**While** school **undoubtedly** has social value, **I believe that** learning online at home is, for many students, the better option, **as it allows** them to work at their own pace **and gives** them access to teaching of a higher standard."], ["learning at one's own pace", "**The most compelling advantage is** the freedom to learn at one's own pace."], ["class of 30 · pitched at the middle · bored vs lost", "**In** a class of thirty, a teacher **has no choice but to** pitch each lesson at the middle, **leaving** quicker students bored and slower ones increasingly lost."], ["pause · replay · skip · tutor-like attention", "**Online, by contrast,** a student can pause a difficult explanation, replay it as often as necessary **which is precisely** the individual attention **that** private tutors charge handsomely for."], ["→ gaps fixed before they widen", "**As a result,** gaps in understanding **are addressed before** they widen, **rather than** carried into the next topic."], ["quality and range of teaching", "**Equally important is** the quality and range of teaching available online."], ["Khan Academy · free · remote village · commuting time saved", "Platforms **such as** Khan Academy **offer** carefully sequenced lessons in most subjects free of charge, **so that** a teenager in a remote village can learn from the same outstanding teachers as one in a capital city; **moreover,** the hour often lost to commuting **can be reinvested in** sleep, exercise or reading."], ["concession: social skills · discipline", "**Critics rightly point out that** school teaches social skills **and that** not every teenager has the discipline to study alone."], ["rebuttal: clubs · sport · self-discipline valued", "**Nevertheless,** friendships **can flourish through** clubs, sport and community activities, **and** self-discipline **is a skill that** online learners must develop early and employers value highly."], ["restate: more flexible + higher quality", "**In conclusion, although** the classroom will not disappear, **I am convinced that** online learning offers a more flexible and often higher-quality education."], ["not a place but access", "Education **is no longer** a place we go to, **but** something we can reach wherever we are."]], "disagree": [["2020 · schools closed · missed classrooms", "**When** schools around the world closed their doors in 2020, **few** students **imagined how much** they would miss an ordinary classroom."], ["online courses improved · claim · lessons suggest otherwise", "**Now that** online courses have become more sophisticated, **some argue that** learning at home is superior to attending school, **yet** the lessons of those months **suggest otherwise**."], ["stance: disagree · social development + structure", "**I strongly disagree with this view, because** school provides the social development and the structure that young people need, **neither of which** a screen can fully replicate."], ["living alongside others", "**Above all,** school **is where** young people learn to live alongside others."], ["group projects · teams · disagreements · empathy", "Group projects, team sports and even playground disagreements **teach** cooperation, empathy and conflict resolution, **skills that are acquired through** daily contact **rather than through** a webcam."], ["pandemic studies · loneliness · anxiety · widening gap", "**It is significant that** studies conducted during the pandemic reported sharp rises in loneliness and anxiety among teenagers learning remotely, **as well as** a widening gap between stronger and weaker students."], ["→ community, not just information", "**What** a school **offers, in other words, is not merely** information **but** a community."], ["self-discipline lacking", "**Equally, few** teenagers **possess** the self-discipline **that** studying alone **demands**."], ["bed · console · notifications · labs · teacher sees confusion", "**Surrounded by** a bed, a games console and endless notifications, **even** motivated students **find it difficult to** concentrate for long, **while** subjects such as chemistry, physical education and music lose much of their meaning without laboratories, playing fields and fellow musicians."], ["concession: own pace · no commute", "**It is true that** online learning allows students to work at their own pace and saves time spent commuting."], ["rebuttal: supplement not replacement · no quiet room", "**However, these** advantages **are best enjoyed by** using recorded lessons as a supplement to school **rather than** a replacement, **particularly as** many families have neither a quiet room nor a reliable connection."], ["restate: school far preferable", "**All things considered,** attending school **remains far preferable to** learning online, at least for the vast majority of students."], ["people as much as information", "Education, **in the end, is about** people **as much as** information."]], "vocab": [["pitch (a lesson) at", "把（課程）難度設定在……"], ["charge handsomely for", "為……收取高額費用"], ["reinvest (time) in", "把（時間）重新投入在……"], ["flourish", "蓬勃發展"], ["replicate", "複製；重現"], ["conflict resolution", "解決衝突"], ["a widening gap", "日益擴大的差距"], ["supplement", "補充；輔助"]]};

window.PET_ESSAY_ADV[8] = {"args": {"agree": [{"t": "Understanding Money 了解金錢", "ts": ["A part-time job teaches teenagers the real value of money in a way that no lesson at home can.", "打工能讓青少年以家中任何說教都無法做到的方式，了解金錢的真正價值。"], "ex": ["When money is earned through hours of effort, young people think more carefully before spending it.", "當錢是用好幾個小時的努力換來的，年輕人花錢前會想得更仔細。"], "eg": ["A student who earns about NT$200 an hour may decide that a NT$70 drink is not worth twenty minutes of work.", "時薪約兩百元的學生，可能會覺得一杯七十元的飲料不值得工作二十分鐘去換。"], "wu": ["Therefore, teenagers who work part-time often learn to budget and save money much earlier than their classmates.", "因此，打工的青少年往往比同學更早學會做預算和存錢。"]}, {"t": "Responsibility and Soft Skills 責任感與軟實力", "ts": ["Holding down a part-time job develops a sense of responsibility and practical social skills that teenagers will need later.", "持續做一份兼職工作能培養責任感與實用的社交技巧，這些都是青少年日後需要的。"], "ex": ["Employees must arrive on time, follow instructions and stay polite even when customers are rude.", "員工必須準時上班、遵照指示，即使客人無禮也要保持禮貌。"], "eg": ["A teenager working in a busy restaurant quickly learns to stay calm, work in a team and solve small problems alone.", "在忙碌餐廳工作的青少年很快就學會保持冷靜、團隊合作和自己解決小問題。"], "wu": ["As a result, working teenagers often become more mature and confident than many of their peers who have never had a job.", "因此，打工的青少年往往比許多從未工作過的同齡人更成熟、更有自信。"]}, {"t": "Career Exploration 職涯探索", "ts": ["Part-time work helps teenagers discover what kind of job they enjoy, and what kind they would rather avoid.", "打工能幫助青少年發現自己喜歡哪一類的工作，以及寧可避開哪一類工作。"], "ex": ["Real experience shows them the daily reality of a job, which a school textbook cannot do.", "真實的經驗讓他們看到一份工作的日常樣貌，這是學校課本做不到的。"], "eg": ["A student who works in a bookshop may realise that she loves helping customers and decide to study marketing.", "在書店打工的學生可能會發現自己喜歡幫助顧客，因而決定念行銷。"], "wu": ["Consequently, they can make wiser and better-informed choices about their university major and their future career.", "因此，他們能對大學科系與未來職涯做出更明智、更有根據的選擇。"]}, {"t": "Independence 獨立", "ts": ["Earning their own money makes teenagers more independent and less reliant on their parents for everyday expenses.", "自己賺錢讓青少年更獨立，日常開銷也較不依賴父母。"], "ex": ["When the money is their own, they must take full responsibility for their spending decisions and live with the results.", "當錢是自己賺的，他們就必須為自己的消費決定負起全責，並承擔後果。"], "eg": ["A teenager who saves for months to buy a laptop usually takes far better care of it than a gift.", "一個存了好幾個月的錢才買到筆電的青少年，通常會比對待禮物更珍惜它。"], "wu": ["In short, a part-time job is an important early step towards the independence that adult life will demand.", "簡而言之，打工是邁向成年生活所需獨立能力的重要第一步。"]}], "disagree": [{"t": "Studies Come First 課業優先", "ts": ["A part-time job takes away the time and energy that teenagers need for schoolwork during the term.", "打工會奪走青少年在學期中完成課業所需的時間與精力。"], "ex": ["After a long evening shift, students are too tired to do homework properly or concentrate in class the next day.", "上完一整晚的班之後，學生累到無法好好寫作業，隔天上課也難以專心。"], "eg": ["Since entrance exams largely decide which school a student can attend, even a small fall in grades can have serious effects.", "由於升學考試很大程度決定學生能進哪所學校，即使成績小幅下滑也可能造成嚴重影響。"], "wu": ["Therefore, the small amount of money earned is rarely worth the damage it can do to a student's education.", "因此，賺到的那一點錢，很少值得以學業受損為代價。"]}, {"t": "Exploitation and Safety 剝削與安全", "ts": ["Teenage workers are easy targets for unfair treatment because they are young, inexperienced and eager to please.", "青少年勞工因為年輕、缺乏經驗又急於討好，很容易成為不公平待遇的對象。"], "ex": ["Because many do not know their rights, they may accept low pay, illegal hours or unsafe tasks without complaining.", "因為許多人不了解自己的權益，他們可能會毫無怨言地接受低薪、違法工時或危險的工作。"], "eg": ["Labour inspections in Taiwan regularly find shops and restaurants that pay young part-timers less than the minimum wage.", "台灣的勞動檢查經常發現有商店和餐廳付給年輕工讀生低於基本工資的薪水。"], "wu": ["As a result, a first job can teach young people the wrong lessons about work.", "因此，第一份工作可能讓年輕人學到關於工作的錯誤觀念。"]}, {"t": "Lost Youth 失去的青春", "ts": ["The teenage years are a short period that should be used for personal growth, friendship and exploring new interests.", "青少年時期很短暫，應該用來自我成長、交朋友和探索新的興趣。"], "ex": ["Time spent on repetitive paid work is time taken away from sport, hobbies and family life.", "花在重複性有薪工作上的時間，就是從運動、嗜好和家庭生活中拿走的時間。"], "eg": ["A student who works every weekend may have to give up the school basketball team or a music club entirely.", "每個週末都在打工的學生，可能不得不完全放棄校隊籃球或音樂社團。"], "wu": ["Consequently, working teenagers may miss valuable experiences that they can never get back later in life.", "因此，打工的青少年可能錯過日後再也無法重來的寶貴經歷。"]}, {"t": "Better Ways to Learn 更好的學習方式", "ts": ["The skills that a part-time job is said to teach can be learned in better and safer ways.", "一般認為打工能學到的技能，其實可以用更好、更安全的方式學到。"], "ex": ["School clubs, volunteering and short holiday internships build responsibility and teamwork without long, tiring evening shifts.", "學校社團、志工服務和寒暑假短期實習都能培養責任感和團隊合作，而不需要上長時間又累人的晚班。"], "eg": ["Volunteering at a library or animal shelter teaches punctuality and service while leaving enough time for study.", "在圖書館或動物收容所當志工能學到守時與服務精神，同時保留足夠的讀書時間。"], "wu": ["In other words, teenagers do not need a paid job to prepare for adult life.", "換句話說，青少年不需要有薪工作也能為成年生活做準備。"]}]}, "agree": [["bubble-tea counter · school uniform · hourly wage", "**Behind** the counter of almost every bubble-tea shop in Taiwan **stands** a teenager in a school uniform, **earning** a modest hourly wage after class."], ["valuable education or distraction?", "**Whether** such work is a valuable education **or** a distraction from study **remains a source of disagreement among** parents and teachers."], ["stance: agree (limited hours) · money + responsibility", "**Provided that** the hours are limited, **I firmly believe that** teenagers benefit from a part-time job, **as it teaches** the value of money **and builds** a sense of responsibility that the classroom rarely develops."], ["realistic sense of money", "**The first benefit lies in** a more realistic understanding of money."], ["Saturday afternoon · price measured in hours", "A teenager **who has spent** a whole Saturday afternoon serving customers **is far more likely to** think twice before an impulse purchase, **because** its price is now measured in hours of effort rather than abstract numbers."], ["financial educators recommend · budget · save", "**It is for this reason that** many financial educators recommend part-time work as one of the most effective ways of teaching young people to budget and save."], ["→ first pay slip > lectures", "**No** lecture from parents **can match** the lesson of a first pay slip."], ["personal qualities", "**Just as valuable are** the personal qualities **that** a job cultivates."], ["punctual · impatient customers · colleagues · career clues", "**Arriving** punctually for every shift, **handling** impatient customers politely and **cooperating** with older colleagues **all demand** a maturity that school seldom tests, **and** a few months in a restaurant or shop **can also reveal** what kind of work a young person enjoys, or dislikes, **long before** they commit to a university course."], ["concession: grades suffer · exploitation", "**Admittedly,** excessive working hours **can harm** academic performance, and some employers **take advantage of** young workers' inexperience."], ["rebuttal: 8–10 hrs/week · labour law · not a ban", "**Yet the solution lies in** sensible limits of perhaps eight to ten hours a week and firm enforcement of labour law, **not in** keeping teenagers out of the workplace altogether."], ["restate: lessons no textbook provides", "**In conclusion,** a carefully limited part-time job **offers lessons in** money and responsibility **that no** textbook **can provide**."], ["first wage → adulthood", "A first wage, **after all, is often** a young person's first step into adulthood."]], "disagree": [["10 p.m. · night market · test tomorrow", "**It is** ten o'clock on a school night, **and** a sixteen-year-old **is still** frying chicken at a night-market stall with a chemistry test the following morning."], ["more teens working · parents: builds character", "**An increasing number of** teenagers **are** taking part-time jobs, **often encouraged by** parents who believe that work builds character."], ["stance: disagree · competes with education + exploitation", "**I disagree that** teenagers should work during the school term, **because** a job **competes directly with** their education **and exposes** them to the risk of exploitation."], ["drains time and energy", "**The most obvious objection is that** employment drains the time and energy that study requires."], ["4-hour shift · no homework · asleep in class", "**After** a four-hour evening shift, **few** students **are capable of** concentrating on homework, **and** the following day is often spent half asleep in class."], ["entrance exams decide options · grades > wages", "**Since** high-school and university entrance examinations **largely determine** a young person's options, **even** a modest drop in grades **can have consequences that far outweigh** a few thousand dollars in wages."], ["→ a poor trade", "**In purely economic terms, then,** the trade is a poor one, even before its effect on health is considered."], ["vulnerable to exploitation", "**Furthermore,** teenage workers **are particularly vulnerable to** exploitation."], ["unaware of rights · below minimum wage · illegal hours · no training", "**Because** few of them know their legal rights, young employees **are frequently** paid below the minimum wage, asked to work illegal hours or given tasks without safety training, **problems that** labour inspections in the restaurant and retail sectors **continue to uncover**."], ["concession: responsibility · value of money", "**It is often argued that** jobs teach responsibility and the value of money."], ["rebuttal: clubs · volunteering · allowance", "**Yet** school clubs, volunteering and holiday internships **cultivate the same** qualities **without** the exhaustion, and a weekly allowance, **carefully managed,** teaches budgeting **just as effectively**."], ["restate: study in term · work in holidays", "**For these reasons,** teenagers **should** concentrate on their education during term time **and leave** paid work **for** the holidays or later life."], ["decades to work · few years to be young", "**There will be** decades **in which to** work; **there are only** a few years **in which to** be young."]], "vocab": [["impulse purchase", "衝動購物"], ["cultivate", "培養"], ["commit to", "投入；決定選擇"], ["take advantage of", "佔……的便宜；利用"], ["enforcement of labour law", "勞動法規的執行"], ["drain (time and energy)", "耗盡（時間與精力）"], ["outweigh", "比……更重要；超過"], ["vulnerable to exploitation", "容易被剝削"]]};

window.PET_ESSAY_ADV[9] = {"args": {"agree": [{"t": "A Tutor at Any Hour 全天候的家教", "ts": ["AI can act as a patient personal tutor that is available at any hour whenever students need help.", "AI 可以當一位有耐心的私人家教，無論何時只要學生需要協助就隨時待命。"], "ex": ["It can explain the same idea in several different ways without getting tired or impatient.", "它能用好幾種不同的方式解釋同一個概念，而且不會疲倦或不耐煩。"], "eg": ["A student stuck on a maths problem late at night can ask an AI for a step-by-step hint instead of giving up.", "深夜卡在數學題上的學生可以請 AI 提供逐步提示，而不是直接放棄。"], "wu": ["Therefore, students can keep learning effectively even when their teachers and parents are not available to help.", "因此，即使老師和家長無法協助，學生也能有效地持續學習。"]}, {"t": "Feedback, Not Answers 回饋而非答案", "ts": ["Used properly, AI gives students quick and useful feedback on work they have already done themselves.", "若使用得當，AI 能對學生自己完成的作業提供快速又有用的回饋。"], "ex": ["Students can write a draft first and then ask the AI to point out grammar mistakes or unclear ideas.", "學生可以先寫好草稿，再請 AI 指出文法錯誤或不清楚的地方。"], "eg": ["A student who asks an AI to explain why a sentence is wrong learns more than one who simply copies a corrected version.", "請 AI 解釋句子哪裡錯的學生，比直接照抄修正版本的學生學到更多。"], "wu": ["As a result, homework becomes a chance to improve rather than just a task to finish.", "因此，作業變成進步的機會，而不只是要完成的任務。"]}, {"t": "Equal Access 平等取得資源", "ts": ["AI makes extra academic help available to all students, not only to those from wealthy families.", "AI 讓所有學生都能獲得額外的課業協助，而不只限於富裕家庭的孩子。"], "ex": ["Private tutors and cram schools are expensive, but many AI tools can be used for free.", "私人家教和補習班很昂貴，但許多 AI 工具可以免費使用。"], "eg": ["A student in a rural area without a nearby cram school can still get instant explanations of difficult grammar or science.", "住在附近沒有補習班的偏鄉學生，仍能即時得到困難文法或科學概念的解說。"], "wu": ["Consequently, AI can help to narrow the long-standing gap in results between rich and poor students.", "因此，AI 有助於縮小貧富學生之間長久以來的成績差距。"]}, {"t": "A Skill for the Future 未來必備的能力", "ts": ["Learning to use AI wisely and critically is an important skill that students will need in their future careers.", "學會明智且批判性地使用 AI，是學生未來職涯中需要的一項重要技能。"], "ex": ["Most jobs will involve AI, so workers must know how to ask clear questions and check the answers they receive.", "大多數工作都會用到 AI，所以工作者必須懂得如何清楚提問並查核得到的答案。"], "eg": ["Office workers already use AI to summarise reports and draft emails, but they still need to correct its mistakes.", "上班族已經用 AI 來摘要報告和草擬電子郵件，但仍需要修正它的錯誤。"], "wu": ["In short, schools that teach responsible AI use prepare students better for the real world.", "簡而言之，教導負責任使用 AI 的學校能讓學生為真實世界做更好的準備。"]}], "disagree": [{"t": "The Struggle Is the Learning 掙扎才是學習", "ts": ["Students learn most effectively when they work through difficult problems by themselves, without being handed the answer.", "學生在不被直接給答案、自己努力解決難題時，學習效果最好。"], "ex": ["The effort of thinking, making mistakes and trying again is what builds real understanding and memory.", "思考、犯錯、再嘗試的過程，才能建立真正的理解與記憶。"], "eg": ["A student who spends twenty minutes solving a maths problem remembers the method far longer than one who reads an AI answer.", "花二十分鐘解出一道數學題的學生，比讀 AI 答案的學生記得解法久得多。"], "wu": ["Therefore, letting AI do the thinking for students removes the very purpose that homework is meant to serve.", "因此，讓 AI 替學生思考，就失去了作業原本的根本目的。"]}, {"t": "Cheating and Dishonesty 作弊與不誠實", "ts": ["AI makes it extremely easy for students to hand in work that is not their own.", "AI 讓學生非常容易交出不是自己完成的作業。"], "ex": ["A full essay or a set of answers can be produced in seconds, and teachers often cannot tell who really wrote it.", "一整篇作文或一整套答案幾秒內就能產生，老師常常無法分辨究竟是誰寫的。"], "eg": ["Some students who hand in excellent essays at home cannot write a clear paragraph during an in-class test.", "有些在家交出優秀作文的學生，在課堂測驗時卻寫不出一段通順的段落。"], "wu": ["As a result, homework no longer shows teachers what their students can actually do on their own.", "因此，作業不再能讓老師看出學生獨立時真正的能力。"]}, {"t": "Errors and False Information 錯誤與不實資訊", "ts": ["AI tools often produce answers that sound confident and convincing but are in fact completely wrong.", "AI 工具經常產生聽起來很有把握、很有說服力，但其實完全錯誤的答案。"], "ex": ["They can invent facts, dates and sources, and young students usually lack the knowledge to notice the mistakes.", "它們可能捏造事實、日期和資料來源，而年輕學生通常缺乏足夠知識察覺這些錯誤。"], "eg": ["A history report based on AI answers may include a quotation that no historical figure ever actually said.", "一份根據 AI 答案寫成的歷史報告，可能包含一句從來沒有任何歷史人物說過的引言。"], "wu": ["Consequently, students may learn false information and get into the habit of trusting technology far too easily.", "因此，學生可能學到錯誤資訊，並養成太輕易相信科技的習慣。"]}, {"t": "Dependence 過度依賴", "ts": ["Relying on AI for every piece of homework can leave students unable to work properly without it.", "每份作業都依賴 AI，可能讓學生沒有它就無法好好做事。"], "ex": ["When every difficult question is answered instantly, students lose the patience and confidence to think for themselves.", "當每個難題都能立刻得到答案，學生就會失去獨立思考的耐心與自信。"], "eg": ["Students who use AI for every assignment often panic in exams, where no such help is allowed.", "每份作業都用 AI 的學生，到了不能使用這類協助的考試時常常驚慌失措。"], "wu": ["In other words, AI may make today's homework easier, but it can seriously weaken the abilities students need tomorrow.", "換句話說，AI 或許能讓今天的作業變輕鬆，卻可能嚴重削弱學生明天需要的能力。"]}]}, "agree": [["AI assistant within reach · homework", "**Whether** teachers approve **or not, most** students **now have** an AI assistant within reach whenever they do homework."], ["prohibit or teach?", "**Rather than** pretending these tools do not exist, schools **must decide whether to** prohibit them **or to** teach students to use them well."], ["stance: allow · tutor not ghost-writer · support + future", "**I agree that** students should be allowed to use AI for homework, **provided that** it serves as a tutor rather than a ghost-writer, **since** it offers personalised support and prepares them for a world in which such tools are everywhere."], ["patient tutor · any hour", "**The strongest argument in favour is that** AI can act as a patient tutor available at any hour."], ["30 students · several explanations · shy students", "**Unlike** a teacher **responsible for** thirty students, an AI **can** explain a concept in several different ways **until** it makes sense, and shy students can ask questions they would be too embarrassed to raise in class."], ["passive voice · ten examples · favourite sport", "**A student** struggling with the passive voice, **for instance, could ask for** ten example sentences about a favourite sport **and then** compare their own attempts with them."], ["→ accelerates learning", "**Used in this way,** AI **does not replace** learning **but** accelerates it."], ["fairer support", "AI **also makes** academic support **considerably fairer**."], ["private tutoring = privilege · free AI · prompts as future skill", "**Whereas** private tutoring **has long been** a privilege of families who can afford it, a free AI tool **gives** every student access to instant explanations and feedback; **moreover, since** most future careers will involve AI, learning to prompt precisely and question answers **is a skill as fundamental as** using a search engine."], ["concession: copying", "**Admittedly,** some students **will be tempted to** copy whatever the AI produces and submit it as their own."], ["rebuttal: submit prompts · oral defence · ban → underground", "**However, clear rules, such as** requiring students to submit their prompts or explain their answers orally, **make** such shortcuts **easy to detect,** and banning AI **would only** drive its use underground."], ["restate: permit with responsible use", "**In conclusion,** AI **should be permitted as** a homework aid, **as long as** schools teach responsible use."], ["not whether but how well", "**The question is not whether** students will use AI, **but whether** they will learn to use it well."]], "disagree": [["essay in 10 seconds · paste", "A complete essay **can now be produced in** ten seconds, **ready to** be pasted into a homework file with a single click."], ["teachers can't tell student vs machine", "**Since** generative AI became freely available, teachers **have found it increasingly difficult to** tell which assignments students have written and which have been produced by machines."], ["stance: disagree · removes effort + easy dishonesty", "**I disagree that** students should be allowed to use AI for homework, **because it removes the very** effort **through which** learning takes place and makes dishonesty effortless."], ["learning = struggle", "**The fundamental problem is that** learning happens in the struggle itself."], ["20 minutes wrestling vs instant answer", "**When** a student wrestles with a difficult problem for twenty minutes, the effort itself **strengthens** understanding and memory; **when** an AI supplies the answer instantly, **little is** retained, and homework **becomes** a performance **rather than** practice."], ["polished homework · weak in exams", "**This is why** many teachers report students whose homework is polished but who struggle to write a coherent paragraph under exam conditions."], ["→ homework stops revealing ability", "Homework, **in other words, ceases to** reveal what a student can actually do, which is its entire purpose."], ["dishonesty + uncritical trust", "**Moreover,** AI **encourages both** dishonesty **and** an uncritical trust in technology."], ["produce not check · invented sources · lost habits", "**Most** students **do not** use these tools **to** check a draft; **they** use them **to** produce one, **and because** AI confidently invents dates, quotations and sources, inexperienced users copy errors they cannot detect, **gradually losing** both the habit of checking facts and the confidence to think independently."], ["concession: free tutoring", "**Supporters argue that** AI provides free tutoring for students who cannot afford private lessons."], ["rebuttal: teachers · libraries · not a tutor", "**Nevertheless,** teachers, libraries and classmates **already offer** that support, and a tutor **who** completes the work for you **is hardly** a tutor **at all**."], ["restate: student's own work", "**To sum up,** homework **should remain** the student's own work, and AI **should play no part in it**."], ["never struggles → never grows", "**A** mind **that never** struggles, **after all, never** grows."]], "vocab": [["ghost-writer", "代筆者；槍手"], ["personalised support", "個人化的協助"], ["accelerate", "加速"], ["drive (sth) underground", "迫使（某事）轉入地下"], ["generative AI", "生成式人工智慧"], ["wrestle with", "努力解決；與……搏鬥"], ["coherent", "有條理的；連貫的"], ["uncritical trust", "不加批判的信任"]]};

window.PET_ESSAY_ADV[10] = {"args": {"agree": [{"t": "Attention Is Everything 專注就是一切", "ts": ["Mobile phones seriously damage students' concentration in class, even when they are switched to silent mode.", "即使調成靜音，手機仍會嚴重損害學生上課時的專注力。"], "ex": ["Each notification breaks a student's train of thought, and it can take several minutes to focus again.", "每一則通知都會打斷學生的思路，而重新專心可能需要好幾分鐘。"], "eg": ["UNESCO's 2023 education report linked heavy phone use in school with lower academic results in many countries.", "聯合國教科文組織 2023 年的教育報告指出，許多國家學生在校大量使用手機與學業成績較低有關。"], "wu": ["Therefore, removing phones from the classroom gives students back the attention that real learning requires.", "因此，讓手機離開教室能讓學生找回真正學習所需的專注力。"]}, {"t": "Cheating and Filming 作弊與偷拍", "ts": ["Phones make cheating in tests and secretly filming people in class much easier than ever before.", "手機讓考試作弊和在課堂上偷拍他人變得比以往容易許多。"], "ex": ["With a phone, students can share test answers in seconds or record classmates and teachers without their permission.", "有了手機，學生可以在幾秒內分享考試答案，或在未經同意的情況下錄下同學和老師。"], "eg": ["A short video of a classmate making a mistake can spread across social media before the lesson has even ended.", "一段同學出糗的短片，可能在下課之前就已經在社群媒體上傳開。"], "wu": ["As a result, a ban protects both fair assessment and the privacy of students and teachers alike.", "因此，禁用手機既能保障公平的評量，也能同時保護學生和老師的隱私。"]}, {"t": "Real Social Interaction 真實的人際互動", "ts": ["Without phones, students talk to each other more during the school day and build stronger friendships.", "沒有手機時，學生在校期間彼此交談得更多，友誼也更穩固。"], "ex": ["When everyone is looking down at a screen during breaks, conversation and group activities quickly disappear.", "當每個人下課時都低頭盯著螢幕，對話和團體活動很快就消失了。"], "eg": ["Schools that have introduced phone pouches often report that students chat, play games and read together during breaks.", "引進手機收納袋的學校常表示，學生在下課時間會一起聊天、玩遊戲和閱讀。"], "wu": ["Consequently, a phone-free school becomes a friendlier and more connected place for everyone in it.", "因此，沒有手機的學校對每個人來說都會變成更友善、更有連結感的地方。"]}, {"t": "A Fairer Classroom 更公平的教室", "ts": ["A phone ban creates a more equal classroom environment for all students, whatever their family background.", "禁用手機能為所有學生創造更平等的教室環境，不論他們的家庭背景如何。"], "ex": ["Expensive phones can become a symbol of status and cause pressure or teasing among classmates.", "昂貴的手機可能成為身分地位的象徵，在同學之間造成壓力或嘲弄。"], "eg": ["When all learning devices are school tablets, a student with an old phone is not left behind or embarrassed.", "當所有學習用的裝置都是學校的平板，拿舊手機的學生就不會跟不上或感到難堪。"], "wu": ["In short, removing phones lets students compete on effort rather than on what they own.", "簡而言之，移除手機讓學生比的是努力，而不是擁有什麼。"]}], "disagree": [{"t": "A Useful Learning Tool 實用的學習工具", "ts": ["Smartphones can be powerful learning tools in the classroom when teachers use them with clear purposes.", "只要老師有明確目的地使用，智慧型手機在課堂上可以成為強大的學習工具。"], "ex": ["Students can look up words, check facts and take photos of notes or experiments in seconds.", "學生可以在幾秒內查單字、查證事實，並拍下筆記或實驗過程。"], "eg": ["Many teachers use apps such as Kahoot and Quizlet on students' phones to turn vocabulary review into a lively game.", "許多老師用學生手機上的 Kahoot 和 Quizlet 等應用程式，把單字複習變成熱鬧的遊戲。"], "wu": ["Therefore, banning phones means throwing away a free and flexible learning resource that students already own.", "因此，禁用手機等於丟掉一項學生本來就擁有、免費又靈活的學習資源。"]}, {"t": "Emergencies and Family 緊急狀況與家庭聯繫", "ts": ["Phones allow students and parents to contact each other quickly and directly when an emergency happens.", "手機讓學生和家長在發生緊急狀況時能迅速、直接地聯絡彼此。"], "ex": ["Accidents, sudden illness or natural disasters can happen at any time, and parents want to know their children are safe.", "意外、突發疾病或天災隨時可能發生，家長希望確認孩子平安。"], "eg": ["After an earthquake in Taiwan, many parents feel calmer as soon as they receive a short message from their child.", "台灣發生地震後，許多家長一收到孩子傳來的簡短訊息就放心多了。"], "wu": ["As a result, a complete ban can cause unnecessary worry for families at the very moments when contact matters most.", "因此，全面禁止可能在最需要聯絡的時刻，造成家庭不必要的擔憂。"]}, {"t": "Teaching Self-Control 教導自我控制", "ts": ["Schools should teach students how to manage their phones instead of simply taking them away.", "學校應該教學生如何管理手機，而不是直接沒收。"], "ex": ["Young people will use phones for the rest of their lives, so they need to practise knowing when to put them down.", "年輕人這輩子都會使用手機，所以他們需要練習知道何時該放下。"], "eg": ["A class rule that phones stay face-down unless the teacher asks for them helps students build good habits step by step.", "「除非老師要求，否則手機正面朝下」的班規，能幫助學生一步步養成好習慣。"], "wu": ["Consequently, students leave school better prepared for adult life and for workplaces where phones are everywhere.", "因此，學生離開學校時，能為成年生活以及處處有手機的職場做更好的準備。"]}, {"t": "Hard to Enforce 難以執行", "ts": ["A complete phone ban is difficult and time-consuming for teachers to enforce in a busy school.", "在忙碌的學校裡，全面禁用手機對老師來說很難執行，也很耗時間。"], "ex": ["Students often hide phones under their desks, and teachers must spend lesson time checking bags instead of teaching.", "學生常把手機藏在桌子底下，老師得花上課時間檢查書包，而不是教學。"], "eg": ["In some schools with strict bans, students simply bring a second, cheaper phone to hand in while keeping their real one.", "在一些嚴格禁用的學校，學生乾脆帶第二支便宜的手機來繳交，自己留著真正的那支。"], "wu": ["In other words, a ban turns teachers into police officers without solving the real problem.", "換句話說，禁令把老師變成警察，卻沒有解決真正的問題。"]}]}, "agree": [["screens under desks · teacher speaking", "**Walk into** almost any secondary-school classroom **and you are likely to see** screens glowing beneath desks while the teacher is speaking."], ["France · Netherlands · others debating", "**Several countries, including** France and the Netherlands, **have already** restricted phones in schools, **and many others are now debating whether to** follow suit."], ["stance: ban · concentration + face-to-face", "**I agree that** mobile phones should be banned from classrooms, **since they undermine** concentration **and erode** the face-to-face interaction **on which** learning depends."], ["attention fragmented", "**The most compelling reason is that** attention is the foundation of learning, and phones fragment it."], ["silent phone draws attention · notification · minutes to recover", "**Even** a phone lying silently on a desk **draws** part of a student's attention, and each notification **interrupts** a train of thought **that can take** several minutes **to** recover."], ["UNESCO 2023 report · phones & lower performance", "**It is worth noting that** UNESCO's 2023 Global Education Monitoring Report linked excessive phone use to lower academic performance, **recommending that** phones be used in class only when they support learning."], ["→ the device usually wins", "**If** a device competes with the teacher for attention, **it is** the device **that usually** wins."], ["healthier and fairer", "**Beyond** academic results, a phone-free classroom **is a healthier and fairer** environment."], ["talk not scroll · shared answers · filming · cyberbullying", "**Without** phones, students **are more inclined to** talk to one another between lessons **rather than** scroll in silence, and teachers **no longer have to worry about** answers being shared during tests or classmates being filmed without consent, **a form of** bullying **that** can follow a child long after the school day ends."], ["concession: dictionary · calculator · emergencies", "**Admittedly,** phones **can serve as** dictionaries or calculators, and parents understandably want to reach their children in an emergency."], ["rebuttal: school tablets · school office", "**However,** school tablets **can perform the same functions under** a teacher's supervision, and urgent messages **can always be passed on through** the school office."], ["restate: restore concentration + contact", "**In conclusion,** banning phones from classrooms **would restore** the concentration and human contact **that** effective learning **requires**."], ["everyone looks up", "A classroom **should be the one place where** everyone looks up."]], "disagree": [["dictionary · calculator · library in pocket · lock away", "**Most** teenagers **now carry** a dictionary, a calculator and a library in their pockets, **yet a growing number of** schools **want to** lock them away."], ["bans spreading · do they teach anything?", "**As** phone bans **spread** across education systems, **few people stop to ask whether** they actually teach students anything."], ["stance: disagree · learning tool + self-control", "**I disagree that** mobile phones should be banned in classrooms, **since** they can be valuable learning tools **and a ban avoids the more important task of** teaching self-control."], ["most versatile tool", "**The first point to consider is that** a phone is the most versatile learning tool many students own."], ["look up word · pronunciation · photograph experiment · no cost", "**In** a language lesson, students can look up a word or hear its pronunciation in seconds, **while in** science they can photograph an experiment or check a figure, **all without** the school buying expensive equipment."], ["Kahoot · Quizlet · vocabulary competition", "Quiz platforms **such as** Kahoot and Quizlet, **which** run on ordinary smartphones, **have become** a familiar feature of classrooms in many countries, **turning** vocabulary review **into** a lively competition."], ["→ more engaging lessons", "**Far from being** a distraction, **then,** a phone in the hands of a skilled teacher **can make** lessons more engaging."], ["ban teaches wrong lesson", "**More importantly,** a blanket ban **teaches the wrong lesson**."], ["adult life · when to put it away · under desks · police", "**Since** young people will spend their adult lives managing phones at work and at home, learning when to put the device away **is precisely the kind of** skill **that** schools **ought to** cultivate; a ban, **by contrast, simply** drives phones under desks and turns teachers into police officers."], ["concession: notifications · cheating", "**It is true that** notifications can break concentration **and that** phones make cheating easier."], ["rebuttal: face-down rule · collect in tests", "**But** a simple rule requiring phones to stay face-down unless the teacher asks for them, **combined with** collecting devices during tests, **addresses both problems without resorting to** a ban."], ["restate: manage, not confiscate", "**In short,** schools **should** teach students to manage their phones **rather than** confiscate them."], ["self-control ≠ removing temptation", "Self-control **cannot be learned by** removing every temptation."]], "vocab": [["follow suit", "跟進；仿效"], ["undermine concentration", "削弱專注力"], ["erode", "侵蝕；逐漸削弱"], ["fragment (attention)", "使（注意力）分散破碎"], ["a train of thought", "思路"], ["versatile", "多功能的；用途廣泛的"], ["blanket ban", "全面禁止"], ["resort to", "訴諸；採取（不得已的手段）"]]};

window.PET_ESSAY_ADV[11] = {"args": {"agree": [{"t": "Shrinking Attention Spans 注意力越來越短", "ts": ["Watching short videos for long periods makes it harder for children to concentrate on slower activities.", "長時間看短影音會讓孩子更難專注於步調較慢的活動。"], "ex": ["Each clip offers something new within seconds, so the brain comes to expect constant stimulation and finds lessons or books boring.", "每段影片幾秒內就給出新刺激，大腦因此習慣不斷的刺激，覺得上課或讀書很無聊。"], "eg": ["Many teachers notice that pupils who scroll every evening struggle to sit through a forty-minute class without fidgeting.", "許多老師發現，每晚滑影片的學生很難安靜上完四十分鐘的課。"], "wu": ["Therefore, a habit formed for fun can damage the very skills that school learning depends on.", "因此，一個為了娛樂而養成的習慣，可能會損害學校學習所仰賴的能力。"]}, {"t": "Addictive Design 成癮設計", "ts": ["Short-video apps are deliberately designed to keep children watching for as long as possible.", "短影音應用程式是刻意設計來讓孩子盡可能看久一點的。"], "ex": ["Features such as infinite scrolling and autoplay remove any natural stopping point, so young users rarely decide to put the phone down.", "無限滑動和自動播放等功能取消了自然的停止點，年幼的使用者很少會主動放下手機。"], "eg": ["A child who opens an app to watch one funny clip can easily find that an hour has passed without noticing.", "一個孩子原本只想看一段搞笑影片，很容易不知不覺就過了一個小時。"], "wu": ["As a result, children lose control over their own time to a product built to capture it.", "結果，孩子把自己的時間控制權交給了一個專門用來搶奪時間的產品。"]}, {"t": "Inappropriate Content 不適當內容", "ts": ["Algorithms can expose children to content that is unsuitable or even dangerous for their age.", "演算法可能讓孩子接觸到不適合其年齡、甚至危險的內容。"], "ex": ["Recommendation systems aim to maximise viewing time rather than protect young viewers, and children cannot easily judge what is true or safe.", "推薦系統的目標是延長觀看時間而非保護年幼觀眾，而孩子也不容易判斷什麼是真實或安全的。"], "eg": ["Risky online 'challenges' have spread quickly among young users, sometimes leading to serious injuries.", "危險的網路「挑戰」曾在年輕使用者之間迅速傳播，有時甚至造成嚴重傷害。"], "wu": ["Consequently, leaving children alone with these apps puts their safety and judgement at risk.", "因此，讓孩子獨自使用這些應用程式，會使他們的安全與判斷力陷入風險。"]}, {"t": "Lost Sleep and Play 失去的睡眠與遊戲", "ts": ["Time spent scrolling often replaces activities that growing children genuinely need.", "滑影片的時間往往取代了成長中的孩子真正需要的活動。"], "ex": ["Sleep, outdoor play and reading all support physical and mental development, but they are easily pushed aside by screens.", "睡眠、戶外遊戲和閱讀都有助於身心發展，卻很容易被螢幕擠掉。"], "eg": ["A child who watches videos in bed may fall asleep an hour later than usual and arrive at school tired the next morning.", "在床上看影片的孩子可能比平常晚一小時入睡，第二天早上疲倦地到校。"], "wu": ["In short, the hidden cost of short videos is everything children are not doing while they watch.", "簡言之，短影音的隱藏代價，就是孩子觀看時沒有去做的那些事。"]}], "disagree": [{"t": "Bite-sized Learning 小份量學習", "ts": ["Well-made short videos can explain ideas in a quick, visual and memorable way.", "製作精良的短影音能以快速、視覺化且好記的方式解釋概念。"], "ex": ["By focusing on a single idea with clear images, a one-minute clip can spark curiosity that a long text may fail to create.", "一分鐘的影片專注於單一概念並搭配清楚的畫面，能激發長篇文字未必能引起的好奇心。"], "eg": ["Many popular channels show simple science experiments or teach English pronunciation in under sixty seconds.", "許多熱門頻道在六十秒內示範簡單的科學實驗或教英文發音。"], "wu": ["Therefore, short videos can act as a gateway to deeper learning rather than a replacement for it.", "因此，短影音可以成為深入學習的入口，而不是學習的替代品。"]}, {"t": "Creativity 創造力", "ts": ["Short-video platforms give children a chance to create content, not just consume it.", "短影音平台讓孩子有機會創作內容，而不只是觀看。"], "ex": ["Planning, filming and editing a clip requires children to write a script, make design choices and think about their audience.", "規劃、拍攝和剪輯影片需要孩子寫腳本、做設計決定，並思考觀眾的感受。"], "eg": ["A pupil might film a short cooking tutorial or a stop-motion animation for a school project and share it with classmates.", "學生可以為學校專題拍一段簡短的料理教學或定格動畫，並與同學分享。"], "wu": ["As a result, children develop digital and communication skills that will be useful in many future careers.", "因此，孩子能培養將來許多職業都用得到的數位與溝通能力。"]}, {"t": "Culture and Connection 文化與連結", "ts": ["Short videos are an important part of how children share culture and stay connected with friends.", "短影音是孩子分享文化、與朋友保持聯繫的重要方式。"], "ex": ["Jokes, songs and dance trends spread through these platforms, and children talk about them at school the next day.", "笑話、歌曲和舞蹈潮流透過這些平台傳播，孩子隔天會在學校討論。"], "eg": ["A child who is completely banned from short videos may feel left out when classmates discuss the latest popular trend.", "完全被禁止看短影音的孩子，在同學討論最新流行話題時可能會覺得被排擠。"], "wu": ["Thus, sensible access helps children feel part of their peer group rather than isolated from it.", "因此，適度接觸能讓孩子融入同儕，而不是被孤立。"]}, {"t": "Supervision, Not Prohibition 監督而非禁止", "ts": ["The risks of short videos can be managed through supervision rather than an outright ban.", "短影音的風險可以透過監督來控管，而不需要全面禁止。"], "ex": ["Child accounts, screen-time limits and content filters reduce exposure to harmful material while keeping the benefits.", "兒童帳號、螢幕使用時間限制和內容過濾器能減少接觸有害內容，同時保留好處。"], "eg": ["Parents who watch videos together with their children can explain what they see and set clear daily limits.", "和孩子一起看影片的父母，可以解釋影片內容並設定明確的每日時限。"], "wu": ["In other words, the problem lies not in the medium but in leaving children to use it alone.", "換句話說，問題不在於媒介本身，而在於讓孩子獨自使用它。"]}]}, "agree": [["fifteen-second clips · children captivated", "**Rarely has** a single technology **captured** children's attention **as completely as** the endless stream of fifteen-second videos."], ["TikTok · Shorts · 'harmless' · teachers & doctors worried", "**While** platforms such as TikTok and YouTube Shorts **present themselves as** harmless entertainment, growing numbers of teachers and paediatricians **are voicing concern about** their effect on young minds."], ["stance: more harm than good · concentration + unsuitable content", "**On balance, I agree that** short videos do children more harm than good, **not only because** they erode the capacity for sustained concentration **but also because** they expose young viewers to content they are ill-equipped to judge."], ["attention / concentration", "**The most insidious effect concerns** children's ability to concentrate."], ["novelty every few seconds · constant stimulation · slower tasks feel dull", "**Because** each clip delivers a fresh burst of novelty within seconds, the brain **becomes accustomed to** constant stimulation, **and** anything slower, whether a textbook chapter, a piano exercise or a conversation, **begins to feel** intolerably dull."], ["teachers report · 40-minute lesson · novel", "**It is hardly surprising, then, that** teachers describe pupils who scroll every evening struggling to follow a forty-minute lesson, **let alone** finish a novel of two hundred pages."], ["entertainment habit → undermines education", "**In other words,** a habit formed for entertainment **ends up undermining the very** skills **on which** education depends."], ["what algorithms deliver", "**Equally worrying is** the content that algorithms deliver."], ["TV planned by adults · algorithm maximises viewing · dangerous challenges · misinformation", "**Unlike** a television schedule, **which** is planned by adults for a young audience, an algorithm **is designed to** maximise viewing time **rather than** wellbeing, **so** a child who watches one harmless prank may soon be served dangerous 'challenges', distorted beauty ideals or outright misinformation, **none of which** a seven-year-old can recognise as such."], ["concession: some clips educational", "**Admittedly,** some short videos **are genuinely** educational, explaining a science experiment or an English idiom in under a minute."], ["rebuttal: exception · next clip chosen by algorithm", "**Yet these are the exception rather than the rule, and even** the most useful clip **is followed** automatically **by** another, chosen not by a teacher but by an algorithm."], ["restate: overwhelmingly negative", "**In conclusion, while** short videos **are unlikely to** disappear, **I remain convinced that** their effect on children's concentration and judgement is overwhelmingly negative."], ["build attention, not surrender it", "Childhood **should be spent** building attention, **not** surrendering it fifteen seconds at a time."]], "disagree": [["comic books · video games · new media feared", "**Every generation of** parents **has found** a new medium to fear, **from** comic books in the 1950s **to** video games in the 1990s."], ["short videos = latest target · claim rarely examined", "Short-video platforms **are simply the latest** target, **and the claim that** they are inherently bad for children **is repeated so often that** it is rarely examined."], ["stance: disagree · supervised → learning + creativity", "**I disagree with this view: provided that** viewing is supervised and sensibly limited, short videos can support children's learning and give them an outlet for genuine creativity."], ["efficient learning", "**The first point worth making is that** short videos can be a remarkably efficient way to learn."], ["one idea · vivid images · sparks curiosity", "**By** condensing a single idea into a minute of vivid images, well-made clips **hold** a young viewer's attention **long enough to** spark a curiosity that a dense page of text often fails to ignite."], ["science · maths puzzles · pronunciation · seek longer explanations", "Channels **devoted to** science experiments, mathematical puzzles and English pronunciation **attract** millions of young viewers, **many of whom** go on to seek out longer explanations of their own accord."], ["gateway, not substitute", "**Seen in this light,** a short video **is less a** substitute for learning **than a** gateway to it."], ["creative opportunity", "**Just as valuable is** the creative opportunity these platforms offer."], ["plan · film · edit · script · audience · digital skills", "**Rather than merely** consuming, children **increasingly** plan, film and edit clips of their own, **a process that involves** drafting a script, choosing music and thinking carefully about an audience; **in doing so, they acquire** practical digital skills that are likely to prove useful in careers ranging from marketing to journalism."], ["concession: unsuitable material", "**It would be naive to deny that** algorithms sometimes push unsuitable material towards young users."], ["rebuttal: child accounts · time limits · parents watching", "**However,** child accounts, screen-time limits and, above all, parents who watch alongside their children **reduce this risk considerably, making** supervision **a far better answer than** an outright ban."], ["restate: not harmful in themselves", "**In conclusion,** short videos **are not** harmful **in themselves; what matters is how** they are used and who is watching with the child."], ["danger = navigating alone", "**The real danger lies not in** the medium **but in** leaving children to navigate it alone."]], "vocab": [["erode", "侵蝕；逐漸削弱"], ["sustained concentration", "持續的專注力"], ["ill-equipped (to do)", "沒有能力（做某事）的；準備不足的"], ["intolerably dull", "無聊到難以忍受"], ["outright misinformation", "徹頭徹尾的錯誤資訊"], ["of one's own accord", "自發地；主動地"], ["a gateway to", "通往……的入口"], ["an outright ban", "全面禁止"]]};

window.PET_ESSAY_ADV[12] = {"args": {"agree": [{"t": "A Health Safety Net 健康安全網", "ts": ["Compulsory sport ensures that every student gets at least some regular physical exercise.", "必修運動確保每位學生至少都有規律的身體活動。"], "ex": ["Many teenagers spend long hours sitting at desks and screens, and some would not exercise at all without a school requirement.", "許多青少年長時間坐在書桌和螢幕前，若學校沒有規定，有些人根本不會運動。"], "eg": ["For students whose families cannot afford gym fees or private lessons, school PE may be their only chance to play a sport.", "對於負擔不起健身房或私人課程的家庭，學校體育課可能是孩子唯一能運動的機會。"], "wu": ["Therefore, making sport compulsory protects the health of all students, not just the naturally active ones.", "因此，讓運動成為必修能保護所有學生的健康，而不只是天生好動的那些人。"]}, {"t": "Better Brains 更好的大腦", "ts": ["Regular exercise improves students' concentration, mood and memory.", "規律運動能提升學生的專注力、情緒和記憶力。"], "ex": ["Physical activity increases blood flow to the brain and reduces stress, which makes it easier to focus during lessons.", "運動能增加腦部血流並減輕壓力，讓學生上課時更容易專心。"], "eg": ["Students who play badminton or basketball after school often report that they sleep better and feel calmer before exams.", "放學後打羽球或籃球的學生常表示自己睡得更好，考前也更平靜。"], "wu": ["As a result, time spent on sport supports academic work rather than taking time away from it.", "因此，花在運動上的時間是在幫助學業，而不是佔用讀書時間。"]}, {"t": "Teamwork and Resilience 團隊合作與韌性", "ts": ["Team sports teach students to cooperate and to cope with failure.", "團隊運動教導學生合作，並學會面對失敗。"], "ex": ["During a match, players must communicate, support each other under pressure and accept defeat without giving up.", "比賽中，球員必須溝通、在壓力下互相支持，並在落敗時不輕言放棄。"], "eg": ["A volleyball team that loses an early set has to stay calm, change its tactics and fight back together.", "一支排球隊輸掉前一局時，必須保持冷靜、調整戰術並一起反攻。"], "wu": ["In short, sport develops qualities such as resilience and teamwork that employers highly value.", "簡言之，運動能培養雇主非常重視的韌性與團隊合作等特質。"]}, {"t": "Habits for Life 終身習慣", "ts": ["Students who discover a sport they enjoy at school are more likely to stay active as adults.", "在學校找到喜愛運動的學生，成年後更可能保持活躍。"], "ex": ["A compulsory programme gives every student the chance to try different activities and find one that suits them.", "必修課程讓每位學生都有機會嘗試不同活動，找到適合自己的那一項。"], "eg": ["A student who reluctantly tries swimming in PE class may end up swimming several times a week for decades.", "一個在體育課勉強嘗試游泳的學生，最後可能幾十年來每週游好幾次。"], "wu": ["Consequently, required sport can plant the seeds of a healthy lifestyle that lasts a lifetime.", "因此，必修運動能種下延續一生的健康生活習慣。"]}], "disagree": [{"t": "Forced Sport Breeds Resentment 被迫運動只會讓人反感", "ts": ["Forcing students to play sport can make them dislike exercise rather than enjoy it.", "強迫學生運動，可能讓他們討厭運動，而不是享受運動。"], "ex": ["When exercise feels like a punishment, students link it with discomfort and embarrassment instead of fun.", "當運動感覺像懲罰時，學生會把它和不適與尷尬聯想在一起，而不是樂趣。"], "eg": ["Students made to run laps in the summer heat often try to avoid any kind of exercise once PE becomes optional.", "被迫在夏日高溫下跑操場的學生，一旦體育課變成選修，往往會逃避任何運動。"], "wu": ["Therefore, a rule meant to build healthy habits may actually discourage them.", "因此，原本用來培養健康習慣的規定，反而可能讓人失去運動的動力。"]}, {"t": "Not Everyone Is Athletic 不是人人都擅長運動", "ts": ["Compulsory sport can be humiliating for students with little athletic ability or health problems.", "對運動能力不佳或有健康問題的學生而言，必修運動可能令人難堪。"], "ex": ["In competitive games, weaker players are easily blamed for mistakes or left out by their teammates.", "在競賽中，較弱的球員很容易因失誤被責怪，或被隊友冷落。"], "eg": ["A student with asthma may struggle to keep up in a football match and feel embarrassed in front of the whole class.", "有氣喘的學生在足球賽中可能跟不上，在全班面前感到難為情。"], "wu": ["As a result, these students may lose confidence instead of gaining fitness.", "結果，這些學生可能失去自信，而不是變得更健康。"]}, {"t": "Time and Priorities 時間與優先順序", "ts": ["Required sport takes valuable time away from students' other interests and studies.", "必修運動會佔用學生發展其他興趣與學業的寶貴時間。"], "ex": ["Teenagers already have heavy schedules, and every hour of compulsory training is an hour they cannot spend on their own strengths.", "青少年的行程已經很滿，每多一小時的強制訓練，就少一小時發展自己的專長。"], "eg": ["A student who hopes to study music at university may need that time to practise the piano rather than play basketball.", "希望大學念音樂的學生，可能需要用那段時間練鋼琴，而不是打籃球。"], "wu": ["Thus, schools should respect that students have different talents and priorities.", "因此，學校應該尊重學生擁有不同的才能與優先事項。"]}, {"t": "Choice Works Better 選擇更有效", "ts": ["Offering a range of optional activities is more effective than forcing everyone to play a sport.", "提供多元的選修活動，比強迫每個人運動更有效。"], "ex": ["Students are more motivated when they can choose an activity that matches their personality and abilities.", "當學生能選擇符合自己個性與能力的活動時，他們會更有動力。"], "eg": ["A school that offers dance, yoga, hiking and cycling clubs may attract students who would never join a competitive team.", "提供舞蹈、瑜伽、登山和自行車社團的學校，能吸引從不參加競賽隊伍的學生。"], "wu": ["In other words, choice gets more students moving than compulsion ever could.", "換句話說，給予選擇比強制規定更能讓學生動起來。"]}]}, "agree": [["more sitting than ever · sports field = last place to sweat", "**At a time when** children spend more hours sitting down than any previous generation, the school sports field **may be the last place** many of them ever break into a sweat."], ["debate · compulsory on timetable?", "**This has prompted a debate about whether** sport should be a compulsory part of every student's timetable."], ["stance: should be · health + character", "**I firmly believe that it should, since** regular exercise safeguards students' physical and mental health **and** develops qualities **that no** classroom lesson **can fully** teach."], ["health", "**The strongest argument concerns** health."], ["obesity rising · desks & screens · every student · regardless of background", "**With** rates of childhood obesity rising in much of the world and teenagers spending long evenings at desks and screens, compulsory sport **guarantees that** every student, **regardless of** family background, takes part in vigorous activity each week."], ["sleep · less anxiety · concentration · better grades", "**Research consistently links** regular exercise **not only to** fitness **but also to** better sleep, lower anxiety and sharper concentration, **which means that** time on the pitch can actually improve performance in the classroom."], ["supports, not distracts", "**Far from being** a distraction from academic work, **then,** sport supports it."], ["character from team sport", "**No less important is** the character that team sport builds."], ["narrow lead · relay · cooperate · lose gracefully · employers value", "**Whether** students are defending a narrow lead in a basketball match **or** finishing a relay after a poor start, **they learn to** cooperate under pressure, accept defeat with grace and try again after failure; **it is precisely these** qualities **that** employers value in graduates, **yet they are seldom** acquired from a textbook."], ["concession: unathletic students suffer", "**Admittedly,** forcing an unathletic student into a competitive team can be a miserable experience."], ["rebuttal: broaden choice · swimming · dance · badminton", "**The solution, however, is not to** abolish the requirement **but to** broaden it, **so that** students can choose from activities such as swimming, dance or badminton according to their abilities and interests."], ["restate: benefits all · with choice", "**In conclusion, I am convinced that** compulsory sport benefits every student, **provided that** schools offer genuine choice."], ["healthy body = foundation", "A healthy body, **after all, is the foundation on which** every other achievement rests."]], "disagree": [["picked last · PE memories", "**Few memories are as vivid for** unathletic adults **as** being picked last for a team in a school PE lesson."], ["some educators: everyone must play", "**Despite this, some** educators **argue that** every student should be obliged to play a sport at school."], ["stance: disagree · resentment + limited time", "**Although I recognise** the value of exercise, **I disagree with** making sport compulsory, **because** coercion tends to breed resentment **rather than** lifelong fitness, **and** students' limited time deserves to be spent developing their own strengths."], ["compulsion defeats its purpose", "**The central problem is that** compulsion often defeats its own purpose."], ["laps in midday heat · games they are poor at · sport = embarrassment", "**When** students **are made to** run laps in the midday heat or compete in games they are poor at, **what they learn is not** a love of exercise **but** a lasting association between sport and embarrassment."], ["adults avoid gyms · trace back to school PE", "**It is telling that** many adults **who** avoid gyms and sports clubs **trace** their reluctance **back to** humiliating experiences in school PE."], ["policy backfires", "**A policy intended to** create healthy habits, **therefore, may well** produce the opposite."], ["time = finite", "**A second concern is** time, which for most teenagers is already in short supply."], ["lessons · homework · exams · violin · coding · rest · talents elsewhere", "**Between** academic lessons, homework and preparation for high-stakes exams, many teenagers already have little free time, and an hour of mandatory training **is an hour that cannot be spent** practising the violin, learning to code or simply resting; **for a student whose** talents lie elsewhere, this trade-off **is hard to justify**."], ["concession: some would never exercise", "**It is true that some** students **would never** exercise **unless** they were required to."], ["rebuttal: optional range · hiking · yoga", "**Even so,** schools **could achieve far more by** offering an attractive range of optional activities, from hiking clubs to yoga, **than by** insisting that everyone play the same sport."], ["restate: encourage, not impose", "**In conclusion,** sport **should be** encouraged and made accessible to all, **but not** imposed on every student."], ["enthusiasm can't be compulsory", "Enthusiasm, **unlike** attendance, **cannot be made** compulsory."]], "vocab": [["break into a sweat", "開始流汗"], ["safeguard", "保護；維護"], ["regardless of", "不論；不管"], ["accept defeat with grace", "有風度地接受失敗"], ["breed resentment", "滋生怨恨"], ["defeat its own purpose", "適得其反；違背初衷"], ["trade-off", "權衡取捨"], ["be in short supply", "供應不足；短缺"]]};

window.PET_ESSAY_ADV[13] = {"args": {"agree": [{"t": "Money Must Be Earned 錢必須靠努力賺取", "ts": ["Linking pocket money to chores teaches children that money is earned through effort.", "把零用錢和家事連結，能教孩子錢是靠努力賺來的。"], "ex": ["In adult life income depends on work, so children who receive money for nothing may develop unrealistic expectations.", "成年後收入取決於工作，不勞而獲的孩子可能會產生不切實際的期待。"], "eg": ["A child who has to wash the car to afford a new comic book quickly learns how much work each coin represents.", "必須洗車才能買新漫畫的孩子，很快就會明白每一塊錢代表多少努力。"], "wu": ["Therefore, paid chores give children an early and realistic view of how the working world operates.", "因此，有報酬的家事讓孩子及早、實際地了解職場如何運作。"]}, {"t": "Responsibility at Home 在家的責任感", "ts": ["When pocket money depends on chores, children are more likely to complete their tasks properly.", "當零用錢取決於家事時，孩子更可能把工作做好。"], "ex": ["A clear reward motivates children to plan their time, keep their promises and finish a job instead of leaving it half done.", "明確的報酬能激勵孩子規劃時間、遵守承諾，並把事情做完而非做一半。"], "eg": ["A child who is paid for walking the dog every evening soon learns that skipping a day means losing money.", "每晚遛狗就能拿到錢的孩子，很快就會明白偷懶一天就會少賺錢。"], "wu": ["As a result, children develop reliable habits and the household runs more smoothly for everyone.", "因此，孩子能養成可靠的習慣，整個家也運作得更順利。"]}, {"t": "Budgeting Skills 理財能力", "ts": ["Earning their own money encourages children to think carefully about how they spend it.", "自己賺錢會促使孩子仔細思考如何花錢。"], "ex": ["Money that has taken effort to earn feels more valuable, so children are more willing to save and compare prices.", "辛苦賺來的錢感覺更珍貴，孩子因此更願意儲蓄和比價。"], "eg": ["A child saving chore money for a new bicycle may decide to skip buying snacks for several weeks.", "為了買新腳踏車而存家事零用錢的孩子，可能會決定好幾週不買零食。"], "wu": ["Consequently, paid chores lay the foundation for sensible money management in later life.", "因此，有報酬的家事為日後理性的理財打下基礎。"]}, {"t": "Appreciation of Housework 體會家務辛勞", "ts": ["Doing chores for pocket money helps children appreciate the work that keeps a home running.", "做家事賺零用錢能幫助孩子體會維持一個家需要多少努力。"], "ex": ["Once children have cleaned or cooked themselves, they understand how much time and energy these tasks require.", "孩子親自打掃或煮飯後，就會明白這些工作需要多少時間和精力。"], "eg": ["A teenager who has scrubbed the bathroom for a small reward may be less likely to leave a mess for others to clean up.", "為了小小報酬刷過浴室的青少年，比較不會把髒亂留給別人收拾。"], "wu": ["In short, the arrangement teaches gratitude as well as financial sense.", "簡言之，這種安排不只教會理財，也教會感恩。"]}], "disagree": [{"t": "Family Is Not a Job 家庭不是工作", "ts": ["Paying children for chores turns shared family responsibilities into paid services.", "付錢讓孩子做家事，會把家庭共同的責任變成有償服務。"], "ex": ["Children may start to believe that helping at home is optional and only worth doing when they want money.", "孩子可能開始認為幫忙家事是可有可無的，只有想要錢時才值得做。"], "eg": ["A child who already has enough savings may simply refuse to set the table because he or she does not need the cash.", "已經存夠錢的孩子，可能會因為不缺錢而直接拒絕擺碗筷。"], "wu": ["Therefore, the habit of helping one another freely, which holds a family together, is weakened.", "因此，維繫家庭的互相幫忙、不求回報的習慣會被削弱。"]}, {"t": "'How Much Will You Pay Me?' 「你要付我多少？」", "ts": ["Once chores have a price, children may start negotiating before they agree to help.", "一旦家事有了價格，孩子可能會先討價還價才答應幫忙。"], "ex": ["Every request becomes a deal, and parents can find themselves paying for tasks that children used to do willingly.", "每個請求都變成交易，父母可能發現自己得為孩子以前樂意做的事付錢。"], "eg": ["A parent who asks for help carrying shopping bags may be met with the question of how much the job is worth.", "父母請孩子幫忙提購物袋時，可能會被反問這份工作值多少錢。"], "wu": ["As a result, family life starts to feel like a business rather than a relationship.", "結果，家庭生活開始像一門生意，而不是一段關係。"]}, {"t": "Unfair to Poorer Families 對經濟較差的家庭不公平", "ts": ["Linking pocket money to chores can make children's rewards depend on their parents' income.", "把零用錢和家事綁在一起，會讓孩子的報酬取決於父母的收入。"], "ex": ["Wealthier parents can pay generously for small tasks, while others can offer very little for the same effort.", "較富裕的父母可以為小事大方付錢，而其他家庭對同樣的付出只能給很少。"], "eg": ["Two classmates who both wash dishes every night might earn completely different amounts for exactly the same work.", "兩個每晚都洗碗的同學，做一樣的工作卻可能拿到完全不同的金額。"], "wu": ["Thus, the system may teach children that effort is valued differently depending on family background.", "因此，這個制度可能讓孩子以為努力的價值會因家庭背景而不同。"]}, {"t": "An Allowance Teaches Budgeting Anyway 固定零用錢本身就能教理財", "ts": ["A regular allowance can teach money management without connecting it to household chores.", "固定的零用錢不必和家事掛勾，也能教孩子理財。"], "ex": ["When children must cover certain expenses with a fixed amount, they learn to plan, save and accept the results of their choices.", "當孩子必須用固定金額支付某些開銷時，他們會學到規劃、儲蓄並承擔選擇的後果。"], "eg": ["A pupil who spends a whole week's allowance on Monday learns the hard way to budget more carefully next time.", "週一就花光一週零用錢的學生，會從教訓中學會下次更謹慎地規劃。"], "wu": ["In other words, financial skills and family duties are best taught as separate lessons.", "換句話說，理財能力和家庭責任最好分開來教。"]}]}, "agree": [["first understanding of money · lifelong habits", "**How** children **first come to** understand money **may shape** their financial habits **for the rest of their lives**."], ["fixed allowance vs pay per job", "**Some** parents hand over a fixed allowance every week, **while others** pay only when a job around the house has been done."], ["stance: agree · effort = money + responsibility", "**I agree with the latter approach, as** linking pocket money to chores teaches children that money is earned through effort and encourages them to take responsibility at home."], ["work → reward", "**The most valuable lesson it offers is** the connection between work and reward."], ["adult income needs effort · money for nothing → unrealistic", "**In adult life,** income **rarely** arrives without effort, **and** a child **who** receives money for nothing **may grow up with** an unrealistic sense of how it is obtained."], ["wash the car · fold laundry · new book · spend carefully", "**By contrast,** a ten-year-old **who has to** wash the car or fold the laundry **in order to** afford a new book **quickly grasps** the value of each coin and tends to spend it more carefully."], ["chores = first, low-risk taste of work", "**In this sense,** chores **serve as** a child's first, low-risk introduction **to** the world of work."], ["responsibility", "**This arrangement also fosters** a stronger sense of responsibility."], ["plan the week · keep promises · finish properly · appreciate unpaid housework", "**When** pocket money **depends on** completing tasks reliably, children **learn to** plan their week, keep their promises and finish a job properly **rather than** half-heartedly; **having** cleaned a bathroom or cooked a simple meal themselves, **they are also far more likely to** appreciate the unpaid work that keeps a household running."], ["concession: family → transaction", "**Critics argue that** paying for chores **turns** family life **into** a commercial transaction."], ["rebuttal: basic duties unpaid · extra tasks paid", "**This risk can be avoided, however, if** parents **distinguish between** basic duties, such as tidying one's own room, **which** go unpaid, **and** additional tasks **that** earn a reward."], ["restate: effective for money sense + responsibility", "**In conclusion, I believe that** tying pocket money to chores **is an effective way to** teach both financial sense and responsibility."], ["effort → reward · never too early", "**The lesson that** effort brings reward **is one** children **can hardly learn too early**."]], "disagree": [["pocket money · parents debate", "**Few** household arrangements **cause as much debate among** parents **as** pocket money."], ["view: pay only for chores · value of work", "**One popular view holds that** children should receive money only in exchange for chores, **in the hope that** this will teach them the value of work."], ["stance: disagree · help freely + allowance teaches budgeting", "**I disagree, because** paying for chores **undermines the idea that** family members help one another freely, **and** money management **can be taught perfectly well through** a regular allowance."], ["shared duties → paid services", "**My main objection is that it turns** shared responsibilities **into** paid services."], ["washing up has a price · helping = optional", "**Once** washing up or taking out the rubbish **carries a price,** children **may start to regard** contributing to the household **as** optional, something to be done only when they want extra cash."], ["teenager saved enough · refuses to help", "**It is not hard to imagine** a teenager **who, having** saved enough for a new game, **simply** refuses to help until the next purchase comes into view."], ["belonging → negotiation", "**What should be** an expression of belonging **thus becomes** a tiresome negotiation over price."], ["money skills ≠ chores", "**Nor is** payment for chores **necessary for** teaching financial skills."], ["fixed allowance · snacks · bus fares · budget · save · consequences", "A fixed weekly allowance, **given on the understanding that** it must cover expenses such as snacks or bus fares, **forces** children **to** budget, save and live with the consequences of overspending; **these are precisely the skills that** financial literacy programmes aim to develop, **and none requires** putting a price on household help."], ["concession: some need incentive", "**Admittedly, some** children **do need** an incentive to help around the house."], ["rebuttal: praise · expectations · example → durable habits", "**Nevertheless,** praise, clear expectations and the example set by parents **tend to build far more** durable habits **than** a cash reward **ever could**."], ["restate: keep separate", "**In conclusion,** chores **and** pocket money **are best kept** separate, **each teaching** its own lesson."], ["help because family, not paid", "Children should help at home **because** they belong to a family, **not because** they are being paid to do so."]], "vocab": [["hand over", "交出；給予"], ["a low-risk introduction to", "低風險的入門"], ["foster a sense of responsibility", "培養責任感"], ["half-heartedly", "敷衍地；不盡心地"], ["a commercial transaction", "商業交易"], ["undermine", "破壞；削弱"], ["live with the consequences", "承擔後果"], ["durable habits", "持久的習慣"]]};

window.PET_ESSAY_ADV[14] = {"args": {"agree": [{"t": "Light and Convenient 輕便方便", "ts": ["E-books allow students to carry all their reading material on a single light device.", "電子書讓學生只要帶一台輕巧的裝置，就能攜帶所有閱讀資料。"], "ex": ["Instead of packing heavy textbooks every day, students can access every title they need wherever they are.", "學生不必每天塞滿沉重的課本，無論身在何處都能取得需要的書。"], "eg": ["A junior high student with eight subjects can replace a bag of heavy textbooks with one tablet weighing less than half a kilogram.", "一個有八個科目的國中生，可以用一台不到半公斤的平板取代一整袋沉重課本。"], "wu": ["Therefore, e-books reduce physical strain and make studying on the move much easier.", "因此，電子書能減輕身體負擔，讓學生隨時隨地讀書更容易。"]}, {"t": "Search, Highlight, Dictionary 搜尋、畫線、字典", "ts": ["E-books come with built-in tools that make studying faster and more efficient.", "電子書內建的工具能讓讀書更快速、更有效率。"], "ex": ["Students can search for key terms, look up words instantly and save their highlights and notes in one place.", "學生能搜尋關鍵字、即時查單字，並把畫線和筆記存在同一個地方。"], "eg": ["When revising for a history test, a student can search the whole textbook for a date in seconds instead of flipping through pages.", "複習歷史考試時，學生能在幾秒內搜尋整本課本的某個年代，不必一頁頁翻找。"], "wu": ["As a result, students spend less time searching and more time actually learning.", "因此，學生花在找資料的時間變少，真正用來學習的時間變多。"]}, {"t": "Cheaper and Up to Date 更便宜、內容更新", "ts": ["Digital textbooks are often cheaper than printed ones and can be updated instantly.", "電子課本通常比紙本便宜，而且能即時更新。"], "ex": ["Publishers do not need to print and deliver new copies, so corrections and new information reach students immediately.", "出版商不必重新印刷和配送，修正與新資訊能立刻送到學生手上。"], "eg": ["When a science textbook needs new data, students can download the revised edition overnight instead of buying a new book.", "當自然課本需要更新數據時，學生能在一夜之間下載新版，不必再買一本新書。"], "wu": ["Consequently, e-books save families money and reduce paper waste at the same time.", "因此，電子書既能為家庭省錢，也能同時減少紙張浪費。"]}, {"t": "Accessibility 無障礙閱讀", "ts": ["E-books can be adjusted to meet the needs of students with reading difficulties.", "電子書可以調整，以符合有閱讀困難學生的需求。"], "ex": ["Features such as larger fonts, background colours and read-aloud functions make texts easier to see and understand.", "放大字體、調整背景顏色與朗讀功能等設計，讓文字更容易看清楚和理解。"], "eg": ["A student with dyslexia can listen to a chapter while following the highlighted words on the screen.", "有閱讀障礙的學生可以一邊聽章節朗讀，一邊跟著螢幕上標示的文字閱讀。"], "wu": ["In short, e-books give every student a fairer chance to access the same material.", "簡言之，電子書讓每位學生都能更公平地接觸相同的教材。"]}], "disagree": [{"t": "Deeper Reading on Paper 紙本閱讀更深入", "ts": ["Students generally understand and remember more when they read on paper.", "一般而言，學生閱讀紙本時理解得更多、記得更牢。"], "ex": ["Physical pages help readers remember where information appears, which makes it easier to follow and recall a long argument.", "實體書頁幫助讀者記住資訊出現的位置，更容易理解並回想長篇論述。"], "eg": ["Several studies have found that readers score higher on comprehension tests after reading complex texts in print rather than on screens.", "多項研究發現，讀者閱讀紙本的複雜文章後，閱讀理解測驗的分數比用螢幕閱讀更高。"], "wu": ["Therefore, paper remains the better choice for the careful reading that exams require.", "因此，對於考試所需的仔細閱讀，紙本仍是較好的選擇。"]}, {"t": "No Distractions 沒有干擾", "ts": ["Printed books allow students to focus without the distractions of a digital device.", "紙本書讓學生能專心閱讀，不受數位裝置干擾。"], "ex": ["A tablet constantly offers messages, games and videos, and even disciplined students find these temptations hard to resist.", "平板不斷跳出訊息、遊戲和影片，即使自律的學生也很難抗拒這些誘惑。"], "eg": ["A student reading a chapter on a tablet may be interrupted by a group chat notification every few minutes.", "用平板讀課本的學生，可能每隔幾分鐘就被群組通知打斷。"], "wu": ["As a result, paper protects the concentration that real learning depends on.", "因此，紙本能保護真正學習所需的專注力。"]}, {"t": "Eyes and Sleep 眼睛與睡眠", "ts": ["Reading on screens for long periods can harm students' eyes and sleep.", "長時間看螢幕閱讀可能傷害學生的眼睛和睡眠。"], "ex": ["Bright screens cause eye strain, and the light they give off at night can make it harder to fall asleep.", "明亮的螢幕會造成眼睛疲勞，夜間發出的光線也會讓人更難入睡。"], "eg": ["A student who revises on a tablet until midnight may wake up with tired eyes and feel sleepy in class the next day.", "用平板複習到半夜的學生，隔天可能眼睛疲勞、上課昏昏欲睡。"], "wu": ["Thus, paper books are a healthier option for students who already spend many hours in front of screens.", "因此，對已經花很多時間盯著螢幕的學生來說，紙本書是更健康的選擇。"]}, {"t": "Reliable and Lasting 可靠又持久", "ts": ["Paper books work anywhere and do not depend on batteries, internet access or software.", "紙本書在任何地方都能使用，不依賴電池、網路或軟體。"], "ex": ["A printed book cannot crash, run out of power or disappear when a licence expires, and it can be lent or resold.", "紙本書不會當機、沒電，也不會因授權到期而消失，還能借人或轉賣。"], "eg": ["During a power cut or on a long trip without Wi-Fi, a student with a printed textbook can keep studying without interruption.", "停電或長途旅行沒有網路時，帶著紙本課本的學生仍能不受影響地繼續讀書。"], "wu": ["In other words, paper offers a reliability that digital files cannot always guarantee.", "換句話說，紙本提供了數位檔案無法每次都保證的可靠性。"]}]}, "agree": [["kilograms of textbooks · daily", "**Not so long ago,** the typical student **would carry** several kilograms of textbooks to and from school every day."], ["one tablet · whole year's reading · schools debating", "**Today,** an entire year's reading **can be stored on** a single tablet, **and many** schools **are debating whether** digital books should replace printed ones altogether."], ["stance: e-books better · practical + learning tools", "**Although** paper **retains** a certain charm, **I agree that** e-books are the better option for students, **as** they are far more practical and offer learning tools **that** printed pages **simply cannot**."], ["convenience", "**The most obvious benefit is** convenience."], ["no hauling · lighter than a hardback · updates in seconds", "**Instead of** hauling heavy textbooks between home, school and the library, students can access every title they need on a device **weighing less than** a single hardback, **and** updated editions can be downloaded in seconds **rather than** reprinted."], ["younger pupils · heavy bags · back pain", "**This matters more than it might seem: for** younger pupils **in particular,** overloaded school bags **have been linked to** back and shoulder pain."], ["practicality alone = strong case", "Practicality **alone, therefore, makes a strong case for** digital reading."], ["built-in tools", "**Even more significant are** the tools built into e-books."], ["look up · search · highlight · export notes · dyslexia · fonts · read-aloud", "**At the tap of a screen,** students can look up an unfamiliar word, search an entire textbook for a key term, highlight passages and export their notes for revision; **for** learners **with** dyslexia or poor eyesight, adjustable fonts and read-aloud functions **can make the difference between** struggling with a text **and** fully understanding it."], ["concession: screens distract", "**It is often claimed that** screens are too distracting for serious study, since a single notification can derail an entire revision session."], ["rebuttal: e-readers · focus mode · settings, not format", "**However,** dedicated e-readers and tablets in focus mode **block** notifications entirely, **so this problem is a matter of** settings **rather than of** the format itself."], ["restate: convenience + tools", "**In conclusion,** e-books offer students **greater** convenience **and more** powerful learning tools **than their** printed **counterparts**."], ["future = digital", "**The future of** the textbook, **it seems, is** digital."]], "disagree": [["enthusiasm for digital · print hard to replace", "**For all the enthusiasm surrounding** digital learning, the humble printed book **has proved remarkably difficult to** replace."], ["schools swapping textbooks for tablets · assumption", "**Many** schools **have nevertheless begun** swapping textbooks **for** tablets, **on the assumption that** e-books are better suited to a generation raised on screens."], ["stance: disagree · comprehension + no distraction", "**I disagree with this assumption, since** paper supports deeper comprehension **and** offers an environment **free from** the distractions that screens invite."], ["understand more on paper", "**The first reason is that** students tend to understand more when they read on paper."], ["turning pages · where information sits · mental map · recall", "**Turning** physical pages **gives** readers **a sense of** where information sits within a text, **which helps them** build a mental map of an argument and recall it later."], ["studies · comprehension tests · print better · screens = skim", "**Several studies comparing** the two formats **have found that** readers perform better on comprehension tests after reading long or complex texts in print, **whereas** on screens they tend to skim."], ["exams demand careful reading", "**For** the kind of careful reading **that** examinations demand, **then,** paper **holds a clear advantage**."], ["no distraction", "**A second advantage of** printed books **is that,** quite simply, they cannot distract."], ["no notifications · internet one tap away · resist messages · broken concentration", "A textbook **offers no** notifications, games or video links, **whereas** a tablet **places** the entire internet **only one tap away from** a difficult page of chemistry; even disciplined students **find it hard to** resist checking a message, and each interruption breaks the concentration that genuine learning requires."], ["concession: lighter · searchable", "**Admittedly,** e-books are lighter **and** easier to search, and they can be updated without reprinting."], ["rebuttal: comprehension matters more · timetable lightens bags", "**Yet these** conveniences **matter far less than** comprehension, **and** a well-planned timetable can reduce the weight of a school bag **without** sacrificing the quality of reading."], ["restate: paper = better for deep reading", "**In conclusion,** paper books **remain the better choice for** students **who** wish to read deeply and without distraction."], ["worth keeping · does one thing", "**Some** technologies **are worth keeping precisely because** they do only one thing, and do it well."]], "vocab": [["retain a certain charm", "保有某種魅力"], ["haul", "（費力地）拖、搬運"], ["make the difference between A and B", "決定是A還是B的關鍵"], ["counterpart", "對應的人或物"], ["prove remarkably difficult to", "結果非常難以……"], ["comprehension", "理解力"], ["skim", "略讀；瀏覽"], ["genuine learning", "真正的學習"]]};

window.PET_ESSAY_ADV[15] = {"args": {"agree": [{"t": "Large Classes, Little Attention 大班制、少關注", "ts": ["Cram schools offer the individual attention that large school classes cannot provide.", "補習班提供學校大班制無法給予的個別關注。"], "ex": ["With around thirty students and a full syllabus, school teachers rarely have time to deal with each student's weaknesses.", "一班約三十人又要趕進度，學校老師很少有時間處理每個學生的弱點。"], "eg": ["In a small cram-school class, a student who misunderstands a maths method can ask questions and get feedback immediately.", "在小班制的補習班裡，搞不懂數學解法的學生能立刻發問並得到回饋。"], "wu": ["Therefore, cram schools help prevent small gaps in understanding from becoming serious problems.", "因此，補習班能避免小小的理解落差演變成嚴重的問題。"]}, {"t": "Exam Skills 考試技巧", "ts": ["Cram schools teach the exam techniques that high-stakes tests reward.", "補習班教授高風險考試所看重的應試技巧。"], "ex": ["Major exams test speed, accuracy and familiarity with question types as well as knowledge, and these skills need focused practice.", "重要考試除了知識，也考速度、準確度和對題型的熟悉度，這些能力需要專門練習。"], "eg": ["Students preparing for the GSAT often practise with timed mock tests and past papers that school lessons have little time to cover.", "準備學測的學生常做限時模擬考和考古題，而這些是學校課堂很少有時間涵蓋的。"], "wu": ["As a result, students who attend cram schools often feel better prepared and more confident on exam day.", "因此，上補習班的學生在考試當天常覺得準備更充分、更有信心。"]}, {"t": "Catching Up and Getting Ahead 補救與超前", "ts": ["Cram schools allow both weaker and stronger students to learn at their own pace.", "補習班讓程度較弱和較強的學生都能按照自己的步調學習。"], "ex": ["School lessons are aimed at the average student, so those who are behind or ahead are often left without suitable support.", "學校課程以中等程度學生為目標，落後或超前的學生往往得不到適合的支援。"], "eg": ["A student who missed lessons due to illness can review the material in a cram school, while a gifted student can study more advanced topics.", "因病缺課的學生可以在補習班複習進度，資優生則能學習更進階的內容。"], "wu": ["Consequently, cram schools fill gaps that the regular school system leaves open.", "因此，補習班能填補一般學校體制留下的空缺。"]}, {"t": "Structure and Supervision 結構與監督", "ts": ["Cram schools give students a structured and supervised place to study after school.", "補習班為學生提供放學後有規劃、有人監督的讀書環境。"], "ex": ["Many parents work long hours and cannot check homework, so a fixed routine helps students stay disciplined.", "許多父母工時很長，無法檢查功課，而固定的作息能幫助學生維持自律。"], "eg": ["A teenager who would otherwise spend the evening alone at home on a phone can complete homework with a tutor nearby.", "原本可能整晚獨自在家滑手機的青少年，能在老師身旁完成功課。"], "wu": ["In short, cram schools provide the routine and supervision that busy families often cannot.", "簡言之，補習班提供了忙碌家庭常常無法給予的作息與監督。"]}], "disagree": [{"t": "Exhaustion 筋疲力盡", "ts": ["Attending cram school after a full school day leaves students physically and mentally exhausted.", "上完一整天的課再去補習，會讓學生身心俱疲。"], "ex": ["Long hours of study leave little time for sleep, exercise or rest, all of which young people need to stay healthy.", "長時間讀書讓學生幾乎沒有時間睡覺、運動或休息，而這些都是青少年維持健康所需的。"], "eg": ["A student who finishes cram school at ten o'clock and then does homework may not get to bed until after midnight.", "十點才下課、回家還要寫功課的學生，可能要過了午夜才能上床睡覺。"], "wu": ["Therefore, the extra study time often comes at a serious cost to students' wellbeing.", "因此，額外的讀書時間往往以學生的身心健康為沉重代價。"]}, {"t": "Dependence, Not Learning 依賴而非學習", "ts": ["Cram schools can make students depend on tutors instead of learning independently.", "補習班可能讓學生依賴老師，而不是學會自主學習。"], "ex": ["When students know that every lesson will be explained again in the evening, they have less reason to listen carefully at school.", "當學生知道每堂課晚上都會再講一次，他們在學校就比較沒有理由認真聽。"], "eg": ["Some students admit that they sleep or chat in class because their cram school teacher will cover the same material later.", "有些學生承認上課時睡覺或聊天，因為補習班老師之後會再教一樣的內容。"], "wu": ["As a result, students fail to develop the self-study skills they will need at university.", "因此，學生無法培養上大學後所需的自學能力。"]}, {"t": "Inequality 不平等", "ts": ["Cram schools give wealthier families an advantage that poorer families cannot afford.", "補習班讓富裕家庭擁有經濟較差的家庭負擔不起的優勢。"], "ex": ["Fees can cost thousands of dollars a month, so academic success starts to depend on family income rather than effort.", "補習費一個月可能要好幾千元，學業成就因此開始取決於家庭收入而非努力。"], "eg": ["A family with two children in several cram-school courses may spend a large share of its monthly income on fees.", "兩個孩子都上好幾門補習課的家庭，可能要把很大一部分月收入花在學費上。"], "wu": ["Thus, relying on cram schools widens the gap between rich and poor students.", "因此，依賴補習班會擴大貧富學生之間的差距。"]}, {"t": "Memorising, Not Thinking 背誦而非思考", "ts": ["Cram schools often focus on memorising tricks rather than developing real understanding.", "補習班常著重背誦解題技巧，而不是培養真正的理解。"], "ex": ["Because their reputation depends on exam results, they teach shortcuts that produce correct answers without explaining why they work.", "因為補習班的名聲取決於考試成績，它們教的是能得出正確答案的捷徑，卻不解釋背後的原理。"], "eg": ["A student may memorise a formula to solve a familiar maths problem but be unable to handle a question written in a new way.", "學生可能背了公式能解熟悉的數學題，卻無法應付換個方式出的題目。"], "wu": ["In other words, cram schools may raise test scores while weakening curiosity and critical thinking.", "換句話說，補習班可能提高了考試分數，卻削弱了好奇心與批判思考能力。"]}]}, "agree": [["evening classes after school · Taipei · familiar sight", "**So familiar is the sight of** teenagers heading to evening classes after a full school day **that** in cities such as Taipei it barely attracts comment."], ["critics: expensive burden · popularity = real need", "**Critics dismiss** these cram schools **as** an expensive burden, **but their popularity suggests that** they meet a genuine need."], ["stance: necessary · attention + exam prep", "**I agree that, under** the current education system, cram schools **are necessary for** most students, **as they provide** individual attention and targeted exam preparation **that** ordinary schools **struggle to offer**."], ["class size", "**The first point to consider is** class size."], ["30 students · crowded syllabus · no time for weaknesses", "**With** around thirty students in a typical classroom **and** a crowded syllabus to cover, **even the most** dedicated teacher **has little time to** identify and address each pupil's particular weaknesses."], ["small class · grammar / algebra · immediate feedback · gap widens", "**In** a small cram-school class, **by contrast,** a student **who** has misunderstood a grammar point or an algebra method can receive immediate feedback **before** the gap widens into a serious problem."], ["without support → fall behind", "**Without** this extra support, **many** students **would simply** fall behind."], ["exam specialists", "Cram schools **are also specialists in** examination technique."], ["GSAT · speed · accuracy · past papers · mock tests · broad curriculum", "**Because** entrance exams such as Taiwan's GSAT **reward not only** knowledge **but also** speed, accuracy and familiarity with question types, students benefit from past papers, timed mock tests and analysis of common errors; **this is precisely the kind of** focused training **that** regular schools, which must cover a broad curriculum, **rarely have time to provide**."], ["concession: exhaustion", "**It is true that** long hours of extra study **can leave** students exhausted."], ["rebuttal: exams decide places · opting out = disadvantage · moderate timetable", "**However, as long as** exams continue to determine university places, opting out of cram school **puts** students **at a clear disadvantage, which is why** a moderate, carefully chosen timetable is the sensible compromise."], ["restate: large classes + competitive exams → necessary", "**In conclusion, given** the realities of large classes and competitive exams, cram schools **remain necessary for** most students."], ["lifeline, not luxury", "**Until** the system itself changes, **they are less a** luxury **than a** lifeline."]], "disagree": [["10 p.m. · leaving second classroom", "**By** ten o'clock on a weeknight, **many** teenagers in East Asia **are only just** leaving their second classroom of the day."], ["belief: essential for success", "**Such** long hours **reflect a widespread belief,** shared by parents and students alike, **that** cram schools are essential for academic success."], ["stance: disagree · exhaustion + dependence on tricks", "**I disagree with this belief, since** cram schools frequently exhaust students **and** encourage dependence on memorised techniques **instead of** genuine understanding."], ["wellbeing", "**The most immediate cost is to** students' wellbeing."], ["8 hours + 3 hours · no sleep · exercise · free thinking", "**After** eight hours of lessons, **a further** three hours of drilling **leaves little time for** sleep, exercise or the unstructured thinking **through which** young people develop interests of their own."], ["surveys · stress · sleep deprivation", "**It is hardly surprising that** surveys of teenagers in highly competitive education systems **regularly report** high levels of stress and chronic sleep deprivation."], ["health vs marginal gains", "**A system that** sacrifices health **for** marginal gains in test scores **is difficult to defend, however** competitive university admission may be."], ["type of learning", "**Equally troubling is** the kind of learning that cram schools promote."], ["results-driven · shortcuts · formulae · not paying attention at school · reliant on tutors", "**Because** their reputation depends on results, **many focus on** shortcuts and formulae that produce correct answers **without requiring** students to understand why they work; **knowing that** every lesson will be re-taught in the evening, some students even stop paying attention at school, **becoming reliant on** tutors **rather than on** their own reasoning."], ["concession: struggling students need help", "**Admittedly,** a struggling student, or one who has missed lessons through illness, **may benefit from some** extra help."], ["rebuttal: school tutorials · online courses · study groups", "**Nonetheless, this** support **can be provided far more cheaply through** school tutorials, free online courses or peer study groups, **none of which** demands every evening of the week."], ["restate: neither necessary nor beneficial", "**In conclusion,** cram schools **are neither** necessary **nor, in many cases,** beneficial for the students who attend them."], ["not more hours · better, independent learning", "**What** students **need most is not** more hours **but** better, more independent learning."]], "vocab": [["attract comment", "引起議論"], ["meet a genuine need", "滿足真正的需求"], ["fall behind", "落後"], ["put sb at a disadvantage", "使某人處於劣勢"], ["a lifeline", "救命索；不可或缺的支援"], ["chronic sleep deprivation", "長期睡眠不足"], ["marginal gains", "些微的進步"], ["become reliant on", "變得依賴……"]]};

window.PET_ESSAY_ADV[16] = {"args": {"agree": [{"t": "Immersive Experience 沉浸式體驗", "ts": ["Watching a film in a theater offers an immersive experience that no living room can match.", "在電影院看電影能提供客廳無法比擬的沉浸式體驗。"], "ex": ["A giant screen, surround sound and a completely dark room pull viewers into the story and shut out the outside world.", "巨大的銀幕、環繞音效與全暗的空間把觀眾拉進故事，隔絕外界的一切。"], "eg": ["Films such as Dune were shot for IMAX, so the desert storms seem to roar around the audience.", "像《沙丘》這類為 IMAX 拍攝的電影，沙漠風暴彷彿就在觀眾身邊呼嘯。"], "wu": ["Therefore, for visually spectacular films, the cinema remains the way the director intended them to be seen.", "因此，對於視覺震撼的電影而言，電影院仍是導演心目中理想的觀看方式。"]}, {"t": "Full Concentration 全神貫注", "ts": ["A theater allows audiences to give a film their full attention.", "電影院讓觀眾能全神貫注地看電影。"], "ex": ["Phones are switched off, there is no pause button and no household chores calling, so viewers follow every detail of the plot.", "手機關機、沒有暫停鍵、也沒有家事打擾，觀眾能跟上劇情的每個細節。"], "eg": ["Many people who watch a complex thriller at home check their phones a dozen times and miss the key clue.", "許多人在家看燒腦驚悚片時查看手機十幾次，結果錯過了關鍵線索。"], "wu": ["As a result, a film watched in a theater is usually understood and remembered better.", "因此，在電影院看的電影通常理解得更透徹、記得更久。"]}, {"t": "A Shared Social Event 共同的社交活動", "ts": ["Going to the cinema is a social event rather than just a way to watch a film.", "去電影院是一場社交活動，而不只是看一部電影。"], "ex": ["Laughing, gasping and clapping together with a crowd makes every emotion stronger, and a night out with friends creates lasting memories.", "和一群觀眾一起大笑、驚呼、鼓掌會放大每一種情緒，和朋友出門看電影也能留下長久的回憶。"], "eg": ["On the opening night of a superhero film, fans often cheer when their favourite hero appears on screen.", "超級英雄電影首映夜，當最愛的英雄出場時，影迷常常一起歡呼。"], "wu": ["For this reason, the theater turns a film into a shared memory that a sofa cannot recreate.", "因此，電影院把電影變成沙發無法重現的共同回憶。"]}, {"t": "Supporting the Film Industry 支持電影產業", "ts": ["Buying cinema tickets directly supports filmmakers and local cinemas.", "買電影票能直接支持電影創作者與在地戲院。"], "ex": ["Box-office income decides which films get sequels and whether smaller productions can be made, and it keeps cinema staff employed.", "票房收入決定哪些電影能拍續集、小成本電影能否開拍，也讓戲院員工保住工作。"], "eg": ["Several Taiwanese films became hits thanks to strong ticket sales, which encouraged investors to fund more local productions.", "幾部台灣電影因票房亮眼而大受歡迎，鼓勵投資人資助更多本土製作。"], "wu": ["In other words, every ticket is a vote for the kind of films audiences want to see.", "換句話說，每一張電影票都是為觀眾想看的電影投下的一票。"]}], "disagree": [{"t": "Convenience and Flexibility 方便與彈性", "ts": ["Streaming allows people to watch films whenever and wherever they like.", "串流讓人隨時隨地都能看電影。"], "ex": ["Viewers can pause, rewind or finish a film tomorrow, with no travel and no fixed showtimes.", "觀眾可以暫停、倒帶，或明天再看完，不必出門、也不用配合固定場次。"], "eg": ["A busy student can watch half a film after homework and the rest on the MRT the next morning.", "忙碌的學生可以寫完作業後看半部，隔天早上在捷運上看完。"], "wu": ["Consequently, streaming fits modern busy lifestyles far better than fixed showtimes.", "因此，串流比固定場次更符合現代人忙碌的生活。"]}, {"t": "Lower Cost 花費較低", "ts": ["Streaming is much cheaper than going to the cinema.", "串流比去電影院便宜得多。"], "ex": ["One monthly subscription costs about the same as a single ticket, yet it offers thousands of films and series for the whole family.", "一個月的訂閱費約等於一張電影票，卻提供全家數千部電影與影集。"], "eg": ["A family of four may spend over NT$1,500 on tickets and popcorn for one night out, whereas a streaming plan costs less than NT$400 a month.", "四口之家看一場電影加爆米花可能花超過 1,500 元，而串流方案每月不到 400 元。"], "wu": ["Therefore, for families and students on a budget, streaming offers far better value.", "因此，對預算有限的家庭和學生來說，串流划算得多。"]}, {"t": "Comfort and Privacy 舒適與隱私", "ts": ["Watching at home is more comfortable and private.", "在家看電影更舒適、更有隱私。"], "ex": ["Viewers can relax on their own sofa, eat their own food and avoid noisy audiences, kicking seats or phones lighting up in the dark.", "觀眾可以窩在自家沙發、吃自己的食物，避開吵鬧的觀眾、踢椅背的人和黑暗中亮起的手機。"], "eg": ["Many people cannot enjoy a film when someone nearby keeps talking or checking messages.", "旁邊有人一直講話或看訊息時，很多人就無法好好享受電影。"], "wu": ["As a result, home viewing often feels more relaxing than a crowded theater.", "因此，在家看電影往往比擁擠的戲院更放鬆。"]}, {"t": "A Huge Choice 選擇多元", "ts": ["Streaming platforms offer a much wider range of content than cinemas.", "串流平台提供的內容比電影院多元得多。"], "ex": ["Besides new releases, they include classic films, documentaries, foreign dramas and independent works that cinemas rarely show.", "除了新片，還有經典電影、紀錄片、外國影集和電影院很少放映的獨立作品。"], "eg": ["Viewers in Taiwan can watch Korean dramas, Spanish thrillers and Japanese anime on one platform, all with Chinese subtitles.", "台灣觀眾可以在同一個平台看韓劇、西班牙驚悚片和日本動畫，而且都有中文字幕。"], "wu": ["Thus, streaming broadens viewers' tastes and cultural horizons.", "因此，串流拓展了觀眾的品味與文化視野。"]}]}, "agree": [["undivided attention · two hours · cinema asks", "**Few** experiences in modern life demand our undivided attention for two uninterrupted hours, **yet that is exactly what** a cinema asks of its audience."], ["streaming releases within weeks · worth the expense?", "**With** streaming platforms now releasing major films within weeks of their premiere, **many people question whether** a trip to the cinema is still worth the time and expense."], ["stance: theatre · immersion + shared occasion", "**While** streaming **undoubtedly** offers convenience, **I much prefer** watching films in a theatre, **as it provides** an immersive experience and a sense of shared occasion **that** home viewing **cannot replicate**."], ["quality of attention", "**The first advantage lies in** the quality of attention a cinema creates."], ["dark auditorium · vast screen · no notifications · no pause", "**In** a darkened auditorium, **with** a vast screen and carefully engineered sound, **there are no** notifications, household interruptions or pause button to fragment the experience, **so** viewers absorb the story as its director intended."], ["Dune · Oppenheimer · lose power on a TV", "Films **conceived for** the big screen, **such as** Dune or Oppenheimer, **lose much of their power when** reduced to a television, **let alone** a phone."], ["home = half-attentive · messages · snacks", "Watching at home, **by contrast, often becomes** a half-attentive activity, interrupted every few minutes by messages and trips to the kitchen."], ["communal dimension", "**Equally important is** the communal dimension of cinema-going."], ["laugh & gasp with strangers · event · opening nights sell out", "Laughing, gasping and falling silent alongside hundreds of strangers **intensifies** every emotional response, and an evening at the cinema is an event in a way that pressing 'play' on a sofa rarely is; **it is no coincidence that** the opening nights of popular films still sell out **despite** the availability of streaming."], ["concession: tickets expensive", "**Admittedly,** cinema tickets **are considerably more** expensive **than** a monthly subscription."], ["rebuttal: occasional visit · weekday discounts", "**However,** an occasional visit **costs relatively little given** the experience it provides, and discounted weekday screenings **make it more affordable than many assume**."], ["restate: cinema = best way", "**In conclusion, although** streaming **is undeniably** practical for casual viewing, **I firmly believe that** the cinema remains the best way to experience a film."], ["experienced, not consumed", "A great film **deserves to be** experienced, **not merely** consumed."]], "disagree": [["viewing habits changed in a decade", "The way audiences watch films **has changed more in** the past decade **than in** the previous half-century."], ["vast libraries · modest fee · weeks after release", "Streaming services **now offer** vast libraries **for** a modest monthly fee, **and** new releases **frequently** arrive online within weeks of their cinema debut."], ["stance: streaming · flexible + affordable + own terms", "**Although** cinemas **retain** a certain glamour, **I prefer** watching films at home, **as** streaming is far more flexible and affordable and allows viewers to enjoy films on their own terms."], ["flexibility and cost", "**The most obvious advantage is** flexibility, closely followed by cost."], ["no fixed times · pause/resume · students & parents", "**Instead of** arranging an evening around fixed screening times and travel, viewers **can** start, pause or resume a film whenever it suits them, **which matters considerably to** students and working parents with unpredictable schedules."], ["family of four · NT$1,500 · subscription a fraction", "**Financially, the difference is striking:** a family of four may spend well over NT$1,500 on tickets and snacks for a single outing, **whereas** a streaming subscription typically costs a fraction of that for an entire month."], ["→ greater value for households", "**For most** households, **therefore,** streaming **offers far greater** value."], ["control over what & how", "Streaming **also gives** viewers **far greater control over** what they watch and how they watch it."], ["classics · documentaries · foreign films · no noise · subtitles", "Platforms **offer not only** new releases **but also** classic films, documentaries and foreign-language productions that local cinemas rarely screen, and at home there are no conversations in the row behind or phone screens glowing in the dark; **for** viewers **who** need subtitles, audio description or simply a quiet environment, **this** control **is invaluable**."], ["concession: cinema screen & sound unrivalled", "**It is true that** a cinema's screen and sound system **remain unrivalled**."], ["rebuttal: large TVs · soundbars · film night", "**Nevertheless,** affordable large televisions and soundbars **have narrowed the gap considerably,** and inviting friends over for a film night **can recreate** much of the social atmosphere."], ["restate: streaming more practical", "**In conclusion, while** cinemas **will continue to** appeal on special occasions, streaming **has become the more** practical and enjoyable **way for most people to** watch films."], ["best seat = one's own", "**The best** seat in the house **is increasingly** one's own."]], "vocab": [["undivided attention", "全神貫注"], ["immersive", "沉浸式的"], ["auditorium", "觀眾席、放映廳"], ["fragment", "使支離破碎"], ["communal", "共同的"], ["on one's own terms", "依自己的方式"], ["unrivalled", "無與倫比的"], ["narrow the gap", "縮小差距"]]};

window.PET_ESSAY_ADV[17] = {"args": {"agree": [{"t": "Knowledge Is Free and Instant 知識免費又即時", "ts": ["AI has made specialised knowledge free and instantly available.", "人工智慧讓專業知識變得免費又能即時取得。"], "ex": ["Students can ask an AI tutor to explain calculus, law or coding at any hour, so a university is no longer the only gateway to expert knowledge.", "學生隨時都能請 AI 家教解釋微積分、法律或程式設計，大學不再是取得專業知識的唯一管道。"], "eg": ["A teenager can learn to build a website with AI help in a few weeks without paying a single tuition fee.", "一個青少年在 AI 的協助下，幾週內就能學會架設網站，完全不用付學費。"], "wu": ["Therefore, the monopoly on knowledge that once gave degrees their value is disappearing.", "因此，曾經賦予學歷價值的知識壟斷正在消失。"]}, {"t": "Skills Go Out of Date Quickly 技能快速過時", "ts": ["Degrees cannot keep up with the speed at which AI is changing jobs.", "學位跟不上人工智慧改變工作的速度。"], "ex": ["A four-year programme may teach skills that are automated before students even graduate.", "四年的課程所教的技能，可能在學生畢業前就已被自動化取代。"], "eg": ["Many translation and graphic-design graduates now compete with AI tools that complete basic tasks in seconds.", "許多翻譯和平面設計系的畢業生，如今得和幾秒內就能完成基本工作的 AI 工具競爭。"], "wu": ["Thus, a degree may certify skills the job market no longer needs.", "因此，學位證明的可能是就業市場已不再需要的技能。"]}, {"t": "Employers Value Skills over Certificates 雇主重視技能勝於文憑", "ts": ["Employers are increasingly hiring for proven skills rather than diplomas.", "雇主越來越看重實際技能，而非文憑。"], "ex": ["Portfolios, online certificates and real projects show what a candidate can actually do.", "作品集、線上證書和實際專案更能展現求職者的真正能力。"], "eg": ["Large companies such as Google and IBM have removed degree requirements for many positions.", "像 Google 和 IBM 這樣的大公司，已取消許多職位的學歷要求。"], "wu": ["As a result, a strong portfolio can open doors that a degree alone cannot.", "因此，一份出色的作品集能打開學歷本身打不開的門。"]}, {"t": "High Cost, Low Return 成本高、報酬低", "ts": ["The cost of a degree is becoming hard to justify.", "取得學位的成本越來越難以合理化。"], "ex": ["Tuition, rent and four years without income add up, while AI-powered courses cost little or nothing.", "學費、房租加上四年沒有收入，累積起來非常可觀，而 AI 輔助課程幾乎免費。"], "eg": ["In many countries, graduates spend a decade repaying student loans, yet start in jobs that do not require a degree.", "在許多國家，畢業生要花十年償還學貸，卻從事不需要學位的工作。"], "wu": ["Consequently, many young people now question whether university is worth it.", "因此，許多年輕人開始質疑上大學是否值得。"]}], "disagree": [{"t": "Critical Thinking and Judgement 批判思考與判斷力", "ts": ["University develops critical thinking that AI cannot replace.", "大學培養的批判思考能力是人工智慧無法取代的。"], "ex": ["Students learn to question evidence, compare theories and argue logically — exactly the skills needed to check whether an AI answer is correct.", "學生學會質疑證據、比較理論、有邏輯地論證，這正是判斷 AI 答案是否正確所需的能力。"], "eg": ["A history student trained to evaluate sources can spot when a chatbot invents a fake quotation.", "受過史料評估訓練的歷史系學生，能看出聊天機器人捏造的假引文。"], "wu": ["Therefore, in the age of AI, the ability to judge information becomes more valuable, not less.", "因此，在 AI 時代，判斷資訊的能力只會更有價值。"]}, {"t": "Professional Qualifications 專業資格", "ts": ["Many careers legally require a degree.", "許多職業在法律上要求具備學位。"], "ex": ["Society will not allow unqualified people to practise medicine, law, engineering or teaching, however good their AI tools are.", "無論 AI 工具多好，社會都不會允許不具資格的人從事醫療、法律、工程或教學工作。"], "eg": ["No patient would accept surgery from someone whose only training came from a chatbot.", "沒有病人會接受一個只靠聊天機器人受訓的人為自己動手術。"], "wu": ["Thus, for professions that affect lives and safety, degrees remain essential.", "因此，對於攸關生命與安全的職業，學位依然不可或缺。"]}, {"t": "Hands-on Learning and Research 實作學習與研究", "ts": ["Universities offer laboratories, equipment and research opportunities that a screen cannot provide.", "大學提供螢幕無法提供的實驗室、設備和研究機會。"], "ex": ["Students work with expert professors on real experiments, often creating the technology that AI itself is built on.", "學生與專業教授一起進行真實實驗，常常正是在創造 AI 賴以建立的技術。"], "eg": ["The researchers who develop AI models almost all hold advanced degrees.", "開發 AI 模型的研究人員幾乎都擁有高等學位。"], "wu": ["In other words, AI is a product of universities rather than a replacement for them.", "換句話說，人工智慧是大學的產物，而不是大學的替代品。"]}, {"t": "Networks and Soft Skills 人脈與軟實力", "ts": ["University builds networks and social skills that last a lifetime.", "大學建立的人脈與社交能力能受用一生。"], "ex": ["Group projects, clubs and internships teach teamwork, leadership and communication, and classmates often become future colleagues and partners.", "小組專題、社團和實習培養團隊合作、領導力和溝通能力，同學也常成為未來的同事與合作夥伴。"], "eg": ["Many successful start-ups were founded by university classmates who met in a lecture hall or a dormitory.", "許多成功的新創公司，是由在教室或宿舍相識的大學同學共同創立的。"], "wu": ["As a result, the relationships formed at university often matter as much as the knowledge.", "因此，在大學建立的人際關係往往和知識一樣重要。"]}]}, "agree": [["degree = passport to secure employment", "**For much of** the twentieth century, a university degree **served as** a reliable passport to secure, well-paid employment."], ["AI tutors · employers ask what you can do", "**That assumption is now being questioned, as** AI tutors can explain almost any subject on demand and employers increasingly ask what candidates can do **rather than** where they studied."], ["stance: agree · degrees eroding for most careers", "**Although** degrees **will not** vanish entirely, **I would argue that** AI is rapidly eroding their value for the majority of careers."], ["universities losing monopoly on knowledge", "**The first reason is that** universities are losing their monopoly on knowledge."], ["lectures & tuition → instant AI explanations · feedback", "Content **that once required** years of lectures and expensive tuition **is now available** instantly through AI systems that explain concepts, set exercises and provide personalised feedback at any hour."], ["motivated learner · programming · statistics · months", "**A motivated learner can** master the fundamentals of programming, statistics or graphic design **within** months, **often at negligible cost**."], ["→ certificate carries less weight", "**If** the knowledge a degree certifies can be acquired so cheaply elsewhere, the certificate itself **inevitably carries less weight**."], ["gap: curriculum vs labour market", "**Equally important is the growing gap between** what universities teach **and** what the labour market requires."], ["AI changes jobs faster than curricula · Google & IBM skills-based hiring", "**Because** AI is reshaping jobs faster than curricula can be revised, a four-year programme **risks** training students for tasks that will be automated before they graduate; **it is therefore unsurprising that** firms such as Google and IBM have dropped degree requirements for many roles **in favour of** skills-based hiring."], ["concession: medicine, law, engineering", "**Admittedly,** regulated professions **such as** medicine, law and engineering **will continue to demand** formal qualifications."], ["rebuttal: small share of jobs · AI changing them too", "**Yet** these fields **account for a relatively small share of** employment, **and even within them** AI is changing the knowledge that practitioners need."], ["restate: prerequisite → one option among many", "**In conclusion, while** degrees will retain some symbolic value, **I am convinced that** AI is turning them **from** a prerequisite for success **into** one option among many."], ["ability > credentials", "**In the future,** demonstrable ability **rather than** formal credentials **is likely to** open the most doors."]], "disagree": [["predictions of decline as old as university", "**Predictions of** the university's decline **are almost as old as** the university itself."], ["radio · TV · online courses · each time wrong", "Radio, television and online courses **were each expected to** make campus education obsolete, **and** AI is merely the latest technology to inspire such claims; each time, the prediction has proved wrong."], ["stance: disagree · skills more valuable", "**I strongly disagree that** it will render degrees useless; **if anything,** the skills that a good degree develops are becoming more valuable, not less."], ["purpose ≠ transmitting information", "**The central purpose of** higher education **has never been simply to** transmit information."], ["evaluate evidence · argue · uncertainty · use AI responsibly", "A rigorous degree **trains students to** evaluate evidence, construct arguments, communicate complex ideas clearly and tolerate uncertainty **— precisely the abilities required to** use AI responsibly."], ["fluent but fabricated answers · question sources", "Language models **can produce** fluent answers **that are nonetheless** inaccurate or entirely fabricated, **and only someone** trained to question sources **is likely to** notice when this happens."], ["→ critical judgement = growing asset", "**In an era of** abundant but unreliable information, the capacity for critical judgement **is therefore a growing asset rather than** a redundant one."], ["qualifications society will not waive", "**Moreover, many careers depend on** qualifications **that society is unwilling to** waive."], ["surgery · engineering · law · AI researchers hold degrees", "**However** sophisticated AI **becomes,** the public will not entrust surgery, structural engineering or legal representation to people who lack accredited training; **indeed,** the researchers who build AI systems almost invariably hold advanced degrees, and universities remain the laboratories in which such technology is developed."], ["concession: self-taught programmers", "**It is true that** some technology firms now recruit self-taught programmers."], ["rebuttal: exceptions · lifetime earnings · job security", "**Nevertheless, these remain exceptions rather than the rule,** and in most countries graduates continue to enjoy higher lifetime earnings and greater job security than non-graduates."], ["restate: AI changes teaching, not value", "**In conclusion,** AI **will undoubtedly** change what and how universities teach, **but it will not** make their degrees worthless."], ["answers vs questions", "A machine **can supply** answers; **only** education **teaches us** which questions are worth asking."]], "vocab": [["monopoly", "壟斷"], ["negligible", "微不足道的"], ["skills-based hiring", "以技能為本的招聘"], ["prerequisite", "先決條件"], ["obsolete", "過時的"], ["fabricated", "捏造的"], ["waive", "免除"], ["accredited", "經認證的"]]};

window.PET_ESSAY_ADV[18] = {"args": {"agree": [{"t": "Cheaper and Never Tired 更便宜、永不疲倦", "ts": ["AI can work faster and more cheaply than humans.", "人工智慧能比人類工作得更快、更便宜。"], "ex": ["It works twenty-four hours a day without breaks, salaries, sick leave or mistakes caused by tiredness.", "它能全天候工作，不需休息、薪水或病假，也不會因疲勞而犯錯。"], "eg": ["Many banks and telecom companies now use chatbots to answer thousands of customer questions at once.", "許多銀行和電信公司現在用聊天機器人同時回答數千個客戶問題。"], "wu": ["Therefore, companies have a strong financial reason to replace staff with AI.", "因此，企業有強烈的財務誘因用 AI 取代員工。"]}, {"t": "Routine Jobs Disappear 例行性工作消失", "ts": ["Jobs built on repetitive tasks are the easiest to automate.", "以重複性任務為主的工作最容易被自動化。"], "ex": ["Data entry, cashier work, basic accounting and simple translation follow clear rules that machines can learn.", "資料輸入、收銀、基礎會計和簡單翻譯都有明確規則，機器可以學會。"], "eg": ["Self-checkout machines in supermarkets and convenience stores have already reduced the number of cashiers needed.", "超市和便利商店的自助結帳機已經減少了所需的收銀員人數。"], "wu": ["Thus, millions of routine jobs are at real risk.", "因此，數以百萬計的例行性工作面臨真實的風險。"]}, {"t": "White-Collar Work Is Not Safe 白領工作也不安全", "ts": ["Even skilled office jobs are now threatened.", "就連需要技能的辦公室工作現在也受到威脅。"], "ex": ["AI can write reports, analyse contracts, draft code and design advertisements in seconds.", "AI 能在幾秒內撰寫報告、分析合約、編寫程式和設計廣告。"], "eg": ["Some law firms now use AI to review documents that junior lawyers once spent weeks reading.", "有些律師事務所現在用 AI 審閱過去菜鳥律師要花好幾週閱讀的文件。"], "wu": ["As a result, a university degree no longer guarantees a safe job.", "因此，大學學歷不再保證一份安穩的工作。"]}, {"t": "AI Improves Faster Than People Retrain AI 進步得比人轉職還快", "ts": ["AI is improving faster than workers can learn new skills.", "AI 進步的速度比勞工學習新技能還快。"], "ex": ["Each new model can do more, while retraining an adult worker takes years and money.", "每一代新模型都能做更多事，而重新訓練一位成年勞工需要數年時間和金錢。"], "eg": ["A middle-aged factory worker may lose a job to a robot long before finishing a programming course.", "一位中年工廠工人可能在上完程式課之前，就已經被機器人搶走工作。"], "wu": ["Consequently, many people may be left behind.", "因此，許多人可能會被拋在後頭。"]}], "disagree": [{"t": "New Jobs Are Created 創造新工作", "ts": ["Every major technology has created more jobs than it destroyed.", "每一次重大科技革新所創造的工作都比消滅的多。"], "ex": ["The Industrial Revolution, computers and the internet all ended some jobs but created whole new industries.", "工業革命、電腦和網路都讓某些工作消失，卻也創造了全新的產業。"], "eg": ["Twenty years ago, nobody worked as a social-media manager, app developer or AI trainer.", "二十年前，沒有人從事社群媒體經理、App 開發者或 AI 訓練師的工作。"], "wu": ["Therefore, AI is more likely to change jobs than to end them.", "因此，AI 較可能改變工作，而不是終結工作。"]}, {"t": "Human Skills Cannot Be Copied 人類能力無法複製", "ts": ["AI cannot replace human empathy, creativity and judgement.", "AI 無法取代人類的同理心、創造力與判斷力。"], "ex": ["Jobs that involve caring for people, leading teams or solving new problems depend on emotional understanding.", "照顧他人、領導團隊或解決新問題的工作都仰賴對情感的理解。"], "eg": ["A nurse comforting a frightened patient or a teacher encouraging a shy student does far more than give information.", "安撫受驚病人的護理師，或鼓勵害羞學生的老師，所做的遠不只是提供資訊。"], "wu": ["Thus, the most human jobs will remain in human hands.", "因此，最具人性的工作仍將由人類來做。"]}, {"t": "AI as a Tool, Not a Replacement AI 是工具而非替代品", "ts": ["In most workplaces, AI makes workers more productive rather than unnecessary.", "在多數職場中，AI 讓員工更有生產力，而不是變得多餘。"], "ex": ["It handles boring, repetitive tasks so that people can focus on the parts of their job that need thought.", "它處理無聊、重複的工作，讓人能專注於需要思考的部分。"], "eg": ["After ATMs appeared, banks did not stop hiring tellers; instead, tellers moved on to customer service and sales.", "提款機出現後，銀行並沒有停止僱用行員，行員反而轉向客服與銷售工作。"], "wu": ["As a result, AI is more of a partner than a competitor.", "因此，AI 與其說是競爭者，不如說是夥伴。"]}, {"t": "Trust and Responsibility 信任與責任", "ts": ["People still want a human to be responsible for important decisions.", "人們仍希望由人類為重要決定負責。"], "ex": ["When health, money or safety are involved, customers want someone they can question and hold accountable.", "當涉及健康、金錢或安全時，顧客希望有一個能詢問、能負責的人。"], "eg": ["Few passengers would board a plane with no pilot, even if the autopilot does most of the flying.", "即使自動駕駛負責大部分飛行，也很少有乘客願意搭沒有機師的飛機。"], "wu": ["Consequently, humans will remain in charge of the decisions that matter most.", "因此，人類仍將掌握最重要的決定。"]}]}, "agree": [["automation displaced labour · AI targets thinking", "Automation **has always** displaced some forms of labour, **but** artificial intelligence **differs from** earlier technologies **in one crucial respect:** it targets thinking rather than merely physical work."], ["contracts · diagnoses · code · how many jobs?", "**As** software **becomes** capable of drafting contracts, diagnosing illnesses and writing code, **the question is no longer whether** jobs will be affected, **but** how many."], ["stance: agree · scale never seen before", "**Although** AI **will undoubtedly** create some new occupations, **I would argue that** it is likely to replace human workers **on a scale that** no previous technology has approached."], ["economic incentive", "**The most compelling reason is** economic."], ["no salary · 24/7 · copied at no cost · incentive disappears", "An AI system **requires no** salary or holidays, works around the clock and can be copied at almost no cost, **so once** it can perform a task adequately, **the incentive to** employ a person **largely disappears**."], ["customer-service centres · chatbots · small team for complaints", "Customer-service centres **illustrate this clearly:** many banks now resolve most routine enquiries through chatbots, **retaining only** a small team for complaints the software cannot handle."], ["one supervisor = twenty workers", "**When** one employee supervising an algorithm can do the work of twenty, **the other** nineteen **are rarely** redeployed."], ["professionals as well as manual workers", "**Equally significant is the fact that** AI threatens educated professionals **as well as** manual labourers."], ["translation · legal research · programming · faster than retraining", "Tasks **once regarded as the preserve of** skilled staff, such as translation, legal research and basic programming, **can now** be completed in seconds, **and because** these systems improve faster than adults can retrain, mid-career workers may see years of expertise lose its value almost overnight."], ["concession: past technologies created jobs", "**Admittedly,** the Industrial Revolution and the computer **ultimately** created **more** jobs **than** they destroyed."], ["rebuttal: decades vs years · cognitive skills", "**Yet** those transitions **unfolded over** decades and left plenty of tasks that only humans could perform, **whereas** AI is advancing within years and encroaching on **the very** cognitive skills **that once** allowed displaced workers to move into new roles."], ["restate: substantial share replaced", "**In conclusion, while** work built on physical dexterity or personal care will survive, **I am convinced that** AI will replace a substantial proportion of today's workforce."], ["prepare, don't deny", "Governments **should therefore focus less on** denying this shift **and more on** preparing for it."]], "disagree": [["anxiety about jobs · AI", "**Few** technologies **have provoked as much** anxiety about employment **as** artificial intelligence."], ["headlines predict mass unemployment · since steam engine", "Headlines **regularly predict that** machines capable of writing, analysing and even diagnosing will leave millions without work, **yet such forecasts have accompanied** almost every major innovation since the steam engine."], ["stance: disagree · reshape not replace", "**In my view,** AI **will** transform a great many jobs, **but it is far more likely to** reshape human work **than to** replace it."], ["history: progress creates jobs", "**First, history suggests that** technological progress creates **at least as much** employment **as** it destroys."], ["lower costs · higher demand · new industries", "**By** lowering the cost of goods and services, automation **raises** demand **and frees** resources **for** entirely new industries, **many of which** could not have been imagined beforehand."], ["ATMs · more branches · tellers → advice", "**When** cash machines spread in the late twentieth century, **for example,** banks did not dismiss their tellers; **instead,** cheaper branches allowed them to open more, and tellers shifted towards advice and customer relationships."], ["→ AI likely to follow the pattern", "**There is little reason to assume that** AI will break this pattern."], ["jobs = bundles of tasks", "**Second,** most jobs **are bundles of** tasks, **and only some of** those tasks can be automated."], ["radiologist · scans vs judgement, empathy, accountability", "A radiologist's work, **for instance, involves not only** reading scans **but also** consulting colleagues, explaining results to anxious patients and taking responsibility for decisions; AI **can accelerate** the first of these, **but the rest depend on** judgement, empathy and accountability, qualities that people are unwilling to delegate to software."], ["concession: data entry may disappear", "**Admittedly, some roles built almost entirely on** routine processing, such as data entry, **may** disappear."], ["rebuttal: redeployment · retraining", "**Even so, the more realistic outcome is** redeployment **rather than** mass unemployment, **provided that** governments and employers invest seriously in retraining."], ["restate: tool that augments", "**In conclusion, while** the transition will be uncomfortable for certain workers, AI **is better understood as** a powerful tool that augments human ability **than as** a substitute for it."], ["tasks, not jobs", "Machines **may increasingly** take over tasks; **it is far less likely that** they will take over jobs."]], "vocab": [["displace", "取代、使失業"], ["incentive", "誘因"], ["redeploy", "重新調配"], ["the preserve of", "…的專屬領域"], ["encroach on", "侵入"], ["augment", "增強"], ["accountability", "問責、負責"], ["delegate", "委託"]]};

window.PET_ESSAY_ADV[19] = {"args": {"agree": [{"t": "Land Is Scarce 土地稀少", "ts": ["Building upwards is the only way to add large numbers of homes when city land is limited and expensive.", "當城市土地有限又昂貴時，往上蓋是唯一能大量增加住宅的方法。"], "ex": ["A tower can house hundreds of families on a plot that would hold only a few detached houses.", "一棟高樓能在原本只夠蓋幾棟獨棟房屋的土地上，容納數百戶家庭。"], "eg": ["Singapore houses around 80 per cent of its residents in high-rise public flats on an island of just over 700 square kilometres.", "新加坡約八成居民住在高樓層的公共組屋裡，而整座島只有七百多平方公里。"], "wu": ["Therefore, tall blocks make the most efficient use of the one resource cities cannot create: land.", "因此，高樓最能有效利用城市無法創造的資源——土地。"]}, {"t": "Protects Green Space 保護綠地", "ts": ["High-rise housing stops cities from spreading endlessly into farmland and countryside.", "高樓住宅能防止城市無止盡地擴張到農地和鄉間。"], "ex": ["When homes are stacked vertically, there is less pressure to build on fields, forests and wetlands at the edge of the city.", "住宅垂直堆疊時，在城市邊緣的田地、森林和濕地開發的壓力就會減少。"], "eg": ["Cities that sprawl outwards, such as many in the United States, have lost large areas of farmland to low-density suburbs.", "向外蔓延的城市，例如美國許多城市，已因低密度郊區而失去大片農地。"], "wu": ["As a result, building tall helps protect the natural environment around cities.", "因此，往高處蓋有助於保護城市周圍的自然環境。"]}, {"t": "Efficient Public Transport 大眾運輸更有效率", "ts": ["Dense high-rise neighbourhoods make public transport and services cheaper to provide.", "高密度的高樓社區讓大眾運輸和公共服務的成本更低。"], "ex": ["When thousands of people live near one station, trains and buses can run frequently and still cover their costs.", "當數千人住在同一個車站附近時，火車和公車就能高頻率行駛，又能回收成本。"], "eg": ["In Hong Kong, most residents live within walking distance of an MTR station, so relatively few households need a car.", "在香港，多數居民住在走路就能到港鐵站的範圍內，因此需要汽車的家庭相對較少。"], "wu": ["Consequently, tall blocks reduce traffic, pollution and the cost of long commutes.", "因此，高樓能減少交通壅塞、污染和長途通勤的成本。"]}, {"t": "Cheaper Infrastructure 基礎建設更省錢", "ts": ["Compact housing reduces the cost of roads, water pipes and power lines per household.", "集中式住宅能降低每戶分攤的道路、水管和電線成本。"], "ex": ["Spreading the same number of homes across a wide area means building and maintaining many more kilometres of infrastructure.", "把同樣數量的住宅分散在廣大區域，就必須興建並維護多出許多公里的基礎設施。"], "eg": ["A single apartment tower can share one water connection, one road entrance and one waste collection point among hundreds of flats.", "一棟公寓大樓的數百戶可以共用一個供水接口、一個道路出入口和一個垃圾收集點。"], "wu": ["In short, building tall saves public money that can be spent on schools and hospitals instead.", "總之，往高處蓋能省下公帑，轉而用在學校和醫院上。"]}], "disagree": [{"t": "Towers Are Expensive 高樓造價昂貴", "ts": ["Very tall buildings cost more per flat to build and maintain than medium-rise housing.", "超高建築每戶的興建和維護成本比中層住宅更高。"], "ex": ["They need deep foundations, more steel, fast lifts and complex fire-safety systems, and residents pay high management fees.", "它們需要很深的地基、更多鋼材、高速電梯和複雜的消防系統，住戶還要付高額管理費。"], "eg": ["Luxury towers in cities such as London and New York are often bought as investments, while ordinary families remain priced out.", "倫敦和紐約等城市的豪華高樓常被當作投資品購買，一般家庭則仍買不起。"], "wu": ["Therefore, more height does not automatically mean more affordable homes.", "因此，蓋得更高並不代表就有更多負擔得起的住宅。"]}, {"t": "Mid-Rise Density Works 中層高密度也可行", "ts": ["Medium-rise blocks of five to eight storeys can house almost as many people as towers.", "五到八層樓的中層建築幾乎能容納和高樓一樣多的人。"], "ex": ["Because they cover more of each plot and need less empty space around them, their density is surprisingly high.", "因為它們占用基地的比例較高，周圍需要的空地較少，所以密度出奇地高。"], "eg": ["Central Paris, built mainly with six- or seven-storey buildings, is one of the most densely populated areas in Europe.", "以六、七層樓建築為主的巴黎市中心，是歐洲人口最稠密的地區之一。"], "wu": ["As a result, cities can add many homes without building skyscrapers.", "因此，城市不必蓋摩天大樓也能增加大量住宅。"]}, {"t": "Reuse Empty Buildings 活用閒置建築", "ts": ["Converting empty offices, shops and old factories into flats adds homes quickly.", "把閒置的辦公室、店面和舊工廠改建成公寓，能快速增加住宅。"], "ex": ["These buildings already have roads, water and electricity, so conversion is often faster and greener than building from scratch.", "這些建築已有道路、水電，因此改建往往比從零興建更快、更環保。"], "eg": ["Since more people began working from home, many cities have started turning unused office buildings into apartments.", "自從更多人開始在家工作，許多城市已著手把閒置辦公大樓改建成公寓。"], "wu": ["Consequently, the existing stock of buildings can be part of the solution.", "因此，現有的建築本身就可以是解決方案的一部分。"]}, {"t": "Better Transport Links 改善交通連結", "ts": ["Fast rail links to satellite towns let people live affordably outside the city centre.", "通往衛星城鎮的快速鐵路，讓人們能在市中心以外以合理的價格居住。"], "ex": ["If the journey to work is quick and reliable, cheaper land outside the city becomes a realistic place to live.", "如果通勤又快又可靠，城市外較便宜的土地就成為可行的居住選擇。"], "eg": ["Tokyo's extensive commuter rail network allows millions of people to live in surrounding towns and still reach central offices.", "東京綿密的通勤鐵路網，讓數百萬人能住在周邊城鎮，仍可抵達市中心的辦公室。"], "wu": ["In short, good transport spreads housing demand instead of concentrating it in towers.", "總之，良好的交通能分散住宅需求，而不是把需求集中在高樓上。"]}]}, "elements": [["Hook", "開頭：引起注意"], ["Background", "背景：議題現況"], ["Thesis", "主旨句：立場＋兩個理由"], ["Body 1 — Topic sentence", "主題句：理由一"], ["Explanation", "說明"], ["Example / evidence", "舉例／證據"], ["Mini-conclusion", "小結：結果"], ["Body 2 — Topic sentence", "主題句：理由二"], ["Explanation + example", "說明＋舉例"], ["Counterargument — Concession", "反方意見：讓步"], ["Rebuttal", "反駁"], ["Conclusion — Restate", "結論：重申立場"], ["Closing thought", "結語"]], "agree": [["housing shortage · persistent challenge", "**Few** problems **confront** governments of major cities **as persistently as** the shortage of affordable homes."], ["growing population · finite land · out or up", "**With** urban populations **continuing to** grow while usable land remains finite, planners **are forced to choose between** spreading outwards **and** building upwards."], ["stance: largely agree · land · services", "**Although** high-rise development **is not without** drawbacks, **I largely agree that** tall apartment blocks offer the best solution, **both because** they make efficient use of scarce land **and because** they sustain the services city life depends on."], ["land", "**The most persuasive argument concerns** land."], ["plots scarce · protect farmland · stack vertically", "In a crowded city, every additional plot is prohibitively expensive or unavailable, **so the only way to** add homes **without** swallowing up farmland and green belts **is to** stack them vertically."], ["Singapore · 80% high-rise flats · 700 km²", "Singapore **offers a striking illustration: by** housing roughly 80 per cent of its residents in high-rise public flats, the city-state **has managed to** accommodate almost six million people on an island of just over 700 square kilometres."], ["low-rise → run out of space", "**Had** it relied on low-rise housing **instead, it would have** run out of space decades ago."], ["density → viable public services", "**Equally important is the fact that** concentrating residents makes public services far more viable."], ["walking distance · trains, clinics, schools · suburbs → cars, long pipes", "**When** thousands of households live within walking distance of a single station, **it becomes economically feasible to** run frequent trains and staff local clinics and schools; low-density suburbs, **by contrast, tend to** leave residents dependent on private cars, **adding to** congestion, emissions and the cost of laying roads and pipes over ever greater distances."], ["concession: post-war estates · isolation, crime", "**Admittedly,** some tower blocks, **such as** certain post-war estates in Britain, **became associated with** isolation and crime."], ["rebuttal: neglect, not height · well-run estates", "**Yet these failures stemmed from** neglect and poor design **rather than from** height itself, **as** well-maintained estates with shared gardens and shops in Singapore and Seoul **demonstrate**."], ["restate: building upwards most realistic", "**In conclusion, while** other measures have a supporting role to play, **I firmly believe that** building upwards remains the most realistic way to house growing cities."], ["build tall well", "**The real question is not whether** cities should build tall, **but how** they can do so well."]], "disagree": [["housing crisis headlines · tower as answer", "**Whenever** housing shortages **make headlines,** the gleaming apartment tower **is often presented as** the obvious answer."], ["scarce land · simplest way", "**Since** land in major cities is scarce, building upwards **appears to be** the simplest way to squeeze more homes into the same space."], ["stance: disagree · cost · better alternatives", "**However, I would argue that** high-rise towers **are far from** the best solution, **since** they are costly to build and maintain, **and** other approaches can deliver more affordable homes more quickly."], ["economics of tall buildings", "**To begin with, the economics of** tall buildings **are less** favourable **than they first appear.**"], ["foundations · steel · lifts · fire safety", "**Beyond a certain** height, construction **requires** deeper foundations, more steel, high-speed lifts and sophisticated fire-safety systems, **all of which** push up the price of each flat."], ["London, New York luxury towers · investors · families priced out", "**This is partly why** luxury towers in cities such as London and New York **often end up as** investment assets for wealthy buyers, **while** ordinary families remain priced out."], ["height ≠ affordability", "**In other words,** greater height **does not necessarily mean** more affordable homes."], ["less dramatic, more effective measures", "**More importantly,** cities **can** expand their housing supply **through** less dramatic **but** more effective measures."], ["mid-rise density · office conversions · Tokyo rail", "Blocks of five to eight storeys **can achieve** densities **comparable to** those of towers **while** remaining far cheaper to build, and converting empty offices **adds** homes **without** consuming new land; fast rail links to satellite towns, **as in** Tokyo's vast commuter belt, **allow** workers to live affordably beyond the centre."], ["concession: Hong Kong · height unavoidable", "**Admittedly, in exceptionally** crowded places **such as** Hong Kong, building upwards **may be unavoidable.**"], ["rebuttal: towers + public housing, limits on speculation", "**Even there, however,** towers **alone cannot** solve the problem **unless they are combined with** public housing and limits on speculative buying that keep homes within reach of ordinary workers."], ["restate: towers have a place, not the best way", "**In conclusion, although** tall apartment blocks **have their place, I do not believe** they are the best way to provide enough homes in large cities."], ["broader strategy: density, reuse, transport", "**What** cities **need most is not** taller buildings **but** a broader strategy combining sensible density, smarter use of existing buildings and better transport."]], "vocab": [["prohibitively expensive", "貴得令人卻步"], ["green belt", "綠帶（城市周圍的保護綠地）"], ["economically feasible", "經濟上可行的"], ["low-density suburbs", "低密度郊區"], ["stem from", "源自；起因於"], ["priced out", "因價格過高而被排除在外"], ["satellite town", "衛星城鎮"], ["speculative buying", "投機性購買（炒房）"]]};

window.PET_ESSAY_ADV[20] = {"args": {"agree": [{"t": "Jobs Across a Whole Industry 支撐整個產業的就業", "ts": ["Theatres and cinemas support far more jobs than the people who sell tickets and popcorn.", "劇院和電影院支撐的工作遠多於賣票和賣爆米花的人。"], "ex": ["Every production needs actors, set designers, lighting and sound technicians, costume makers, marketers and front-of-house staff.", "每一場演出都需要演員、布景設計師、燈光音響技師、服裝師、行銷人員和前台人員。"], "eg": ["A single West End or Broadway musical can employ hundreds of people, many of whom trained for years in specialised crafts.", "一部倫敦西區或百老匯音樂劇就能雇用數百人，其中許多人在專業技藝上受訓多年。"], "wu": ["Therefore, losing these venues would mean losing skilled jobs that streaming platforms cannot easily replace.", "因此，失去這些場館就意味著失去串流平台難以取代的專業工作。"]}, {"t": "Keeping City Centres Alive 讓市中心保持活力", "ts": ["Theatres and cinemas bring people into city centres, especially in the evenings.", "劇院和電影院把人潮帶進市中心，尤其是在晚上。"], "ex": ["Audiences rarely just watch a show; they also eat in nearby restaurants, visit cafés, use public transport and shop.", "觀眾很少只是看一場表演；他們也會在附近餐廳用餐、去咖啡店、搭乘大眾運輸和購物。"], "eg": ["Areas such as Ximending in Taipei or London's West End owe much of their lively night-time economy to their cinemas and theatres.", "台北西門町或倫敦西區等地區熱鬧的夜間經濟，很大程度要歸功於當地的電影院和劇院。"], "wu": ["As a result, when a cinema closes, surrounding businesses often suffer as well.", "因此，當一家電影院關門時，周邊商家往往也跟著受害。"]}, {"t": "A Shared Cultural Experience 共享的文化體驗", "ts": ["Watching a play or film with an audience is a social and cultural event, not just entertainment.", "和觀眾一起看戲或看電影是一種社交與文化活動，而不只是娛樂。"], "ex": ["Laughing, gasping and reacting together creates a sense of community that watching alone on a phone cannot provide.", "一起大笑、驚呼和反應能創造出獨自用手機觀看無法提供的群體感。"], "eg": ["Opening nights, film festivals and school trips to the theatre bring together people of different ages and backgrounds.", "首映之夜、電影節和學校的劇院校外教學，能把不同年齡和背景的人聚在一起。"], "wu": ["In short, these venues help to build shared memories and a common culture.", "總之，這些場館有助於建立共同的回憶和共同的文化。"]}, {"t": "Protecting Live Art and New Talent 保護現場藝術與新秀", "ts": ["Theatres keep live performance alive and give new artists a place to develop.", "劇院讓現場表演得以延續，也給新藝術家成長的空間。"], "ex": ["Many famous actors, directors and writers began their careers in small local theatres before working in film or television.", "許多知名演員、導演和編劇在進入影視圈之前，都是從地方小劇場開始職業生涯的。"], "eg": ["Traditional art forms, such as Taiwanese opera or puppet theatre, depend on live stages to survive and attract new audiences.", "歌仔戲或布袋戲等傳統藝術，仰賴現場舞台才能存續並吸引新觀眾。"], "wu": ["Thus, without theatres, much of a country's cultural heritage could slowly disappear.", "因此，沒有劇院，一個國家的許多文化遺產可能會慢慢消失。"]}], "disagree": [{"t": "Cheaper and More Convenient 更便宜也更方便", "ts": ["Online entertainment is far cheaper and more convenient than going out.", "線上娛樂比出門看表演便宜得多，也方便得多。"], "ex": ["A monthly subscription often costs about the same as one cinema ticket, and there is no need to travel, park or book seats.", "一個月的訂閱費往往和一張電影票差不多，而且不必交通、停車或訂位。"], "eg": ["A family of four can watch a new film at home for a fraction of what tickets, snacks and transport would cost.", "一家四口在家看一部新片，花費只是電影票、零食和交通費的一小部分。"], "wu": ["Therefore, for many ordinary households, online viewing is simply the more sensible choice.", "因此，對許多一般家庭來說，線上觀看就是比較合理的選擇。"]}, {"t": "Endless Choice 選擇無窮", "ts": ["Streaming platforms offer a range of content that no single venue could ever match.", "串流平台提供的內容種類，是任何單一場館都無法比擬的。"], "ex": ["Viewers can choose from thousands of films, series and documentaries from around the world, whenever they like.", "觀眾隨時都能從世界各地數以千計的電影、影集和紀錄片中挑選。"], "eg": ["Korean dramas, Spanish thrillers and Japanese anime have found huge global audiences largely through online platforms.", "韓劇、西班牙驚悚片和日本動畫主要透過線上平台吸引了大量全球觀眾。"], "wu": ["As a result, people no longer need cinemas to discover new and varied stories.", "因此，人們不再需要電影院才能發掘新穎多元的故事。"]}, {"t": "Culture for Everyone 人人都能接觸文化", "ts": ["Online platforms make culture accessible to people who could rarely visit theatres.", "線上平台讓很少有機會去劇院的人也能接觸文化。"], "ex": ["People in rural areas, those with disabilities or tight budgets, and busy parents can now enjoy performances at home.", "鄉村居民、身心障礙者、預算有限的人和忙碌的父母，現在都能在家欣賞表演。"], "eg": ["Britain's National Theatre streams filmed productions, allowing audiences far from London to see acclaimed plays cheaply.", "英國國家劇院在網路上播放演出錄影，讓遠離倫敦的觀眾也能便宜地欣賞好評如潮的戲劇。"], "wu": ["In other words, the internet has spread culture more widely rather than destroyed it.", "換句話說，網路讓文化傳播得更廣，而不是摧毀了文化。"]}, {"t": "The Economy Is Shifting Online 經濟正轉向線上", "ts": ["The entertainment economy is not disappearing; it is moving online.", "娛樂經濟並沒有消失，而是轉移到線上。"], "ex": ["Streaming companies invest billions in new productions, creating jobs for writers, actors, editors and technicians.", "串流公司投資數十億製作新節目，為編劇、演員、剪接師和技術人員創造工作機會。"], "eg": ["Many recent award-winning films and series were funded and released by streaming services rather than traditional studios.", "許多近年得獎的電影和影集都是由串流服務出資和發行，而非傳統片廠。"], "wu": ["Thus, the economic argument for physical venues is weaker than it first appears.", "因此，支持實體場館的經濟論點其實比表面上薄弱。"]}]}, "elements": [["Hook", "開頭：引起注意"], ["Background", "背景：議題現況"], ["Thesis (both views + my opinion)", "主旨句：兩方觀點＋我的立場"], ["View 1 — Topic sentence", "觀點一：主題句"], ["Explanation", "說明"], ["Example / evidence", "舉例／證據"], ["Evaluation", "評價"], ["View 2 — Topic sentence", "觀點二：主題句"], ["Explanation + example", "說明＋舉例"], ["My opinion — Reason", "我的看法：理由"], ["Support", "支持論證"], ["Conclusion — Restate", "結論：重申立場"], ["Closing thought", "結語"]], "agree": [["streaming · how stories are consumed · rapid change", "**Rarely has** a single technology **transformed** the way people consume stories **as rapidly as** streaming."], ["films, series, stage shows online · do venues still matter?", "**With** thousands of films, series and even recorded stage productions **available at the touch of a button,** some **question whether** physical venues still serve any real purpose."], ["both views · stance: indispensable · economy + culture", "**Although the case for** online entertainment **is persuasive, I would argue that** theatres and cinemas **remain** indispensable, **both as** engines of local economies **and as** spaces for shared cultural life."], ["view 1: obsolete · convenience", "**Those who consider** these venues obsolete **point to** the sheer convenience of streaming."], ["price of one ticket · limitless library · any device · no travel", "**For the price of** a single cinema ticket, a monthly subscription **offers** an almost limitless library **that can be** watched at any hour, on any device and without the expense of travelling."], ["films released directly online · cinemas closed after pandemic", "**The scale of this shift is evident in the fact that** major studios now release some films directly online, **while** many smaller cinemas closed permanently after the pandemic."], ["evaluation: valid for individuals", "**From a purely** individual **perspective, then,** this argument **carries considerable weight**."], ["view 2: economic role", "**Supporters of** theatres and cinemas, **however, emphasise** their far wider economic role."], ["footfall · restaurants, bars, shops · technicians, actors · West End tourism", "A busy venue **sustains far more than** its own staff, drawing visitors into city centres where they spend money in restaurants, bars and shops, and employing technicians, actors and designers; London's West End, **for instance,** attracts millions of theatregoers every year and is a cornerstone of the city's tourist economy."], ["my opinion: culture most convincing", "**Persuasive as** this economic case **is, what convinces me most is** the cultural value of experiencing a performance collectively."], ["live play · no pause · unrepeatable · debate afterwards", "A live play **cannot be** paused or replayed, **and it is precisely** this shared, unrepeatable moment, together with the discussion it provokes afterwards, **that** keeps theatre a living art form **rather than** an archive of recordings."], ["restate: still important · economically + culturally", "**In conclusion, while** streaming **has undoubtedly** made entertainment more accessible, **I firmly believe that** theatres and cinemas remain important **both** economically **and** culturally."], ["not redundant · reason to gather", "**Far from being** made redundant by home screens, they **offer what** no algorithm can supply: a reason for people to gather."]], "disagree": [["vast range of entertainment · arm's reach", "**Never before have** audiences **had** such a vast range of entertainment within arm's reach."], ["new films online within weeks · debate pressing", "**Now that** most new films reach streaming platforms within weeks of their release, **the debate over whether** theatres and cinemas still matter **has become** increasingly pressing."], ["both views · stance: far less important · choice, cost, access", "**While** these venues **retain** some economic and cultural value, **I believe that** they are becoming far less important to most people, **given** the choice, affordability and accessibility of online alternatives."], ["view 1: economy · culture", "**Advocates of** theatres and cinemas **argue that** they underpin both local economies and cultural life."], ["footfall · restaurants & shops · communal experience", "**Not only do** they bring footfall to city centres, benefiting nearby restaurants and shops, **but they also** offer a communal experience that many regard as central to a city's identity."], ["Broadway · billions · tourists", "Broadway, **for example, is estimated to** contribute billions of dollars to New York's economy each year, **much of it** spent by visitors from abroad."], ["evaluation: valid in major cities", "**In major cities at least,** this argument **is difficult to dismiss**."], ["view 2: venues largely unnecessary", "**Others, however, contend that** the internet **has made** such venues largely unnecessary for ordinary audiences."], ["subscription = one ticket · thousands of titles · National Theatre streams plays", "A streaming subscription **costs roughly the same as** one cinema ticket **yet provides** access to thousands of titles, and even live theatre has moved online; the National Theatre's filmed productions, **for instance, have allowed** audiences far from London to watch acclaimed plays at a fraction of the price."], ["my opinion: access > atmosphere", "**I am inclined to agree with** this second view, **chiefly because** access matters more than atmosphere for most people."], ["rural areas · tight budgets · democratised culture", "**For those living** in rural areas or on tight budgets, regular theatre trips were never realistic, **so** online platforms **have in effect** democratised culture **rather than** diminished it."], ["restate: still contribute · but far less important", "**In conclusion, although** theatres and cinemas **still** contribute to urban economies and cultural life, **I maintain that** they are becoming far less important as online entertainment meets most people's needs."], ["occasional treats · not essential", "They **will probably endure, but as** occasional treats **rather than** essential institutions."]], "vocab": [["indispensable", "不可或缺的"], ["obsolete", "過時的；被淘汰的"], ["footfall", "人流量；來客數"], ["a cornerstone of", "……的基石"], ["underpin", "支撐；鞏固"], ["unrepeatable", "無法重來的；獨一無二的"], ["democratise culture", "讓文化普及大眾"], ["at a fraction of the price", "以極低的價格"]]};

window.PET_ESSAY_ADV[21] = {"args": {"agree": [{"t": "Theory Becomes Real Skill 理論化為實用技能", "ts": ["A work placement allows students to apply classroom theory to genuine problems in a professional setting.", "企業實習讓學生在職場環境中把課堂理論應用在真實問題上。"], "ex": ["They learn to meet deadlines, work in teams and communicate with clients, skills that lectures alone rarely develop.", "他們學會趕上期限、團隊合作與客戶溝通，這些都是光靠上課很難培養的能力。"], "eg": ["Engineering students on placement, for example, often help to test real products rather than only solving textbook exercises.", "例如，實習中的工程系學生常參與測試真實產品，而不只是解課本習題。"], "wu": ["Therefore, graduates enter the workforce with practical competence as well as academic knowledge.", "因此，畢業生進入職場時不只有學術知識，也具備實務能力。"]}, {"t": "Better Job Prospects 更好的就業前景", "ts": ["Students with placement or overseas experience tend to find skilled employment more quickly after graduation.", "有實習或海外經驗的學生畢業後往往更快找到專業工作。"], "ex": ["Employers value proof that a candidate can already function in a workplace, so such experience strengthens any CV.", "雇主重視應徵者已能在職場上運作的證明，因此這類經驗能讓履歷更有說服力。"], "eg": ["Many companies hire their former interns directly, saving themselves the cost and risk of recruiting strangers.", "許多公司直接錄用以前的實習生，省下招募陌生人的成本與風險。"], "wu": ["As a result, a compulsory placement could narrow the gap between graduation and stable employment.", "因此，必修實習能縮短畢業到穩定就業之間的落差。"]}, {"t": "Independence and Maturity 獨立與成熟", "ts": ["Living abroad or working full-time forces young people to become far more independent and self-reliant.", "在海外生活或全職工作會迫使年輕人變得更獨立、更能自立。"], "ex": ["They must manage money, solve everyday problems and adapt to unfamiliar rules without relying on parents or teachers.", "他們必須自己管理金錢、解決日常問題，並適應陌生的規則，無法依賴父母或老師。"], "eg": ["Exchange students often have to open bank accounts, rent rooms and deal with officials in a foreign language.", "交換學生常常必須用外語開銀行帳戶、租房子並和公務人員打交道。"], "wu": ["Consequently, they return with greater confidence and a clearer sense of what they want from their careers.", "因此，他們回來時更有自信，也更清楚自己想要的職涯方向。"]}, {"t": "Global and Intercultural Skills 國際視野與跨文化能力", "ts": ["A period of study abroad develops language ability and intercultural awareness that employers increasingly demand.", "海外研修能培養雇主越來越重視的語言能力與跨文化意識。"], "ex": ["Daily contact with people from other cultures teaches students to question assumptions and communicate across differences.", "每天與不同文化的人接觸，讓學生學會質疑既有觀念，並跨越差異溝通。"], "eg": ["Europe's Erasmus+ programme has sent millions of students to study in other countries since it began in 1987.", "歐洲的 Erasmus+ 計畫自 1987 年開辦以來，已送出數百萬名學生到他國求學。"], "wu": ["Thus, graduates are better prepared for international companies and a globalised job market.", "因此，畢業生更能勝任跨國企業的工作，也更能面對全球化的就業市場。"]}], "disagree": [{"t": "Heavy Financial Burden 沉重的經濟負擔", "ts": ["Studying abroad is extremely expensive once tuition, flights, rent and living costs are added together.", "把學費、機票、房租和生活費加起來，出國研修的費用極為昂貴。"], "ex": ["Many placements are also unpaid or poorly paid, yet students still have to cover their daily expenses.", "許多實習也沒有薪水或薪水很低，但學生仍必須自付日常開銷。"], "eg": ["A semester in a city such as London or Tokyo can easily cost more than a whole year of study at home.", "在倫敦或東京這類城市待一學期，花費很容易超過在國內讀一整年。"], "wu": ["Therefore, a compulsory requirement could push many students and their families into debt.", "因此，強制規定可能讓許多學生和家庭負債。"]}, {"t": "Widening Inequality 加劇不平等", "ts": ["A universal requirement would hit students from low-income families much harder than wealthier students.", "全面強制的規定對低收入家庭學生的衝擊會遠大於富裕學生。"], "ex": ["Richer students can afford the best overseas programmes, while others may be forced into whatever cheap option remains.", "有錢的學生負擔得起最好的海外課程，其他人卻可能被迫接受剩下的便宜選項。"], "eg": ["Students who work part-time or care for relatives may be unable to leave home for several months.", "需要打工或照顧家人的學生，可能根本無法離家好幾個月。"], "wu": ["As a result, a policy meant to help everyone could actually deepen existing social divisions.", "因此，原本要幫助所有人的政策，反而可能加深既有的社會分歧。"]}, {"t": "Poor-Quality Placements 實習品質不佳", "ts": ["There may not be enough high-quality placements for every undergraduate in every subject.", "不見得每個科系的每位大學生都能分配到高品質的實習。"], "ex": ["When demand suddenly rises, some employers may treat students as cheap labour rather than as learners.", "需求突然暴增時，有些雇主可能把學生當成廉價勞力，而不是學習者。"], "eg": ["Interns in some industries complain that they spend months making coffee and photocopying instead of learning real skills.", "某些產業的實習生抱怨，他們花了好幾個月泡咖啡、影印，而不是學習真正的技能。"], "wu": ["Thus, a compulsory scheme could waste students' time without delivering the promised benefits.", "因此，強制制度可能浪費學生的時間，卻帶不來承諾的好處。"]}, {"t": "Not Suitable for Every Subject 不適合所有科系", "ts": ["Not every academic discipline benefits equally from a period abroad or in a workplace.", "並非每個學科都能從海外研修或職場實習中同等受益。"], "ex": ["Subjects such as pure mathematics or philosophy have few obvious placements, and some courses already include extensive practical training.", "純數學或哲學等學科幾乎沒有明顯的實習場所，而有些科系本來就已包含大量實務訓練。"], "eg": ["Medical and teacher-training students, for instance, already spend long periods in hospitals and schools as part of their degrees.", "例如，醫學系和師資培育的學生本來就要在醫院和學校待很長的時間。"], "wu": ["In other words, a single rule for all courses ignores the real differences between them.", "換句話說，所有科系一體適用的規定忽略了科系之間的真實差異。"]}]}, "elements": [["Hook", "開頭：引起注意"], ["Background", "背景：議題現況"], ["Thesis (which outweighs)", "主旨句：利或弊何者較大"], ["Advantages — Topic sentence", "優點：主題句"], ["Explanation", "說明"], ["Example / evidence", "舉例／證據"], ["Mini-conclusion", "小結"], ["Disadvantages — Topic sentence", "缺點：主題句"], ["Explanation + example", "說明＋舉例"], ["Weighing up — Concession", "權衡：讓步"], ["Rebuttal", "反駁"], ["Conclusion — Restate", "結論：重申立場"], ["Closing thought", "結語"]], "agree": [["gap · lecture halls vs first day at work", "**There is often a wide gap between** what students learn in lecture halls **and what** employers **actually expect** on their first day at work."], ["proposal · compulsory abroad / placement", "**For this reason, some argue that** every undergraduate programme **should include** a period of study abroad or a work placement **as** a compulsory element."], ["stance: advantages outweigh · employability + growth", "**Although such a requirement would** bring certain costs, **I believe that its advantages, both for** students' employability **and for** their personal development, **clearly outweigh** its drawbacks."], ["theory → usable skills", "**The most significant benefit is that** practical experience turns theoretical knowledge into usable skills."], ["deadlines · colleagues · real problems · few seminars", "**During** a placement, students **are required to** meet deadlines, collaborate with colleagues of different ages and apply classroom concepts to real problems, **which few** seminars **can replicate**."], ["UK sandwich degrees · year in industry · jobs sooner", "British sandwich degrees, **for instance,** build a full year in industry into the course, **and** their graduates **are widely reported to** secure skilled jobs **more quickly than** their peers."], ["abroad or placement → independence · direction", "**Whether** students **choose** a placement **or** a semester abroad, **they return with** greater independence, sharper communication skills and a clearer sense of direction."], ["disadvantages · genuine difficulties", "**On the other hand,** making such experience compulsory **would create** genuine difficulties."], ["cost · low-income · uneven placements · unpaid photocopying", "Studying abroad **can be prohibitively** expensive for students from low-income families, **and** placements are unevenly distributed, **so** those in rural areas or less commercial disciplines may struggle to find meaningful positions; **in the worst cases,** students **may end up in** unpaid roles that amount to little more than photocopying."], ["concession: could widen inequality", "**It is true that** these obstacles **could** widen existing inequalities **if left unaddressed**."], ["rebuttal: practical not principle · grants · local partners · online", "**However,** they **are** practical problems **rather than** objections in principle, **and they can be overcome through** means-tested grants, partnerships with local employers and online international projects."], ["restate: funding needed · benefits far outweigh", "**In conclusion, although** such a scheme **would require** careful funding and organisation, **the benefits for** students' skills, confidence and employability **far outweigh** the drawbacks."], ["essential bridge · university → working life", "**Rather than** a costly luxury, **it should be seen as** an essential bridge **between** university **and** working life."]], "disagree": [["semester abroad · year in industry · transformative", "**Few would deny that** a semester abroad or a year in industry **can be** a transformative experience for an undergraduate."], ["imposed on all · subject · finances · circumstances", "**The question, however, is whether** such an experience **should be** imposed on every student, **regardless of** their subject, finances or circumstances."], ["stance: disadvantages outweigh · more problems than solves", "**While** the benefits **are** real, **I would argue that** making it a universal requirement **would create more** problems **than it** solves."], ["advantage · employability", "**To be fair, the case in favour rests on** a strong argument**:** practical experience makes graduates more employable."], ["workplace → theory, professionalism · abroad → independence, language", "Students **who** spend time in a workplace **learn to** apply theory, communicate professionally and meet real deadlines, **while those who** study abroad **gain** independence and fluency in another language."], ["optional placement years · Erasmus+ · millions", "**This is why** many business and engineering courses **already** offer optional placement years, **and** the Erasmus+ programme **has enabled** millions of European students **to** study in another country."], ["those who choose · substantial rewards", "**For** students **who choose** these opportunities, **the rewards can be** substantial."], ["problem = compulsory for all", "**The problems arise, however, when** such experience **becomes** compulsory for all."], ["cost on poorer students · unpaid city placement · not enough good positions", "**First,** the cost **would fall most heavily on** students from poorer backgrounds, **who may not be able to afford** months abroad or an unpaid placement in an expensive city; **second,** universities **would struggle to** find worthwhile positions for every student, **so** many would end up in roles offering little genuine learning."], ["concession: grants · partnerships", "**It could be argued that** grants and university partnerships **might** solve these difficulties."], ["rebuttal: diverts money · lengthens courses · more debt", "**Yet** such funding **would** divert money from teaching, **and** lengthening already demanding courses, such as architecture, **would add** time and debt **for** students **who** gain little from the extra requirement."], ["restate: universal requirement → disadvantages outweigh", "**In conclusion, although** time abroad or in the workplace **can be** highly beneficial, **I believe that** the disadvantages of a universal requirement **outweigh** the advantages."], ["better: well-funded option · student choice", "**A better approach would be to** offer such opportunities **as** a well-funded option, **so that** students can choose what genuinely suits their goals."]], "vocab": [["prohibitively expensive", "貴到令人卻步"], ["means-tested grants", "依經濟狀況核發的補助金"], ["employability", "就業能力"], ["unevenly distributed", "分配不均"], ["transformative experience", "改變人生的經歷"], ["a universal requirement", "一體適用的規定"], ["divert money from", "把資金從…挪走"], ["sandwich degree", "含一年產業實習的學位課程"]]};

window.PET_ESSAY_ADV[22] = {"args": {"agree": [{"t": "Children Learn by Doing 孩子從做中學", "ts": ["Young children understand new ideas best through hands-on activities rather than long periods of listening and copying.", "幼童透過動手操作最能理解新概念，而不是長時間聽講和抄寫。"], "ex": ["When they build, measure, sort or act things out, abstract concepts become concrete experiences that they can remember.", "當他們動手建造、測量、分類或演出時，抽象概念就變成能記住的具體經驗。"], "eg": ["A child who weighs fruit while playing shopkeeper grasps addition and units far faster than one who only fills in worksheets.", "玩扮演店員遊戲、一邊秤水果的孩子，比只寫學習單的孩子更快理解加法和單位。"], "wu": ["Therefore, play is not a break from learning but one of its most effective forms.", "因此，遊戲不是學習的中斷，而是最有效的學習方式之一。"]}, {"t": "Play Builds Social Skills 遊戲培養社交能力", "ts": ["Play teaches children to cooperate, negotiate and manage their emotions, skills that formal lessons rarely develop.", "遊戲教會孩子合作、協商和管理情緒，而這些能力是正式課程很少培養的。"], "ex": ["In a game, children must agree on rules, take turns and cope with losing, all without an adult directing them.", "在遊戲中，孩子必須協調規則、輪流進行並面對輸的感覺，而且沒有大人在旁指揮。"], "eg": ["Group role-play, such as running a pretend restaurant, requires pupils to share roles and resolve disagreements by themselves.", "像經營假想餐廳這樣的分組角色扮演，需要學生自己分配角色並解決意見分歧。"], "wu": ["As a result, children who play regularly are better prepared for teamwork at school and later at work.", "因此，經常遊戲的孩子更能適應在學校以及日後職場中的團隊合作。"]}, {"t": "Motivation and a Love of Learning 學習動機與熱忱", "ts": ["Too much formal learning at an early age can make children see school as a chore.", "太早接受過多正式學習，可能讓孩子把上學視為苦差事。"], "ex": ["Endless tests and drills create pressure and anxiety, which often replace natural curiosity with a fear of making mistakes.", "沒完沒了的考試和練習會造成壓力和焦慮，常常讓天生的好奇心被害怕犯錯取代。"], "eg": ["In Taiwan, many primary pupils go from a full school day straight to an evening cram school, leaving little time to explore their own interests.", "在台灣，許多國小學生上完整天課後直接去補習班，幾乎沒有時間探索自己的興趣。"], "wu": ["Consequently, children may lose their enthusiasm for learning long before they reach secondary school.", "因此，孩子可能在上國中之前，就早已失去學習的熱忱。"]}, {"t": "Health and Wellbeing 身心健康", "ts": ["Active play protects children's physical and mental health, which matters as much as their academic progress.", "活動性的遊戲能保護孩子的身體和心理健康，這和學業進步同樣重要。"], "ex": ["Sitting at desks and screens for most of the day reduces exercise, harms eyesight and increases stress.", "一天大部分時間坐在書桌和螢幕前，會減少運動量、傷害視力並增加壓力。"], "eg": ["Taiwan's health authorities encourage children to spend about two hours outdoors every day, partly to reduce the high rate of short-sightedness.", "台灣的衛生單位鼓勵孩子每天到戶外活動約兩小時，部分原因是為了降低高近視率。"], "wu": ["In short, play time is an investment in children's health, not a waste of lesson time.", "總之，遊戲時間是對孩子健康的投資，而不是浪費上課時間。"]}], "disagree": [{"t": "Foundations Must Come Early 基礎必須趁早打好", "ts": ["Literacy and numeracy are the foundations of all later learning, so they must be taught early and thoroughly.", "讀寫和算術是日後所有學習的基礎，所以必須及早並徹底地教導。"], "ex": ["These skills build step by step, and a child who misses one stage finds every following stage harder.", "這些能力是一步步累積的，錯過其中一個階段的孩子，會發現之後每個階段都更困難。"], "eg": ["A pupil who has not mastered multiplication by the age of nine usually struggles with fractions, percentages and later algebra.", "九歲還沒掌握乘法的學生，通常在分數、百分比以及日後的代數上都會吃力。"], "wu": ["Therefore, a strong focus on formal learning in primary school is necessary rather than excessive.", "因此，國小重視正式學習是必要的，而不是過度的。"]}, {"t": "Fairness for Disadvantaged Pupils 對弱勢學生的公平", "ts": ["Structured teaching matters most for children from disadvantaged homes, who have fewer chances to learn outside school.", "結構化的教學對來自弱勢家庭的孩子最為重要，因為他們在校外學習的機會較少。"], "ex": ["Children with educated, well-off parents learn a great deal at home, while others rely almost entirely on school.", "父母受過教育且經濟寬裕的孩子在家能學到很多，其他孩子則幾乎完全仰賴學校。"], "eg": ["If lessons were largely replaced by free play, pupils from homes without books would be the ones leaving school unable to read well.", "如果課程大多被自由遊戲取代，那些家裡沒有書的學生就會是畢業時還讀不好的人。"], "wu": ["As a result, reducing formal learning could widen the gap between rich and poor children.", "因此，減少正式學習可能會擴大貧富孩子之間的差距。"]}, {"t": "Successful Systems Are Structured 成功的教育體系重視結構", "ts": ["Many of the world's highest-performing school systems teach basic skills in a clear and systematic way.", "世界上許多表現最好的教育體系，都以清楚且有系統的方式教導基本能力。"], "ex": ["Carefully sequenced lessons make sure that every child masters one step before moving on to the next.", "經過仔細安排順序的課程，確保每個孩子先掌握一個步驟再進入下一步。"], "eg": ["Singapore, whose primary schools teach mathematics in a highly structured way, regularly ranks at or near the top of international assessments.", "新加坡的小學以高度結構化的方式教數學，在國際評量中經常名列前茅。"], "wu": ["Consequently, formal learning should be seen as a strength of primary education, not a weakness.", "因此，正式學習應被視為小學教育的優勢，而不是弱點。"]}, {"t": "Structured Play Works Better 有結構的遊戲效果更好", "ts": ["Play is useful in the classroom only when it has a clear learning purpose.", "遊戲只有在具有明確學習目的時，才在課堂中有用。"], "ex": ["Unguided free play can be enjoyable, but it does not reliably teach reading, writing or arithmetic.", "沒有引導的自由遊戲雖然好玩，但不能可靠地教會閱讀、寫作或算術。"], "eg": ["A phonics card game or a classroom shop with price tags can make practice enjoyable while still targeting specific skills.", "自然發音卡牌遊戲或貼有價格標籤的教室商店，能讓練習變有趣，同時仍針對特定能力。"], "wu": ["In other words, play should support formal learning rather than replace it.", "換句話說，遊戲應該輔助正式學習，而不是取代它。"]}]}, "elements": [["Hook", "開頭：引起注意"], ["Background", "背景：議題現況"], ["Thesis (answer to Q1 + Q2)", "主旨句：回答問題一＋問題二"], ["Q1 — Topic sentence", "問題一：主題句"], ["Explanation", "說明"], ["Example / evidence", "舉例／證據"], ["Mini-conclusion", "小結"], ["Q2 — Topic sentence", "問題二：主題句"], ["Explanation + example", "說明＋舉例"], ["Counterargument — Concession", "反方意見：讓步"], ["Rebuttal", "反駁"], ["Conclusion — Restate both answers", "結論：重申兩題答案"], ["Closing thought", "結語"]], "agree": [["many primary classrooms · rows of desks · worksheets · tests", "**Walk into** many primary classrooms **and you are likely to find** rows of seven-year-olds copying sentences, completing worksheets and preparing for their next test."], ["anxious parents · academic training starts earlier", "**As** parents **grow increasingly anxious about** their children's prospects, schools **have come under pressure to** begin academic training ever earlier."], ["stance: agree · play = effective form of learning", "**I largely agree that** primary schools place too much emphasis on formal learning, **and I would argue that** play **is not** a distraction from learning **but** one of its most effective forms."], ["ignores how children learn", "**The central problem is that** an overly academic approach **ignores how** young children actually learn."], ["hands-on · conversation · imitation · rote memorisation", "Children of this age **develop understanding chiefly through** hands-on experience, conversation and imitation, **whereas** long periods of seated instruction **tend to produce** rote memorisation **rather than** genuine comprehension."], ["Finland · school at seven · outdoor breaks · literacy", "Finland, **where** formal schooling **does not begin until** the age of seven and lessons are regularly broken up by outdoor play, **has long been admired for** its high standards of literacy."], ["less instruction ≠ lower achievement", "**This suggests that** less formal instruction **need not mean** lower achievement."], ["Q2: play develops skills textbooks cannot", "**Just as importantly,** play **develops skills that** no textbook **can teach**."], ["negotiate · solve problems · frustration · Taiwan cram schools", "**When** children build a model or invent the rules of a game, **they learn to** negotiate, solve problems and manage frustration; **in Taiwan, by contrast,** many pupils **move straight from** a full school day **to** an evening at a cram school, **leaving them with** little time for the unstructured play through which these abilities develop."], ["concession: basics must be mastered early", "**Admittedly,** reading, writing and arithmetic **must be mastered early, since** almost all later learning depends on them."], ["rebuttal: playful methods · counting games · role-play", "**Yet** these skills **can be taught just as effectively through** playful methods, **such as** counting games, shop role-plays and storytelling, **which** keep children motivated **instead of** making them dread school."], ["restate: too formal · play deserves a central place", "**In conclusion, I firmly believe that** primary schools focus excessively on formal learning, **and that** play **deserves a central place in** every primary classroom."], ["enjoys learning at eight → eighteen", "**A child who** enjoys learning at eight **is far more likely to** keep learning at eighteen."]], "disagree": [["reading fluently · calculating accurately · life chances", "**Few** abilities **shape** a person's life chances **as profoundly as** the capacity to read fluently and calculate accurately."], ["fashionable claim · too much instruction · too little play", "**Nevertheless, it has become fashionable to claim that** primary schools burden children with too much formal instruction and too little play."], ["stance: disagree · play secondary · literacy & numeracy = foundation", "**While** play **certainly has** a supporting role, **I disagree that** primary schools focus too much on formal learning, **as** literacy and numeracy **form the foundation on which** all later education rests."], ["basic skills · early · systematic", "**The primary reason is that** these basic skills **are best acquired** early and systematically."], ["step by step · phonics · multiplication · fall behind", "Reading and mathematics **are built** step by step, **so a child who fails to** master phonics or multiplication **often** struggles for years, **falling further behind with** every new topic."], ["Singapore · structured maths · top of TIMSS & PISA", "**It is no coincidence that** Singapore, **whose** primary schools teach mathematics in a highly structured way, **consistently ranks** at or near the top of international assessments such as TIMSS and PISA."], ["not excessive · tools for independent learning", "**Far from being** excessive, **then,** formal instruction **gives** children **the tools they need to** learn independently."], ["Q2: structure helps disadvantaged pupils most", "**Moreover,** structured lessons **tend to benefit** disadvantaged pupils **the most**."], ["affluent homes vs no books · free play · attainment gap", "Children from affluent, well-educated families **often** absorb vocabulary and number sense at home, **whereas** those without such advantages **depend almost entirely on** school; **if** classroom time **were** largely given over to free play, **it is precisely these children who would** leave primary school unable to read well, **widening** an already troubling attainment gap."], ["concession: creativity · cooperation · cannot sit still all day", "**Admittedly,** play **can foster** creativity, cooperation and enthusiasm, **and** young children **cannot be expected to** sit still all day."], ["rebuttal: structured activities · clear goals · free play at break", "**However,** these benefits **are best achieved through** structured activities with clear learning goals, such as maths games or reading role-plays, **rather than** unguided play, **which belongs** in the playground."], ["restate: not overemphasised · play supports, not replaces", "**In conclusion, I do not believe that** primary schools overemphasise formal learning; play **is valuable, but it should** support, **not** replace, the teaching of core skills."], ["without basics · creative child · uphill struggle", "**Without** a firm grasp of the basics, **even the most** imaginative child **will find** later learning an uphill struggle."]], "vocab": [["rote memorisation", "死記硬背"], ["genuine comprehension", "真正的理解"], ["unstructured play", "非結構化的（自由）遊戲"], ["manage frustration", "處理挫折感"], ["literacy and numeracy", "讀寫與算術能力"], ["attainment gap", "學業成就差距"], ["disadvantaged pupils", "弱勢學生"], ["an uphill struggle", "艱難的苦戰"]]};
